import { useEffect, useState } from 'react';
import type { TrackOrderResponse } from '@alfarid/api-client';
import { formatStorePrice } from '@alfarid/utils';

// Maximum delay accepted by setTimeout (32-bit signed integer); larger numbers wrap around to 0.
const MAX_TIMEOUT_MS = 2 ** 31 - 1;

/**
 * Renders InstaPay payment instructions with Cairo deadline and live expiration handler.
 */
export function InstaPayInstructions({ details, className }: {
  details: NonNullable<TrackOrderResponse['instapay']>;
  className?: string;
}) {
  const parsedDeadline = Date.parse(details.expires_at);
  const deadline = Number.isFinite(parsedDeadline) ? parsedDeadline : 0;
  const [expiredDeadline, setExpiredDeadline] = useState(() => deadline <= Date.now() ? deadline : null);

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    function checkDeadline() {
      const remaining = deadline - Date.now();
      if (remaining <= 0) {
        setExpiredDeadline(deadline);
        return;
      }
      timer = setTimeout(checkDeadline, Math.min(remaining, MAX_TIMEOUT_MS));
    }
    checkDeadline();
    return () => clearTimeout(timer);
  }, [deadline]);

  if (expiredDeadline === deadline) return <p className={className}>انتهت مهلة التحويل لهذا الطلب.</p>;

  return (
    <section aria-label="تعليمات التحويل عبر InstaPay" className={className} dir="rtl">
      <p>حوّل <strong>{formatStorePrice(Number(details.amount))}</strong> عبر InstaPay إلى <strong dir="ltr">{details.address}</strong>.</p>
      <p>التحويل متاح لحد {new Date(deadline).toLocaleString('ar-EG', { timeZone: 'Africa/Cairo' })} بتوقيت القاهرة.</p>
      <p>ابعث للمتجر رقم الطلب والرقم المرجعي للتحويل عشان يراجع الدفع.</p>
    </section>
  );
}'use client';

import { useEffect, useState } from 'react';

export function AnimatedNumber({ value, start = 0, duration = 800, trigger, format }: {
  value: number;
  start?: number;
  duration?: number;
  trigger?: number;
  format?: (value: number) => string;
}) {
  const [display, setDisplay] = useState(start);

  useEffect(() => {
    if (!Number.isFinite(value) || start === value || duration <= 0 ||
      window.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      setDisplay(value);
      return;
    }
    let frame: number;
    const started = performance.now();
    setDisplay(start);
    function tick(now: number) {
      const progress = Math.min(1, (now - started) / duration);
      setDisplay(progress === 1 ? value : start + (value - start) * (1 - (1 - progress) ** 3));
      if (progress < 1) frame = requestAnimationFrame(tick);
    }
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [value, start, duration, trigger]);

  const shown = Number.isInteger(value) ? Math.round(display) : display;
  return <>{format ? format(shown) : String(shown === value ? value : Number(shown.toFixed(3)))}</>;
}'use client';
import React, { useRef, useCallback, useEffect } from 'react';
import { BIRKIN_IMG_DATA } from '../assets/birkinHalftone';

export function AuthHalftone() {
  const gridStep = 7;
  // Canvas refs
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const birkinPixelsRef = useRef<Uint8ClampedArray | null>(null);
  const renderCanvasRef = useRef<() => void>(() => {});
  const mousePosRef = useRef({ x: -1000, y: -1000, isHovering: false });

  const W = 560;
  const H = 640;

  // Canvas drawing routine
  const renderCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, W, H);

    const activePixels = birkinPixelsRef.current;
    if (!activePixels) return;

    const step = gridStep;
    const half = step / 2;
    const { x: mx, y: my, isHovering: isHover } = mousePosRef.current;

    ctx.fillStyle = '#09090b';

    for (let y = Math.floor(half); y < H; y += step) {
      for (let x = Math.floor(half); x < W; x += step) {
        const idx = (y * W + x) * 4;
        const luma = activePixels[idx] / 255.0;
        const dark = 1.0 - luma;
        if (dark < 0.06) continue;

        let drawX = x;
        let drawY = y;
        let scaleBoost = 1.0;

        if (isHover) {
          const dx = x - mx;
          const dy = y - my;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 110) {
            const factor = 1.0 - dist / 110.0;
            drawX += (dx / (dist + 1)) * factor * 2.2;
            drawY += (dy / (dist + 1)) * factor * 2.2;
            scaleBoost = 1.0 + factor * 0.16;
          }
        }

        const r = Math.pow(dark, 0.92) * (step * 0.68) * scaleBoost;
        if (r < 0.45) continue;

        // Diamond dot
        ctx.beginPath();
        ctx.moveTo(drawX, drawY - r);
        ctx.lineTo(drawX + r, drawY);
        ctx.lineTo(drawX, drawY + r);
        ctx.lineTo(drawX - r, drawY);
        ctx.closePath();
        ctx.fill();

        // White micro center dot
        if (dark > 0.76 && r > 2.4) {
          const ir = (dark - 0.74) * (step * 0.3);
          if (ir >= 0.7) {
            ctx.save();
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(drawX, drawY, ir, 0, Math.PI * 2);
            ctx.fill();
            ctx.restore();
          }
        }
      }
    }
  }, []);

  useEffect(() => {
    renderCanvasRef.current = renderCanvas;
    renderCanvas();
  }, [renderCanvas]);

  // Extract pixel buffers on mount
  useEffect(() => {
    const offCanvas = document.createElement('canvas');
    offCanvas.width = W;
    offCanvas.height = H;
    const offCtx = offCanvas.getContext('2d', { willReadFrequently: true });
    if (!offCtx) return;

    const extract = (img: HTMLImageElement) => {
      offCtx.fillStyle = '#ffffff';
      offCtx.fillRect(0, 0, W, H);
      offCtx.drawImage(img, 0, 0, W, H);
      return offCtx.getImageData(0, 0, W, H).data;
    };

    const bImg = new Image();
    bImg.onload = () => {
      birkinPixelsRef.current = extract(bImg);
      renderCanvasRef.current();
    };
    bImg.src = BIRKIN_IMG_DATA;

    return () => {
      bImg.onload = null;
    };
  }, []);

  // Pointer tracking
  const handlePointerMove = (clientX: number, clientY: number) => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches || !window.matchMedia('(hover: hover) and (pointer: fine)').matches) return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    mousePosRef.current = {
      x: ((clientX - rect.left) / rect.width) * W,
      y: ((clientY - rect.top) / rect.height) * H,
      isHovering: true,
    };
    requestAnimationFrame(renderCanvas);
  };

  const handlePointerLeave = () => {
    mousePosRef.current.isHovering = false;
    requestAnimationFrame(renderCanvas);
  };

  return (
    <canvas
      ref={canvasRef}
      width={W}
      height={H}
      aria-hidden="true"
      onMouseMove={(e) => handlePointerMove(e.clientX, e.clientY)}
      onMouseLeave={handlePointerLeave}
      onTouchMove={(e) => {
        if (e.touches[0]) handlePointerMove(e.touches[0].clientX, e.touches[0].clientY);
      }}
    />
  );
}import React from 'react';
import { cn } from '../lib/utils';

export interface BadgeProps extends React.HTMLAttributes<HTMLSpanElement> {
  variant?: 'default' | 'success' | 'warning' | 'danger' | 'info';
}

export function Badge({ className, variant = 'default', children, ...props }: BadgeProps) {
  const variantStyles = {
    default: 'bg-zinc-100 text-zinc-800 border-zinc-200',
    success: 'bg-emerald-50 text-emerald-700 border-emerald-200',
    warning: 'bg-amber-50 text-amber-700 border-amber-200',
    danger: 'bg-rose-50 text-rose-700 border-rose-200',
    info: 'bg-sky-50 text-sky-700 border-sky-200',
  };

  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium',
        variantStyles[variant],
        className
      )}
      {...props}
    >
      {children}
    </span>
  );
}'use client';

import { createContext, useCallback, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { DEFAULT_BRANDING, type BrandIdentity } from '../lib/brand-identity';
export type { BrandIdentity } from '../lib/brand-identity';

const BrandingContext = createContext({ branding: DEFAULT_BRANDING, refreshBranding: async () => {} });

export function BrandingProvider({ children, loadBranding, initialBranding = DEFAULT_BRANDING, titleSuffix = '', manageHead = true, pollIntervalMs = 60_000 }: {
  children: ReactNode;
  loadBranding: (signal?: AbortSignal) => Promise<BrandIdentity>;
  initialBranding?: BrandIdentity;
  titleSuffix?: string;
  manageHead?: boolean;
  pollIntervalMs?: number;
}) {
  const [branding, setBranding] = useState(initialBranding);
  const controller = useRef<AbortController | null>(null);
  const pending = useRef<Promise<void> | null>(null);
  const lastAttempt = useRef(-Infinity);
  const refresh = useCallback(async (force = false): Promise<void> => {
    if (pending.current && !controller.current?.signal.aborted) {
      await pending.current;
      if (force) await refresh(true);
      return;
    }
    if (!force && !controller.current?.signal.aborted && Date.now() - lastAttempt.current < 30_000) return;
    lastAttempt.current = Date.now();
    const requestController = new AbortController();
    controller.current = requestController;
    const request = (async () => {
      try {
        const next = await loadBranding(requestController.signal);
        if (!requestController.signal.aborted) setBranding({ ...DEFAULT_BRANDING, ...next, name: next.name?.trim() || DEFAULT_BRANDING.name });
      } catch (error) {
        if (!requestController.signal.aborted) console.warn('Brand identity update failed; keeping the last known identity.', error instanceof Error ? error.message : 'Unknown error');
      }
    })();
    pending.current = request;
    await request;
    if (pending.current === request) pending.current = null;
  }, [loadBranding]);
  const refreshBranding = useCallback(() => refresh(true), [refresh]);

  useEffect(() => {
    void refresh();
    const refreshVisible = () => { if (document.visibilityState === 'visible') void refresh(); };
    const timer = pollIntervalMs > 0 ? setInterval(refreshVisible, pollIntervalMs) : null;
    window.addEventListener('focus', refreshVisible);
    document.addEventListener('visibilitychange', refreshVisible);
    return () => {
      controller.current?.abort();
      if (timer !== null) clearInterval(timer);
      window.removeEventListener('focus', refreshVisible);
      document.removeEventListener('visibilitychange', refreshVisible);
    };
  }, [refresh, pollIntervalMs]);

  useEffect(() => {
    if (manageHead) document.title = titleSuffix ? `${branding.name} | ${titleSuffix}` : branding.name;
  }, [branding.name, titleSuffix, manageHead]);

  useEffect(() => {
    if (!manageHead) return;
    const existing = document.head.querySelector<HTMLLinkElement>('link[data-brand-icon]');
    if (!branding.logo) { existing?.remove(); return; }
    const favicon = existing ?? document.createElement('link');
    favicon.dataset.brandIcon = 'true';
    favicon.rel = 'icon';
    favicon.href = branding.logo;
    if (!favicon.isConnected) document.head.appendChild(favicon);
    return () => favicon.remove();
  }, [branding.logo, manageHead]);

  return <BrandingContext.Provider value={{ branding, refreshBranding }}>{children}</BrandingContext.Provider>;
}

export const useBranding = () => useContext(BrandingContext);

export function BrandLogo({ className = '', fallback }: { className?: string; fallback?: ReactNode }) {
  const { branding } = useBranding();
  const [failed, setFailed] = useState<string | null>(null);
  if (!branding.logo || failed === branding.logo) return <>{fallback ?? null}</>;
  return <img src={branding.logo} alt="" className={`object-contain shrink-0 ${className}`} onError={() => setFailed(branding.logo)} />;
}import React from 'react';
import { cn } from '../lib/utils';

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline' | 'danger' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  isLoading?: boolean;
}

export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant = 'primary', size = 'md', isLoading = false, children, disabled, ...props }, ref) => {
    const variantStyles = {
      primary: 'bg-brand-600 text-white hover:bg-brand-700 active:bg-brand-800 disabled:bg-brand-300',
      secondary: 'bg-zinc-100 text-zinc-900 hover:bg-zinc-200 active:bg-zinc-300 disabled:bg-zinc-100',
      outline: 'border border-zinc-300 text-zinc-700 hover:bg-zinc-50 active:bg-zinc-100 disabled:opacity-50',
      danger: 'bg-red-600 text-white hover:bg-red-700 active:bg-red-800 disabled:bg-red-300',
      ghost: 'text-zinc-700 hover:bg-zinc-100 active:bg-zinc-200 disabled:opacity-50',
    };

    const sizeStyles = {
      sm: 'px-3 py-1.5 text-xs rounded-md',
      md: 'px-4 py-2 text-sm rounded-lg',
      lg: 'px-6 py-3 text-base rounded-lg',
    };

    return (
      <button
        ref={ref}
        disabled={disabled || isLoading}
        className={cn(
          'inline-flex items-center justify-center font-medium transition-colors focus:outline-none focus:ring-2 focus:ring-brand-500 focus:ring-offset-2 disabled:cursor-not-allowed',
          variantStyles[variant],
          sizeStyles[size],
          className
        )}
        {...props}
      >
        {isLoading && (
          <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-current" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            />
          </svg>
        )}
        {children}
      </button>
    );
  }
);

