  }
  /* Readiness helper & Desktop Submit */
  .checkout-readiness-helper {
    margin: 14px 0 10px;
    padding: 12px 14px;
    border-radius: 12px;
    background: #fffbeb;
    border: 1px solid #fde68a;
    color: #92400e;
    font-size: 0.88rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 10px;
  }
  .checkout-readiness-btn {
    min-height: 44px;
    padding: 4px 12px;
    border-radius: 8px;
    border: 1px solid #d97706;
    background: #ffffff;
    color: #92400e;
