  -webkit-font-smoothing: antialiased;
}

.luxury-auth-page *,
.luxury-auth-page *::before,
.luxury-auth-page *::after { box-sizing: border-box; }

.luxury-auth-page ::selection { color: #fff; background: #171717; }
.luxury-auth-main { width: 100%; min-height: 100svh; }
.auth-card {
  display: grid;
  grid-template-columns: minmax(0, 44fr) minmax(0, 56fr);
  min-height: 100svh;
  background: #fff;
}

.luxury-left-col {
