.luxury-field-error,
.luxury-form-error { margin: 8px 0 0; color: #b91c1c; font-size: 13px; line-height: 1.7; }
.luxury-form-error { padding: 12px 16px; border: 1px solid #fecaca; border-radius: 12px; background: #fef2f2; }
.luxury-auth-page :is(button, a):focus-visible { outline: 2px solid #171717; outline-offset: 5px; }

.luxury-right-col {
