.as-docs li.is-rej { flex-wrap: wrap; }import React, { useState, useEffect, useRef } from 'react';
import { useApp } from './context';
import { wholesaleEndpoints, cartEndpoints, checkoutEndpoints, accountEndpoints } from '@alfarid/api-client';
import { useApi } from './data/useApi';
import { DataBoundary } from './data/DataBoundary';
import { apiError, saveBlob, pageMeta, num, day } from './data/helpers';
import { mapProduct, mapOrder, mapShippingOptions, mapQuickLookup } from './data/mappers';
import { ORDER_STATUS, PAY_METHOD, PAY_STATUS, QUOTE_STATUS } from './data/constants';
import { fmt, Money } from './data/format';
import {
  Badge, PageHead, Crumb, Panel, Empty,
  Async, Pager, Field, Modal, Banner, Qty, Thumb, Seg
} from './ui-primitives';

/* Screens 6–12: dashboard, catalog, quick order + import, cart, checkout, success. */

const QUOTE_ST = { priced_by_admin: 'priced', converted_to_order: 'converted' };

/* ---------- 6. Dashboard ---------- */
export const Dashboard = () => {
  const { go, account, dash } = useApp();
  const pct = account?.credit_limit ? Math.round(((account.used_credit ?? 0) / account.credit_limit) * 100) : 0;
  const invoices = (dash?.latest_invoices || []).map((o) => ({
    id: o.id, number: o.order_number, date: day(o.created_at),
    status: o.status, method: o.payment_method, pay: o.payment_status, total: num(o.grand_total),
  }));
  const quotes = (dash?.latest_quotations || []).map((q) => ({
    id: q.id, number: q.quotation_number, created: day(q.created_at), valid_until: q.valid_until,
    status: QUOTE_ST[q.status] || q.status, total: num(q.grand_total),
  }));
  const shortcuts = [
    ['catalog', 'fa-table-cells-large', 'الكتالوج وقائمة الأسعار', 'CATALOG'],
    ['quick', 'fa-bolt', 'طلب سريع بالـ SKU', 'QUICK ORDER'],
    ['quoteNew', 'fa-file-signature', 'طلب عرض سعر جديد', 'NEW QUOTE'],
    ['noticeNew', 'fa-money-check-dollar', 'تسجيل إشعار سداد', 'PAYMENT NOTICE'],
  ];
  return (
    <>
      <PageHead en="Dashboard" ar={<>أهلًا {String(account?.name || '').split(' ')[0]} — {account?.company}</>} />
      <Async rows={3} cols={4} empty={<Empty title="لا توجد بيانات بعد" />}>
        <div className="kpis">
          <div className="kpi is-ink">
            <span className="kpi-en">CREDIT LIMIT</span><span className="kpi-label">حد الائتمان</span>
            <span className="kpi-value">{fmt(account?.credit_limit ?? 0, 0)}<small>EGP</small></span>
          </div>
          <div className="kpi">
            <span className="kpi-en">USED CREDIT</span><span className="kpi-label">المستخدم من الائتمان</span>
            <span className="kpi-value">{fmt(account?.used_credit ?? 0, 0)}<small>EGP</small></span>
            <div className="kpi-bar"><span style={{ width: pct + '%' }} /></div>
            <span className="kpi-foot"><span className="num">{pct}%</span> من الحد</span>
          </div>
          <div className="kpi">
            <span className="kpi-en">AVAILABLE</span><span className="kpi-label">المتاح للشراء الآجل</span>
            <span className="kpi-value" style={{ color: 'var(--accent)' }}>{fmt(account?.available_credit ?? 0, 0)}<small>EGP</small></span>
          </div>
          <div className="kpi" style={{ cursor: 'pointer' }} onClick={() => go('orders')}>
            <span className="kpi-en">IN PROGRESS</span><span className="kpi-label">طلبات جاري تنفيذها</span>
            <span className="kpi-value">{account?.in_progress_orders_count ?? 0}</span>
            <span className="kpi-foot">عرض الطلبات <i className="fa-solid fa-arrow-left" style={{ fontSize: 10 }} /></span>
          </div>
        </div>

        <div className="dash-shortcuts">
          {shortcuts.map(([r, ic, l, en]) => (
            <button key={r} className="dash-sc" onClick={() => go(r)}>
              <i className={`fa-solid ${ic}`} />
              <span><b>{l}</b><small>{en}</small></span>
              <i className="fa-solid fa-arrow-left dash-sc-arrow" />
            </button>
          ))}
        </div>

        <div className="dash-tables">
          <Panel title="آخر الفواتير" en="LATEST 5 INVOICES" body={false} action={<button className="btn-link muted" onClick={() => go('invoices')}>عرض الكل</button>}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>رقم الطلب</th><th>الحالة</th><th>الدفع</th><th>السداد</th><th className="t-end">الإجمالي</th></tr></thead>
              <tbody>{invoices.slice(0, 5).map((o) => (
                <tr key={o.id} className="is-click" onClick={() => go('order', o.id)}>
                  <td><div className="strong num">{o.number}</div><div className="soft small num">{o.date}</div></td>
                  <td><Badge map={ORDER_STATUS} k={o.status} /></td>
                  <td>{PAY_METHOD[o.method]}</td>
                  <td><Badge map={PAY_STATUS} k={o.pay} /></td>
                  <td className="t-end strong num">{fmt(o.total)}</td>
                </tr>))}</tbody>
            </table></div>
          </Panel>
          <Panel title="آخر عروض الأسعار" en="LATEST 5 QUOTATIONS" body={false} action={<button className="btn-link muted" onClick={() => go('quotes')}>عرض الكل</button>}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>الرقم</th><th>الحالة</th><th>صالح حتى</th><th className="t-end">الإجمالي</th></tr></thead>
              <tbody>{quotes.slice(0, 5).map((q) => (
                <tr key={q.id} className="is-click" onClick={() => go('quote', q.id)}>
                  <td><div className="strong num">{q.number}</div><div className="soft small num">{q.created}</div></td>
                  <td><Badge map={QUOTE_STATUS} k={q.status} /></td>
                  <td className="num">{q.valid_until || '—'}</td>
                  <td className="t-end strong num">{q.total != null ? fmt(q.total) : '—'}</td>
                </tr>))}</tbody>
            </table></div>
          </Panel>
        </div>
      </Async>
    </>
  );
};

/* ---------- 7. Catalog ---------- */
export const Catalog = () => {
  const { addToCart, toast } = useApp();
  const [q, setQ] = useState('');
  const [debouncedQ, setDebouncedQ] = useState('');
  const [page, setPage] = useState(1);
  const [open, setOpen] = useState(null);
  const [exporting, setExporting] = useState(null);

  useEffect(() => {
    const t = setTimeout(() => { setDebouncedQ(q); setPage(1); }, 400);
    return () => clearTimeout(t);
  }, [q]);

  const api = useApi((signal) => wholesaleEndpoints
    .products({ search: debouncedQ || undefined, page, per_page: 24 }, signal)
    .then((r) => ({ items: (r.data || []).map(mapProduct), meta: pageMeta(r.meta) })), [debouncedQ, page]);

  const list = api.data?.items || [];
  const meta = api.data?.meta || { page: 1, pages: 1, total: 0, per: 24 };

  const doExport = async (f) => {
    setExporting(f);
    try {
      await saveBlob(wholesaleEndpoints.exportPriceList(f), `price-list.${f}`);
      toast(`تم تنزيل قائمة الأسعار ${f.toUpperCase()}`);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setExporting(null);
    }
  };

  return (
    <>
      <PageHead en="Price List" ar="كتالوج الجملة بأسعار حسابك وشرائح الكميات">
        <button className="btn-pill" onClick={() => doExport('pdf')} disabled={!!exporting}>{exporting === 'pdf' ? <span className="spin" /> : <i className="fa-regular fa-file-pdf" />} تنزيل PDF</button>
        <button className="btn-pill" onClick={() => doExport('xlsx')} disabled={!!exporting}>{exporting === 'xlsx' ? <span className="spin" /> : <i className="fa-regular fa-file-excel" />} تنزيل Excel</button>
      </PageHead>
      <section className="panel">
        <div className="toolbar">
          <div className="search"><i className="fa-solid fa-magnifying-glass" /><input className="line-input" placeholder="ابحث بالاسم أو SKU…" value={q} onChange={(e) => setQ(e.target.value)} /></div>
          <span className="soft small"><span className="num">{meta.total}</span> منتج · الأسعار شاملة خصم حسابك</span>
        </div>
        <DataBoundary api={api}>
          <Async rows={6} cols={6} isEmpty={list.length === 0} empty={<Empty icon="fa-magnifying-glass" title="مفيش نتائج" desc={q ? `مفيش منتج أو SKU يطابق «${q}».` : 'لا توجد منتجات متاحة حاليًا.'} action={q && <button className="btn-pill" onClick={() => setQ('')}>مسح البحث</button>} />}>
            <div className="tbl-wrap"><table className="tbl cat-tbl">
              <thead><tr><th>المنتج</th><th>المتغيرات</th><th>السعر الأساسي</th><th>سعرك</th><th>شرائح الكميات</th><th>المتاح</th><th></th></tr></thead>
              <tbody>{list.map((p) => {
                const v = p.variants[0];
                const stock = p.variants.reduce((a, x) => a + (x.qty || 0), 0);
                const prices = p.variants.map((x) => x.price).filter((x) => x != null);
                return (
                  <tr key={p.id}>
                    <td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{p.name_ar}</div><div className="prod-en">{p.name_en}</div></div></div></td>
                    <td><span className="num strong">{p.variants.length}</span> <span className="soft small">{p.variants.map((x) => x.label).join(' · ')}</span></td>
                    <td><span className="strike num">{fmt(p.base)}</span></td>
                    <td className="strong num">{prices.length > 1 && Math.min(...prices) !== Math.max(...prices) ? 'من ' : ''}{prices.length ? fmt(Math.min(...prices)) : '—'}</td>
                    <td>{v ? v.tiers.map(([m, pr]) => <span key={m} className="tier"><span className="num">{m}+</span> ← <b className="num">{fmt(pr, 0)}</b></span>) : '—'}</td>
                    <td>{stock === 0 ? <span className="badge danger">نفدت الكمية</span> : <span className={`num ${stock < 50 ? '' : 'strong'}`} style={stock < 50 ? { color: '#b45309', fontWeight: 600 } : null}>{stock}</span>}</td>
                    <td className="t-end"><button className="btn-pill is-dark sm" onClick={() => setOpen(p)}>اختيار الكمية</button></td>
                  </tr>);
              })}</tbody>
            </table></div>
            <Pager page={meta.page} pages={meta.pages} total={meta.total} per={meta.per} onPage={setPage} />
          </Async>
        </DataBoundary>
      </section>
      <p className="note mt-16"><i className="fa-solid fa-circle-info" />السعر النهائي لكل بند يتحسب في السلة حسب الكمية والشريحة المطبقة وقت الطلب.</p>
      {open && <VariantModal product={open} onClose={() => setOpen(null)} onAdd={(lines) => { addToCart(lines.map((l) => ({ variant_id: l.v.id, qty: l.qty }))); setOpen(null); }} />}
    </>
  );
};

export const tierPrice = (v, qty) => { let p = v.price; (v.tiers || []).forEach(([m, pr]) => { if (qty >= m) p = pr; }); return p; };

export const VariantModal = ({ product, onClose, onAdd }) => {
  const [qty, setQty] = useState(Object.fromEntries(product.variants.map((v) => [v.id, 0])));
  const lines = product.variants.filter((v) => qty[v.id] > 0).map((v) => ({ v: { ...v, product }, qty: qty[v.id] }));
  const total = lines.reduce((a, l) => a + tierPrice(l.v, l.qty) * l.qty, 0);
  const over = product.variants.some((v) => qty[v.id] > (v.qty || 0));
  return (
    <Modal wide title={product.name_ar} onClose={onClose} icon={<Thumb sm />}
      foot={<><span className="muted small" style={{ marginInlineEnd: 'auto' }}>تقديري: <Money v={total} strong /></span>
        <button className="btn-pill" onClick={onClose}>إلغاء</button>
        <button className="btn-pill is-dark" disabled={!lines.length || over} onClick={() => onAdd(lines)}><i className="fa-solid fa-cart-plus" /> إضافة للسلة {lines.length > 0 && <span className="num">({lines.reduce((a, l) => a + l.qty, 0)})</span>}</button></>}>
      <p className="prod-en" style={{ textAlign: 'right', marginTop: -10 }}>{product.name_en} · السعر الأساسي <span className="strike">{fmt(product.base)}</span></p>
      <div className="tbl-wrap mt-16"><table className="tbl">
        <thead><tr><th>المتغير</th><th>SKU / باركود</th><th>سعرك</th><th>الشرائح</th><th>المتاح</th><th>الكمية</th></tr></thead>
        <tbody>{product.variants.map((v) => {
          const q = qty[v.id]; const bad = q > (v.qty || 0);
          return (
            <tr key={v.id} className={bad ? 'is-error' : ''}>
              <td className="strong">{v.label}</td>
              <td><div className="sku">{v.sku}</div><div className="sku soft">{v.barcode}</div></td>
              <td className="strong num">{v.price != null ? fmt(q ? tierPrice(v, q) : v.price) : '—'}</td>
              <td>{(v.tiers || []).map(([m, pr]) => <span key={m} className="tier" style={q >= m ? { background: 'var(--accent)', color: '#fff', borderColor: 'var(--accent)' } : null}><span className="num">{m}+</span> <b className="num">{fmt(pr, 0)}</b></span>)}</td>
              <td className="num">{!v.qty ? <span className="badge danger">نفدت</span> : v.qty}</td>
              <td>{!v.qty ? <span className="soft small">غير متاح</span> : <><Qty value={q} onChange={(n) => setQty({ ...qty, [v.id]: n })} />{bad && <p className="f-error">المتاح <span className="num">{v.qty}</span> فقط</p>}</>}</td>
            </tr>);
        })}</tbody>
      </table></div>
    </Modal>
  );
};

/* ---------- 8–9. Quick order + Excel import ---------- */
export const QuickOrder = () => {
  const { go, toast, applyCartResponse } = useApp();
  const [tab, setTab] = useState('manual');
  const blank = () => ({ code: '', qty: '' });
  const [rows, setRows] = useState([blank()]);
  const [looked, setLooked] = useState(false);
  const [busy, setBusy] = useState(false);
  const [adding, setAdding] = useState(false);
  const [result, setResult] = useState(null);
  const [skipped, setSkipped] = useState(null);
  const set = (i, k, v) => { const r = [...rows]; r[i] = { ...r[i], [k]: v }; if (i === rows.length - 1 && v) r.push(blank()); setRows(r); setLooked(false); setResult(null); };

  const lookup = async () => {
    const items = rows.filter((r) => r.code && r.code.trim() && Number(r.qty) > 0).map((r) => {
      const code = r.code.trim();
      const isBarcode = /^[0-9]+$/.test(code) && code.length >= 8;
      return isBarcode ? { barcode: code, qty: Number(r.qty) } : { sku: code, qty: Number(r.qty) };
    });
    if (!items.length) { toast('أدخل كود وكمية لبند واحد على الأقل.'); return; }
    setBusy(true);
    try {
      const res = await wholesaleEndpoints.quickLookup(items);
      setResult(mapQuickLookup(res));
      setLooked(true);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setBusy(false);
    }
  };

  const lines = result?.data || [];
  const checkedRows = rows.filter((r) => r.code?.trim() && Number(r.qty) > 0);
  const rowState = (row) => lines[checkedRows.indexOf(row)];
  const valid = lines.filter((l) => l.found && l.in_stock);

  const addValid = async () => {
    setAdding(true);
    setSkipped(null);
    try {
      const r = await wholesaleEndpoints.quickAddToCart(valid.map((l) => ({ sku: l.sku, qty: l.qty })));
      applyCartResponse(r.cart);
      if (r.skipped?.length) setSkipped(r.skipped);
      else { toast('تمت الإضافة إلى سلة المشتريات بنجاح'); go('cart'); }
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setAdding(false);
    }
  };

  return (
    <>
      <PageHead en="Quick Order" ar="أدخل الأكواد والكميات مباشرة، أو ارفع ملف Excel">
        <Seg value={tab} onChange={setTab} options={[{ value: 'manual', label: 'إدخال مباشر', icon: 'fa-keyboard' }, { value: 'import', label: 'استيراد ملف', icon: 'fa-file-arrow-up' }]} />
      </PageHead>
      {tab === 'manual' ? (
        <div className="grid-2" style={{ gridTemplateColumns: '1fr 320px' }}>
          <section className="panel">
            <div className="toolbar">
              <span className="muted small">الصق من Excel مباشرة: عمود SKU أو باركود، ثم الكمية. حتى <span className="num">500</span> بند.</span>
              <button className="btn-link muted" onClick={() => { setRows([blank()]); setLooked(false); setResult(null); }}>مسح الكل</button>
            </div>
            {skipped?.length > 0 && <div style={{ padding: '0 24px' }}><Banner kind="warn"><b>تم تخطي {skipped.length} بند:</b> {skipped.map((s) => `${s.sku} (${ { not_found_or_inactive: 'الصنف غير موجود أو غير متاح', insufficient_stock: 'الكمية غير متاحة' }[s.reason] || s.reason})`).join('، ')}</Banner></div>}
            <div className="tbl-wrap"><table className="tbl qo-tbl">
              <thead><tr><th style={{ width: 36 }}>#</th><th style={{ width: 210 }}>SKU أو باركود</th><th style={{ width: 96 }}>الكمية</th><th>الصنف</th><th>سعر الوحدة</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
              <tbody>{rows.map((r, i) => {
                const x = looked ? rowState(r) : null;
                const st = !x ? null : !x.found ? { err: 'الصنف غير موجود' } : (x.available_qty || 0) === 0 ? { err: 'نفدت الكمية', v: x } : !x.in_stock ? { warn: `المتاح ${x.available_qty} فقط`, v: x } : { ok: true, v: x };
                return (
                  <tr key={i} className={st && (st.err ? 'is-error' : st.warn ? 'is-warn' : '')}>
                    <td className="soft num">{i + 1}</td>
                    <td><input className={`box-input ltr${st && st.err && !st.v ? ' is-invalid' : ''}`} value={r.code} placeholder="SPH-…" onChange={(e) => set(i, 'code', e.target.value)} /></td>
                    <td><input className="box-input ltr" value={r.qty} inputMode="numeric" onChange={(e) => set(i, 'qty', e.target.value.replace(/\D/g, ''))} /></td>
                    <td>{!x ? <span className="soft small">{r.code ? 'اضغط «فحص البنود»' : ''}</span> : st.v ? <><div className="strong small">{st.v.product_name} — {st.v.label || st.v.sku}</div>{st.err ? <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-exclamation" />{st.err}</p> : st.warn ? <p className="f-error" style={{ margin: 0, color: '#b45309' }}><i className="fa-solid fa-triangle-exclamation" />{st.warn}</p> : <span className="small" style={{ color: '#047857' }}><i className="fa-solid fa-check" /> متاح</span>}</> : <p className="f-error" style={{ margin: 0 }}><i className="fa-solid fa-circle-xmark" />{st.err}</p>}</td>
                    <td className="num">{x && x.unit_price != null ? fmt(x.unit_price) : '—'}</td>
                    <td className="t-end strong num">{x && x.line_total != null ? fmt(x.line_total) : '—'}</td>
                    <td>{r.code && <button className="btn-link muted" aria-label="حذف" onClick={() => { setRows(rows.filter((_, j) => j !== i)); setLooked(false); setResult(null); }}><i className="fa-solid fa-xmark" /></button>}</td>
                  </tr>);
              })}</tbody>
            </table></div>
          </section>
          <aside className="panel" style={{ position: 'sticky', top: 100 }}>
            <div className="panel-body">
              <h2 className="panel-title">ملخص الفحص</h2>
              <div className="mt-16">
                <div className="sum-row"><span>إجمالي البنود</span><strong className="num">{rows.filter((r) => r.code).length}</strong></div>
                <div className="sum-row"><span>بنود معروفة</span><strong className="num">{looked ? (result?.meta?.found ?? '—') : '—'}</strong></div>
                <div className="sum-row"><span>بنود صالحة للإضافة</span><strong className="num" style={{ color: 'var(--accent)' }}>{looked ? valid.length : '—'}</strong></div>
                <div className="sum-row"><span>بنود بها أخطاء</span><strong className="num" style={{ color: '#b91c1c' }}>{looked ? lines.filter((l) => !l.found || !l.in_stock).length : '—'}</strong></div>
                <div className="sum-total"><span>قيمة البنود الصالحة</span><span className="num">{looked ? fmt(valid.reduce((a, l) => a + (l.line_total || 0), 0)) : '—'}</span></div>
              </div>
              <button className="btn-block mt-24" onClick={lookup} disabled={busy}>{busy ? <span className="spin" /> : <i className="fa-solid fa-magnifying-glass" />} فحص البنود</button>
              <button className="btn-pill is-dark mt-8" style={{ width: '100%', justifyContent: 'center' }} disabled={!looked || !valid.length || adding} onClick={addValid}>{adding ? <span className="spin" /> : <i className="fa-solid fa-cart-plus" />} إضافة <span className="num">{valid.length}</span> بند صالح للسلة</button>
              <p className="note mt-16"><i className="fa-solid fa-circle-info" />الفحص للمعاينة فقط؛ الأسعار النهائية بتتأكد في السلة.</p>
            </div>
          </aside>
        </div>
      ) : <ImportTab />}
    </>
  );
};

const SKIP_REASON_LABEL = { not_found_or_inactive: 'الصنف غير موجود أو غير متاح', insufficient_stock: 'الكمية غير متاحة' };

const ImportTab = () => {
  const { go, applyCartResponse, toast } = useApp();
  const [stage, setStage] = useState('idle'); // idle | invalid | uploading | done
  const [file, setFile] = useState(null);
  const [report, setReport] = useState(null);
  const [err, setErr] = useState('');
  const inputRef = useRef(null);

  const pick = (f) => {
    setErr('');
    if (!f) return;
    if (f.size > 5 * 1024 * 1024) { setFile({ name: f.name }); setStage('invalid'); return; }
    setFile(f);
    setStage('ready');
  };

  const upload = async () => {
    if (!file || !(file instanceof File)) return;
    setStage('uploading');
    try {
      const r = await wholesaleEndpoints.quickImport(file);
      setReport(r);
      applyCartResponse(r.cart);
      setStage('done');
    } catch (e) {
      setErr(apiError(e).message);
      setStage('ready');
    }
  };

  return (
    <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
      <section className="panel"><div className="panel-body">
        {stage !== 'done' ? (
          <>
            <input ref={inputRef} type="file" accept=".xlsx,.xls,.csv" style={{ display: 'none' }} onChange={(e) => pick(e.target.files?.[0])} />
            <div className={`drop${stage === 'invalid' ? ' is-invalid' : ''}`} onClick={() => inputRef.current?.click()}>
              <i className="fa-solid fa-file-arrow-up" />
              <b>اسحب الملف هنا أو اضغط للاختيار</b>
              <small>XLSX · XLS · CSV — حتى <span className="num">5</span> ميجابايت</small>
            </div>
            {file && (
              <div className="file-row mt-16">
                <i className="fa-regular fa-file-excel" />
                <div className="grow"><b className="num">{file.name}</b></div>
                <button className="btn-link muted" onClick={() => { setFile(null); setStage('idle'); }}><i className="fa-solid fa-xmark" /></button>
              </div>
            )}
            {stage === 'invalid' && <p className="f-error"><i className="fa-solid fa-circle-exclamation" />حجم الملف أكبر من 5 ميجابايت. قسّم الملف وحاول تاني.</p>}
            {err && <p className="f-error"><i className="fa-solid fa-circle-exclamation" />{err}</p>}
            <Banner kind="warn"><b>الاستيراد بيضيف البنود للسلة مباشرة</b> — مش معاينة. البنود اللي فيها مشاكل هتتخطى وهيظهرلك سببها.</Banner>
            <div className="row mt-16" style={{ justifyContent: 'flex-end' }}>
              <button className="btn-pill is-dark" disabled={stage !== 'ready'} onClick={upload}>{stage === 'uploading' ? <><span className="spin" /> جارٍ الاستيراد…</> : <><i className="fa-solid fa-upload" /> استيراد وإضافة للسلة</>}</button>
            </div>
          </>
        ) : (
          <>
            <div className="row" style={{ gap: 16 }}>
              <div className="modal-icon"><i className="fa-solid fa-check" /></div>
              <div><h2 className="panel-title">تم الاستيراد</h2><p className="muted small" style={{ margin: '4px 0 0' }}><span className="num">{file?.name}</span></p></div>
            </div>
            <div className="imp-stats mt-24">
              <div><span className="num">{report?.added?.length ?? 0}</span><small>بند تمت إضافته</small></div>
              <div className="is-warn"><span className="num">{report?.skipped?.length ?? 0}</span><small>بند تم تخطيه</small></div>
            </div>
            {(report?.skipped?.length > 0) && (
              <>
                <h3 className="f-label mt-24">البنود المتخطاة وأسبابها</h3>
                <table className="tbl"><thead><tr><th>SKU</th><th>الكمية</th><th>السبب</th></tr></thead>
                  <tbody>{report.skipped.map((s, i) => <tr key={i}><td className="sku">{s.sku}</td><td className="num">{s.qty || '—'}</td><td style={{ color: '#b91c1c' }}>{SKIP_REASON_LABEL[s.reason] || s.reason}</td></tr>)}</tbody></table>
              </>
            )}
            <div className="row mt-24"><button className="btn-pill is-dark" onClick={() => go('cart')}><i className="fa-solid fa-bag-shopping" /> فتح السلة</button><button className="btn-pill" onClick={() => { setStage('idle'); setFile(null); setReport(null); }}>استيراد ملف آخر</button></div>
          </>
        )}
      </div></section>
      <aside className="panel"><div className="panel-body">
        <h2 className="panel-title">ترتيب الأعمدة</h2>
        <p className="muted small" style={{ lineHeight: 1.8 }}>العمود الأول SKU أو الباركود، والثاني الكمية. صف العناوين اختياري.</p>
        <table className="tbl imp-sample ltr"><thead><tr><th>A · sku</th><th>B · qty</th></tr></thead>
          <tbody><tr><td className="sku">SPH-TT-001-BLK</td><td className="num">24</td></tr></tbody></table>
      </div></aside>
    </div>
  );
};

/* ---------- 10. Cart ---------- */
const CartRow = ({ line, onCommit, onRemove, busy }) => {
  const [qty, setQty] = useState(line.qty);
  const timer = useRef(null);
  useEffect(() => { setQty(line.qty); }, [line.qty]);
  const change = (n) => {
    setQty(n);
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => { if (n !== line.qty) onCommit(line, n); }, 400);
  };
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current); }, []);
  const shortage = !line.available || (line.max_qty > 0 && line.qty > line.max_qty);
  return (
    <div className={`cart-row${shortage ? ' is-bad' : ''}`}>
      <Thumb />
      <div className="cart-info">
        <div className="prod-name">{line.name}</div>
        <div className="cart-meta"><span>المتغير</span><b>{line.label}</b><span>SKU</span><b className="sku">{line.sku}</b><span>سعر الوحدة</span><b className="num">{fmt(line.unit)}{line.base != null && line.unit != null && line.unit < line.base && <span className="tier" style={{ marginInlineStart: 8 }}>شريحة كمية</span>}</b></div>
        {!line.priced && <p className="f-error" style={{ margin: '4px 0 0' }}>الصنف غير مسعّر — أزله من السلة للمتابعة.</p>}
        <div className="row mt-8"><Qty value={qty} min={1} onChange={change} />{shortage && <span className="f-error" style={{ margin: 0 }}>الكمية أكبر من المتاح. عدّل الكمية للمتابعة.</span>}</div>
      </div>
      <div className="cart-right">
        <span className="strong num">{fmt(line.line_total)}</span>
        <button className="btn-link muted" disabled={busy} onClick={() => onRemove(line)}>حذف</button>
      </div>
    </div>
  );
};

export const Cart = () => {
  const { cart, cartApi, go, toast, applyCartResponse } = useApp();
  const [coupon, setCoupon] = useState('');
  const [cErr, setCErr] = useState('');
  const [confirmClear, setConfirmClear] = useState(false);
  const [busy, setBusy] = useState(false);
  const lines = cart?.lines || [];
  const totals = cart?.totals || {};
  const discount = num(totals.pricing_discount ?? 0) + num(totals.coupon_discount ?? 0);

  const commit = async (line, qty) => {
    if (!qty || qty < 1) return;
    setBusy(true);
    try {
      const c = await cartEndpoints.update(line.id, qty, null);
      applyCartResponse(c);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setBusy(false);
    }
  };
  const remove = async (line) => {
    setBusy(true);
    try {
      const c = await cartEndpoints.remove(line.id, null);
      applyCartResponse(c);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setBusy(false);
    }
  };
  const clear = async () => {
    setBusy(true);
    try {
      const c = await cartEndpoints.clear(null);
      applyCartResponse(c);
      setConfirmClear(false);
    } catch (e) {
      toast(apiError(e).message);
    } finally {
      setBusy(false);
    }
  };
  const apply = async () => {
    if (!coupon.trim()) return;
    setCErr('');
    try {
      const r = await cartEndpoints.applyCoupon(coupon.trim(), null);
      applyCartResponse(r.cart);
    } catch (e) {
      setCErr(apiError(e).message);
    }
  };
  const unapply = async () => {
    try {
      const c = await cartEndpoints.removeCoupon(null);
      applyCartResponse(c);
      setCoupon('');
    } catch (e) {
      toast(apiError(e).message);
    }
  };

  const blocked = lines.some((l) => !l.priced || !l.available || (l.max_qty > 0 && l.qty > l.max_qty));

  if (cartApi.state !== 'ready') return <DataBoundary api={cartApi}><Async rows={4} cols={4} /></DataBoundary>;

  if (!lines.length) return (<><PageHead en="Your Bag" ar="سلة المشتريات" /><section className="panel"><Empty icon="fa-bag-shopping" title="السلة فاضية" desc="ضيف منتجات من الكتالوج أو استخدم الطلب السريع." action={<div className="row"><button className="btn-pill is-dark" onClick={() => go('catalog')}>تصفح الكتالوج</button><button className="btn-pill" onClick={() => go('quick')}>طلب سريع</button></div>} /></section></>);
  return (
    <>
      <PageHead en="Your Bag" ar={<>سلة المشتريات · <span className="num">{lines.length}</span> بند</>}>
        <button className="btn-pill is-danger" onClick={() => setConfirmClear(true)}><i className="fa-regular fa-trash-can" /> تفريغ السلة</button>
      </PageHead>
      <div className="grid-2" style={{ gridTemplateColumns: '1.35fr 1fr', gap: 48 }}>
        <section>
          {lines.map((l) => <CartRow key={l.id} line={l} onCommit={commit} onRemove={remove} busy={busy} />)}
        </section>
        <aside style={{ position: 'sticky', top: 100, alignSelf: 'start' }}>
          <h2 className="checkout-heading">ملخص الطلب</h2>
          <div className="promo">
            {totals.coupon_code ? (
              <span className="promo-chip">كوبون <b className="num">{totals.coupon_code}</b> مطبق<button onClick={unapply} aria-label="إزالة">✕</button></span>
            ) : (<>
              <div style={{ flex: 1 }}><input className={`line-input ltr${cErr ? ' is-invalid' : ''}`} placeholder="كود الخصم" value={coupon} onChange={(e) => { setCoupon(e.target.value); setCErr(''); }} />{cErr && <p className="f-error">{cErr}</p>}</div>
              <button className="btn-soft" onClick={apply}>تطبيق</button></>)}
          </div>
          <div className="sum-row"><span>قيمة المنتجات</span><strong className="num">{fmt(totals.subtotal)}</strong></div>
          <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{discount ? '− ' + fmt(discount) : '—'}</strong></div>
          <div className="sum-row"><span>الشحن والضريبة</span><span className="soft small">تُحسب في الخطوة التالية</span></div>
          <div className="sum-total"><span>الإجمالي المبدئي</span><span className="num">{fmt(totals.total)}</span></div>
          <button className="btn-block mt-24" disabled={blocked || busy} onClick={() => go('checkout')}>متابعة لإتمام الطلب <i className="fa-solid fa-arrow-left" /></button>
          <button className="btn-link muted mt-16" onClick={() => go('catalog')}><i className="fa-solid fa-arrow-right" /> كمّل التسوق</button>
        </aside>
      </div>
      {confirmClear && <Modal title="تفريغ السلة؟" onClose={() => setConfirmClear(false)} icon={<div className="modal-icon is-warn"><i className="fa-solid fa-trash-can" /></div>}
        foot={<><button className="btn-pill" onClick={() => setConfirmClear(false)}>إلغاء</button><button className="btn-pill is-danger" disabled={busy} onClick={clear}>تفريغ</button></>}>
        <p className="muted">هيتم حذف كل البنود (<span className="num">{lines.length}</span>) من السلة. الإجراء ده مش ممكن التراجع عنه.</p></Modal>}
    </>
  );
};

/* ---------- 11. Checkout ---------- */
const FIELD_MAP = { recipient_name: 'name', recipient_phone: 'phone', recipient_email: 'email', city_id: 'city', shipping_address_line: 'address', shipping_notes: 'notes' };

export const Checkout = () => {
  const { cart, cartApi, go, toast, account, loadCart, refreshAccount, setLastOrder } = useApp();
  const initialApi = useApi(async () => {
    const [addresses, cities] = await Promise.all([accountEndpoints.addresses(), checkoutEndpoints.cities()]);
    return { addresses, cities };
  }, []);
  const addrs = initialApi.data?.addresses || [];
  const cities = initialApi.data?.cities || [];
  const [addrId, setAddrId] = useState(null);
  const [f, setF] = useState({ name: '', phone: '', email: '', city_id: '', address: '', notes: '' });
  const [pay, setPay] = useState('credit');
  const [ship, setShip] = useState('standard');
  const [preview, setPreview] = useState(null);
  const [options, setOptions] = useState([]);
  const [methods, setMethods] = useState([]);
  const [errs, setErrs] = useState({});
  const [creditErr, setCreditErr] = useState('');
  const [step, setStep] = useState('form'); // form | changed | submitting
  const [prevTotal, setPrevTotal] = useState(null);
  const [previewState, setPreviewState] = useState('loading');
  const [previewAttempt, setPreviewAttempt] = useState(0);
  const submitting = useRef(false);
  const idemKey = useRef(typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now()));

  useEffect(() => {
    if (initialApi.state !== 'ready') return;
      const d = addrs.find((x) => x.is_default) || addrs[0];
      if (d) {
        setAddrId(d.id);
        setF((s) => ({ ...s, name: s.name || account?.name || '', phone: s.phone || account?.phone || '', city_id: d.city_id, address: d.address_line }));
      } else {
        setF((s) => ({ ...s, name: s.name || account?.name || '', phone: s.phone || account?.phone || '' }));
      }
  }, [initialApi.data]);

  useEffect(() => {
    setPreview(null);
    if (!f.city_id) { setOptions([]); setMethods([]); return; }
    const ctrl = new AbortController();
    setPreviewState('loading');
    checkoutEndpoints.shippingOptions({ city_id: Number(f.city_id), payment_method: pay }, null, ctrl.signal)
      .then(mapShippingOptions)
      .then((r) => { if (!ctrl.signal.aborted) { setPreview(r.preview); setOptions(r.options || []); setMethods(r.payment_methods || []); setPreviewState('ready');
        if (r.payment_methods?.length && !r.payment_methods.includes(pay)) setPay(r.payment_methods[0]);
      } })
      .catch(() => { if (!ctrl.signal.aborted) setPreviewState('error'); });
    return () => ctrl.abort();
  }, [f.city_id, pay, previewAttempt]);

  const overCredit = pay === 'credit' && preview && account && preview.grand_total > Number(account.available_credit ?? 0);
  const walletShort = preview && account && Number(account.wallet ?? 0) < Number(preview.grand_total ?? 0);

  const pickAddr = (a) => {
    if (!a) { setAddrId(0); setF({ ...f, city_id: '', address: '' }); return; }
    setAddrId(a.id);
    setF({ ...f, city_id: a.city_id, address: a.address_line });
  };

  const mapFieldErrors = (fields) => {
    const e = {};
    Object.entries(fields || {}).forEach(([k, msgs]) => {
      const local = FIELD_MAP[k] || k;
      e[local] = Array.isArray(msgs) ? msgs[0] : String(msgs);
    });
    return e;
  };

  const submit = async () => {
    if (submitting.current) return;
    const e = {};
    if (!String(f.name).trim()) e.name = 'اسم المستلم مطلوب.';
    if (!String(f.phone).trim()) e.phone = 'رقم موبايل المستلم مطلوب.';
    if (!f.city_id) e.city = 'اختر المدينة.';
    if (!String(f.address).trim()) e.address = 'العنوان التفصيلي مطلوب.';
    setErrs(e);
    if (Object.keys(e).length) return;
    if (!preview || previewState !== 'ready' || !methods.includes(pay)) { toast('جارٍ حساب الشحن… حاول مرة أخرى.'); return; }
    submitting.current = true;
    setCreditErr('');
    setStep('submitting');
    const payload = {
      recipient_name: f.name, recipient_phone: f.phone, recipient_email: f.email || undefined,
      city_id: Number(f.city_id), shipping_address_line: f.address, shipping_notes: f.notes || undefined,
      payment_method: pay, expected_total: preview.grand_total,
    };
    try {
      const res = await checkoutEndpoints.place(payload, null, idemKey.current);
      setLastOrder(mapOrder(res.data));
      await loadCart();
      refreshAccount();
      go('success', res.data.id);
    } catch (err) {
      const info = apiError(err);
      if (info.code === 'price_changed') {
        setPrevTotal(preview.grand_total);
        try {
          const r = mapShippingOptions(await checkoutEndpoints.shippingOptions({ city_id: Number(f.city_id), payment_method: pay }, null));
          setPreview(r.preview); setOptions(r.options || []); setMethods(r.payment_methods || []);
        } catch (_) { setPreview(null); setPreviewState('error'); }
        setStep('changed');
      } else if (info.code === 'credit_limit_exceeded') {
        setCreditErr(info.message);
        setStep('form');
      } else {
        setErrs(mapFieldErrors(info.fields));
        if (!Object.keys(info.fields).length) toast(info.message);
        setStep('form');
      }
    } finally {
      submitting.current = false;
    }
  };

  const inp = (k, props = {}) => <input className={`line-input${errs[k] ? ' is-invalid' : ''}`} value={f[k]} onChange={(e) => { setF({ ...f, [k]: e.target.value }); setErrs({ ...errs, [k]: null }); }} {...props} />;
  const lines = cart?.lines || [];

  if (cartApi.state !== 'ready') return <DataBoundary api={cartApi}><Async rows={4} cols={4} /></DataBoundary>;
  if (initialApi.state !== 'ready') return <DataBoundary api={initialApi}><Async rows={4} cols={4} /></DataBoundary>;

  return (
    <>
      <PageHead en="Checkout" crumb={<Crumb items={[{ label: 'السلة', go: () => go('cart') }, { label: 'إتمام الطلب' }]} />}>
        <button className="btn-pill" onClick={() => go('cart')}><i className="fa-solid fa-arrow-right" /> العودة للسلة</button>
      </PageHead>
      <ol className="steps"><li className="step is-done"><span className="step-dot">✓</span>السلة</li><li className="step is-now"><span className="step-dot">2</span>الشحن والدفع</li><li className="step"><span className="step-dot">3</span>التأكيد</li></ol>
      {step === 'changed' && <div className="mb-24"><Banner kind="warn" icon="fa-arrows-rotate"><b>تغيّر الإجمالي قبل التأكيد.</b> الإجمالي الجديد <b className="num">{fmt(preview?.grand_total)} EGP</b>{prevTotal != null && <> بدل <span className="num">{fmt(prevTotal)} EGP</span></>} — راجعه واضغط تأكيد.</Banner></div>}
      {creditErr && <div className="mb-24"><Banner kind="error">{creditErr}</Banner></div>}
      <div className="grid-2" style={{ gridTemplateColumns: '1.22fr .95fr', gap: 64 }}>
        <div>
          <fieldset className="ck-block" disabled={step === 'submitting'}>
            <h2 className="checkout-heading">عنوان التسليم</h2>
            <div className="addr-picks">
              {addrs.map((a) => (
                <button key={a.id} type="button" className={`addr-pick${addrId === a.id ? ' is-on' : ''}`} onClick={() => pickAddr(a)}>
                  <b>{a.city_name_ar || ''}{a.is_default && <span className="badge accent" style={{ marginInlineStart: 8 }}>افتراضي</span>}</b>
                  <span>{a.address_line}</span>
                </button>
              ))}
              <button type="button" className={`addr-pick${addrId === 0 ? ' is-on' : ''}`} onClick={() => pickAddr(null)}><b>عنوان آخر</b><span>إدخال يدوي لهذا الطلب</span></button>
            </div>
            <div className="fields mt-24">
              <Field label="اسم المستلم" req error={errs.name}>{inp('name')}</Field>
              <Field label="تليفون المستلم" req error={errs.phone}>{inp('phone', { dir: 'ltr', inputMode: 'tel', style: { textAlign: 'right' } })}</Field>
              <Field label="بريد المستلم" opt error={errs.email}>{inp('email', { dir: 'ltr', placeholder: 'name@company.com', style: { textAlign: 'right' } })}</Field>
              <Field label="المدينة" req error={errs.city}>
                <select className={`line-input${errs.city ? ' is-invalid' : ''}`} value={f.city_id} onChange={(e) => { setF({ ...f, city_id: e.target.value ? Number(e.target.value) : '' }); setErrs({ ...errs, city: null }); }}>
                  <option value="">اختر المدينة</option>{cities.map((c) => <option key={c.id} value={c.id}>{c.name_ar}</option>)}
                </select></Field>
              <Field label="العنوان التفصيلي" req span error={errs.address}>{inp('address', { placeholder: 'الشارع، رقم المبنى، علامة مميزة' })}</Field>
              <Field label="ملاحظات الشحن" opt span><textarea className="line-input" rows="2" value={f.notes} placeholder="مواعيد الاستلام، رقم بديل…" onChange={(e) => setF({ ...f, notes: e.target.value })} /></Field>
            </div>
          </fieldset>
          <fieldset className="ck-block" disabled={step === 'submitting'}>
            <h2 className="checkout-heading">خيارات الشحن</h2>
            {previewState === 'error' && <Banner kind="error" action={<button className="btn-pill sm" onClick={() => setPreviewAttempt((n) => n + 1)}>إعادة المحاولة</button>}>تعذر تحميل تكلفة الشحن.</Banner>}
            <div className="radio-list">
              {(options.length ? options : [{ key: 'standard', label: 'شحن قياسي', cost: preview?.shipping }]).filter((o) => o.key === 'standard').map((o) => (
                <label key={o.key} className="radio-row"><span className="radio-left"><input type="radio" checked={ship === o.key} onChange={() => setShip(o.key)} /><span><span className="radio-title">{o.label || 'شحن قياسي'}</span><span className="radio-desc">{o.estimated_days || ''}</span></span></span><span className="radio-price num">{fmt(o.cost)}</span></label>))}
            </div>
          </fieldset>
          <fieldset className="ck-block" disabled={step === 'submitting'}>
            <h2 className="checkout-heading">طريقة الدفع</h2>
            <div className="radio-list">
              {methods.map((m) => {
                if (m === 'credit') return (
                  <label key={m} className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'credit'} onChange={() => setPay('credit')} /><span><span className="radio-title">آجل على الحساب</span><span className="radio-desc">المتاح حاليًا <span className="num">{fmt(account?.available_credit ?? 0)}</span> EGP · متاح لحسابك حسب سياسة الائتمان</span></span></span><span className="badge accent">مسموح لحسابك</span></label>);
                if (m === 'cod') return (
                  <label key={m} className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'cod'} onChange={() => setPay('cod')} /><span><span className="radio-title">الدفع عند الاستلام</span><span className="radio-desc">رسوم تحصيل <span className="num">{fmt(preview?.cod_fee ?? 0)}</span> EGP</span></span></span><span className="radio-price num">+{fmt(preview?.cod_fee ?? 0)}</span></label>);
                if (m === 'bank_transfer') return (
                  <label key={m} className="radio-row"><span className="radio-left"><input type="radio" checked={pay === 'bank_transfer'} onChange={() => setPay('bank_transfer')} /><span><span className="radio-title">تحويل بنكي مقدم</span><span className="radio-desc">سجّل إشعار السداد بعد التحويل</span></span></span></label>);
                if (m === 'wallet') return (
                  <label key={m} className={`radio-row${walletShort ? ' is-disabled' : ''}`}><span className="radio-left"><input type="radio" disabled={walletShort} checked={pay === 'wallet'} onChange={() => setPay('wallet')} /><span><span className="radio-title">المحفظة</span><span className="radio-desc">{walletShort ? <>الرصيد <span className="num">{fmt(account?.wallet ?? 0)}</span> غير كافٍ لهذا الطلب</> : <>الرصيد <span className="num">{fmt(account?.wallet ?? 0)}</span> EGP</>}</span></span></span></label>);
                return null;
              })}
            </div>
            {overCredit && <div className="mt-16"><Banner kind="error">الإجمالي أكبر من المتاح للشراء الآجل. قلل الكمية أو اختر طريقة دفع أخرى.</Banner></div>}
          </fieldset>
        </div>
        <aside style={{ position: 'sticky', top: 100, alignSelf: 'start' }}>
          <h2 className="checkout-heading">ملخص الطلب</h2>
          <div className="ck-items">
            {lines.map((l) => (
              <div key={l.id} className="ck-item"><Thumb sm /><div style={{ flex: 1, minWidth: 0 }}><div className="strong small">{l.name}</div><div className="soft small">{l.label} · <span className="num">×{l.qty}</span></div></div><span className="num strong small">{fmt(l.line_total)}</span></div>))}
          </div>
          <div className="sum-row"><span>قيمة المنتجات</span><strong className="num">{fmt(preview?.items_total)}</strong></div>
          <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{preview?.coupon_discount ? '− ' + fmt(preview.coupon_discount) : '—'}</strong></div>
          <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(preview?.shipping)}</strong></div>
          <div className="sum-row"><span>الضريبة</span><strong className="num">{fmt(preview?.tax ?? 0)}</strong></div>
          {Number(preview?.cod_fee ?? 0) > 0 && <div className="sum-row"><span>رسوم التحصيل</span><strong className="num">{fmt(preview.cod_fee)}</strong></div>}
          <div className="sum-total"><span>الإجمالي النهائي</span><span className="num">{fmt(preview?.grand_total)}</span></div>
          <button className="btn-block mt-24" disabled={overCredit || (pay === 'wallet' && walletShort) || !lines.length || step === 'submitting' || !preview || previewState !== 'ready' || !methods.includes(pay)} onClick={submit}>{step === 'submitting' ? <><span className="spin" /> جاري إتمام الطلب…</> : step === 'changed' ? 'تأكيد الإجمالي الجديد وإتمام الطلب' : 'إتمام الطلب'}</button>
          <p className="note mt-16"><i className="fa-solid fa-lock" />الأسعار والإجمالي النهائي بيتحسبوا من الخادم لحظة التأكيد.</p>
        </aside>
      </div>
    </>
  );
};

/* ---------- 12. Success ---------- */
export const OrderSuccess = () => {
  const { lastOrder, go, route } = useApp();
  const api = useApi((signal) => lastOrder
    ? Promise.resolve(lastOrder)
    : wholesaleEndpoints.order(route.id, signal).then(mapOrder), [lastOrder?.id, route.id]);
  const o = lastOrder || api.data;
  if (!o) {
    return (
      <DataBoundary api={api}>
        <Async rows={4} cols={4} empty={<Empty icon="fa-box-open" title="لا يوجد طلب لعرضه" />} />
      </DataBoundary>
    );
  }
  return (
    <div className="success-wrap"><div className="order-card">
      <div className="modal-icon" style={{ width: 64, height: 64, fontSize: 26 }}><i className="fa-solid fa-check" /></div>
      <h1 className="success-title">ORDER PLACED</h1>
      <p className="muted" style={{ margin: '0 0 6px' }}>تم استلام طلبك بنجاح</p>
      <p className="success-num num">{o.number}</p>
      <div className="row" style={{ justifyContent: 'center', gap: 8, marginBottom: 24 }}><Badge map={ORDER_STATUS} k={o.status} /><Badge map={PAY_STATUS} k={o.pay} /></div>
      <div style={{ textAlign: 'start' }}>
        {(o.items || []).map((it) => <div key={it.sku || it.id} className="ck-item"><Thumb sm /><div style={{ flex: 1 }}><div className="strong small">{it.name}</div><div className="sku">{it.sku}</div></div><span className="num small">×{it.qty}</span></div>)}
        <div className="sum-row"><span>طريقة الدفع</span><strong>{PAY_METHOD[o.method]}</strong></div>
        <div className="sum-row"><span>عنوان التسليم</span><strong style={{ textAlign: 'left' }}>{o.city} — {o.address}</strong></div>
        <div className="sum-total"><span>الإجمالي</span><span className="num">{fmt(o.total)}</span></div>
      </div>
      <div className="row mt-24" style={{ justifyContent: 'center' }}>
        <button className="btn-pill is-dark" onClick={() => go('order', o.id)}>فتح الطلب</button>
        <button className="btn-pill" onClick={() => go('catalog')}>الرجوع للكتالوج</button>
      </div>
    </div></div>
  );
};import React, { useState, useEffect } from 'react';
import { useApp } from './context';
import { wholesaleEndpoints, accountEndpoints, defaultApiClient } from '@alfarid/api-client';
import { useApi } from './data/useApi';
import { DataBoundary } from './data/DataBoundary';
import { apiError, pageMeta, saveBlob, allPages } from './data/helpers';
import { mapOrder, mapQuote, mapReturn } from './data/mappers';
import { validateReturnFiles } from './data/validation';
import { ORDER_STATUS, PAY_METHOD, PAY_STATUS, QUOTE_STATUS, RETURN_STATUS, REFUND_METHOD } from './data/constants';
import { fmt, Money } from './data/format';
import {
  Badge, PageHead, Crumb, Panel, SkeletonRows, Empty,
  Async, Pager, Field, Modal, Banner, Thumb, Qty
} from './ui-primitives';

/* Screens 13–17 + 22: orders, order detail, quotations, returns. */

const REORDER_SKIP_LABEL = { not_found_or_inactive: 'الصنف غير موجود أو غير متاح', insufficient_stock: 'الكمية غير متاحة' };

export const ReorderModal = ({ orderId, onClose }) => {
  const { go, applyCartResponse } = useApp();
  const [busy, setBusy] = useState(true);
  const [report, setReport] = useState(null);
  const [err, setErr] = useState('');
  const request = React.useRef(null);
  useEffect(() => {
    let active = true;
    setBusy(true);
    setErr('');
    setReport(null);
    // StrictMode replays effects; re-use the same mutation rather than adding twice.
    if (request.current?.id !== orderId) request.current = {
      id: orderId,
      promise: wholesaleEndpoints.reorder(orderId).then((r) => { applyCartResponse(r.cart); return r; }),
    };
    request.current.promise
      .then((r) => { if (active) { setReport(r); setBusy(false); } })
      .catch((e) => { if (active) { setErr(apiError(e).message); setBusy(false); } });
    return () => { active = false; };
  }, [orderId, applyCartResponse]);
  return (
    <Modal title="إعادة الطلب" onClose={onClose} icon={<div className="modal-icon"><i className="fa-solid fa-rotate" /></div>}
      foot={<><button className="btn-pill" onClick={onClose}>إغلاق</button><button className="btn-pill is-dark" disabled={busy || !report} onClick={() => go('cart')}><i className="fa-solid fa-bag-shopping" /> فتح السلة</button></>}>
      <Banner kind="info">تمت إضافة البنود المتاحة للسلة <b>بأسعار اليوم</b>، مش بأسعار الطلب القديم.</Banner>
      <div className="mt-16">
        {busy && <SkeletonRows rows={3} cols={3} />}
        {err && <p className="f-error">{err}</p>}
        {report && (
          <>
            {(report.added || []).map((a, i) => (
              <div key={`a-${i}`} className="sum-row"><span><b style={{ color: 'var(--ink)' }}>{a.sku}</b></span>
                <span className="badge success">أضيف <span className="num">×{a.qty}</span></span></div>))}
            {(report.skipped || []).map((s, i) => (
              <div key={`s-${i}`} className="sum-row"><span><b style={{ color: 'var(--ink)' }}>{s.sku}</b></span>
                <span className="badge danger">تم تخطيه · {REORDER_SKIP_LABEL[s.reason] || s.reason}</span></div>))}
            {!report.added?.length && !report.skipped?.length && <p className="muted">لا توجد بنود قابلة للإضافة.</p>}
          </>
        )}
      </div>
    </Modal>
  );
};

export const CancelModal = ({ order, onClose, onDone }) => {
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState('');
  const confirm = async () => {
    setBusy(true);
    setErr('');
    try {
      await accountEndpoints.cancelOrder(order.id);
      onDone();
    } catch (e) {
      setErr(apiError(e).message);
      setBusy(false);
    }
  };
  return (
    <Modal title={`إلغاء الطلب ${order.number}؟`} onClose={onClose} icon={<div className="modal-icon is-err"><i className="fa-solid fa-ban" /></div>}
      foot={<><button className="btn-pill" onClick={onClose}>تراجع</button><button className="btn-pill is-danger" disabled={busy} onClick={confirm}>{busy ? <span className="spin" /> : null} تأكيد الإلغاء</button></>}>
      {order.method === 'credit' && <p className="muted" style={{ lineHeight: 1.9 }}>هيتم إلغاء الطلب وتحرير مبلغ <b className="num" style={{ color: 'var(--ink)' }}>{fmt(order.total)} EGP</b> من الائتمان المستخدم. الإلغاء متاح طالما الطلب لم يُشحن.</p>}
      {order.method !== 'credit' && <p className="muted" style={{ lineHeight: 1.9 }}>هيتم إلغاء الطلب. الإلغاء متاح طالما الطلب لم يُشحن.</p>}
      {err && <p className="f-error" style={{ marginTop: 8 }}>{err}</p>}
    </Modal>
  );
};

/* ---------- 13. Orders ---------- */
const GROUPS = { all: null, active: 'active', delivered: 'delivered', cancelled: 'cancelled' };

export const Orders = () => {
  const { go, toast, refreshAccount } = useApp();
  const [f, setF] = useState('all');
  const [page, setPage] = useState(1);
  const [re, setRe] = useState(null);
  const [cancel, setCancel] = useState(null);

  const api = useApi((signal) => wholesaleEndpoints
    .orders({ group: GROUPS[f] || undefined, page }, signal)
    .then((r) => ({ items: (r.data || []).map(mapOrder), meta: pageMeta(r.meta) })), [f, page]);

  const list = api.data?.items || [];
  const meta = api.data?.meta || { page: 1, pages: 1, total: 0, per: 15 };

  const onCancelled = () => {
    setCancel(null);
    refreshAccount();
    api.reload();
    toast('تم إلغاء الطلب');
  };

  return (
    <>
      <PageHead en="My Orders" ar="كل طلبات حساب الجملة" />
      <section className="panel">
        <div className="toolbar">
          <div className="chips">{[['all', 'الكل'], ['active', 'جاري التنفيذ'], ['delivered', 'تم التسليم'], ['cancelled', 'ملغي']].map(([k, l]) => <button key={k} className={`chip${f === k ? ' is-on' : ''}`} onClick={() => { setF(k); setPage(1); }}>{l}</button>)}</div>
        </div>
        <DataBoundary api={api}>
          <Async rows={6} cols={6} isEmpty={!list.length} empty={<Empty icon="fa-box-open" title="مفيش طلبات" desc="لما تعمل أول طلب هيظهر هنا." action={<button className="btn-pill is-dark" onClick={() => go('catalog')}>تصفح الكتالوج</button>} />}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>رقم الطلب</th><th>التاريخ</th><th>حالة التنفيذ</th><th>طريقة الدفع</th><th>السداد</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
              <tbody>{list.map((o) => (
                <tr key={o.id} className="is-click" onClick={() => go('order', o.id)}>
                  <td className="strong num">{o.number}</td>
                  <td className="num">{o.date}</td>
                  <td><Badge map={ORDER_STATUS} k={o.status} /></td>
                  <td>{PAY_METHOD[o.method]}</td>
                  <td><Badge map={PAY_STATUS} k={o.pay} /></td>
                  <td className="t-end strong num">{fmt(o.total)}</td>
                  <td onClick={(e) => e.stopPropagation()}><div className="row-actions">
                    <button className="btn-link" onClick={() => setRe(o.id)}>إعادة الطلب</button>
                    {o.cancellable && <button className="btn-link danger" onClick={() => setCancel(o)}>إلغاء</button>}
                    <button className="btn-link muted" onClick={() => go('order', o.id)}>التفاصيل</button>
                  </div></td>
                </tr>))}</tbody>
            </table></div>
            <Pager page={meta.page} pages={meta.pages} total={meta.total} per={meta.per} onPage={setPage} />
          </Async>
        </DataBoundary>
      </section>
      {re && <ReorderModal orderId={re} onClose={() => setRe(null)} />}
      {cancel && <CancelModal order={cancel} onClose={() => setCancel(null)} onDone={onCancelled} />}
    </>
  );
};

/* ---------- 14. Order detail + tracking ---------- */
export const OrderDetail = ({ id }) => {
  const { go, refreshAccount, route } = useApp();
  const [re, setRe] = useState(false);
  const [cancel, setCancel] = useState(false);

  const api = useApi((signal) => wholesaleEndpoints.order(id, signal).then(mapOrder), [id]);
  const o = api.data;

  const onCancelled = () => {
    setCancel(false);
    refreshAccount();
    api.reload();
  };

  return (
    <>
      <PageHead en={o?.number || ''} crumb={<Crumb items={[{ label: 'طلباتي', go: () => go('orders') }, { label: o?.number || '', mono: true }]} />} ar={o ? <>تاريخ الطلب <span className="num">{o.date}</span></> : null}>
        {o && <Badge map={ORDER_STATUS} k={o.status} lg />}
        {o && <button className="btn-pill" onClick={() => setRe(true)}><i className="fa-solid fa-rotate" /> إعادة الطلب</button>}
        {o?.returnable && <button className="btn-pill" onClick={() => go('returnNew', o.id)}><i className="fa-solid fa-rotate-left" /> طلب إرجاع</button>}
        {o?.cancellable && <button className="btn-pill is-danger" onClick={() => setCancel(true)}>إلغاء الطلب</button>}
      </PageHead>
      <DataBoundary api={api}>
        <Async rows={5} cols={4} empty={<Empty icon="fa-box-open" title="الطلب غير موجود" />}>
          {o && (
          <div className="grid-2">
            <div className="stack">
              <Panel title="البنود" en="ITEMS" body={false}>
                <div className="tbl-wrap"><table className="tbl">
                  <thead><tr><th>المنتج</th><th>الكمية</th><th>سعر الوحدة</th><th>الخصم</th><th className="t-end">الإجمالي</th></tr></thead>
                  <tbody>{o.items.map((it) => (
                    <tr key={it.id || it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td>
                      <td className="num">{it.qty}</td><td className="num">{fmt(it.unit)}</td><td className="num" style={{ color: it.discount ? 'var(--teal)' : null }}>{it.discount ? '− ' + fmt(it.discount) : '—'}</td>
                      <td className="t-end strong num">{fmt(it.line_total)}</td></tr>))}</tbody>
                </table></div>
              </Panel>
              <div className="grid-2e" style={{ gap: 24 }}>
                <Panel title="المستلم والعنوان" en="DELIVERY">
                  <dl className="kv"><dt>المستلم</dt><dd>{o.recipient}</dd><dt>التليفون</dt><dd className="num">{o.phone}</dd><dt>المدينة</dt><dd>{o.city}</dd><dt>العنوان</dt><dd>{o.address}</dd></dl>
                </Panel>
                <Panel title="الدفع" en="PAYMENT">
                  <dl className="kv"><dt>الطريقة</dt><dd>{PAY_METHOD[o.method]}</dd><dt>حالة السداد</dt><dd><Badge map={PAY_STATUS} k={o.pay} /></dd></dl>
                  {o.pay === 'unpaid' && o.method === 'credit' && <button className="btn-link mt-16" onClick={() => go('noticeNew', o.id)}>تسجيل إشعار سداد لهذا الطلب</button>}
                </Panel>
              </div>
            </div>
            <div className="stack">
              <Panel title="تفصيل المبالغ" en="TOTALS">
                <div className="sum-row"><span>المنتجات</span><strong className="num">{fmt(o.subtotal)}</strong></div>
                <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{o.discount ? '− ' + fmt(o.discount) : '—'}</strong></div>
                <div className="sum-row"><span>الشحن</span><strong className="num">{fmt(o.shipping)}</strong></div>
                <div className="sum-row"><span>رسوم التحصيل</span><strong className="num">{fmt(o.cod_fee)}</strong></div>
                <div className="sum-row"><span>الضريبة</span><strong className="num">{fmt(o.tax)}</strong></div>
                <div className="sum-total"><span>الإجمالي</span><span className="num">{fmt(o.total)}</span></div>
              </Panel>
              <Panel title="سجل الحالة" en="TRACKING">
                <ul className="tl">{(o.track || []).map(([s, t, st], i) => (
                  <li key={i} className={st === 'now' ? 'is-now' : st === 'done' ? 'is-done' : 'is-future'}>
                    <div className="tl-title">{ORDER_STATUS[s] ? ORDER_STATUS[s][0] : s}</div>{t && <div className="tl-meta num">{t}</div>}</li>))}</ul>
                <p className="note"><i className="fa-solid fa-circle-info" />التتبع من خدمة الشحن برقم الطلب ورقم الهاتف.</p>
              </Panel>
            </div>
          </div>
          )}
        </Async>
      </DataBoundary>
      {re && o && <ReorderModal orderId={o.id} onClose={() => setRe(false)} />}
      {cancel && o && <CancelModal order={o} onClose={() => setCancel(false)} onDone={onCancelled} />}
    </>
  );
};

/* ---------- 15. Quotations list ---------- */
const QUOTE_FILTER_REV = { priced: 'priced_by_admin', converted: 'converted_to_order' };

export const Quotes = () => {
  const { go } = useApp();
  const [f, setF] = useState('all');
  const [page, setPage] = useState(1);

  const api = useApi((signal) => wholesaleEndpoints
    .quotes({ status: QUOTE_FILTER_REV[f] || (f === 'all' ? undefined : f), page }, signal)
    .then((r) => ({ items: (r.data || []).map(mapQuote), meta: pageMeta(r.meta) })), [f, page]);

  const list = api.data?.items || [];
  const meta = api.data?.meta || { page: 1, pages: 1, total: 0, per: 15 };

  return (
    <>
      <PageHead en="Quotations" ar="اطلب تسعير خاص للكميات الكبيرة وتابع رد الإدارة">
        <button className="btn-pill is-dark" onClick={() => go('quoteNew')}><i className="fa-solid fa-plus" /> طلب عرض سعر</button>
      </PageHead>
      <section className="panel">
        <div className="toolbar"><div className="chips">
          <button className={`chip${f === 'all' ? ' is-on' : ''}`} onClick={() => { setF('all'); setPage(1); }}>الكل</button>
          {Object.entries(QUOTE_STATUS).map(([k, [l]]) => <button key={k} className={`chip${f === k ? ' is-on' : ''}`} onClick={() => { setF(k); setPage(1); }}>{l}</button>)}
        </div></div>
        <DataBoundary api={api}>
          <Async rows={6} cols={5} isEmpty={!list.length} empty={<Empty icon="fa-file-signature" title="لا توجد عروض أسعار بهذه الحالة" action={<button className="btn-pill is-dark" onClick={() => go('quoteNew')}>طلب عرض سعر</button>} />}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>رقم العرض</th><th>تاريخ الإنشاء</th><th>الحالة</th><th>صالح حتى</th><th className="t-end">الإجمالي</th><th></th></tr></thead>
              <tbody>{list.map((q) => {
                const daysLeft = q.valid_until ? Math.ceil((new Date(q.valid_until).getTime() - Date.now()) / 864e5) : null;
                return (
                  <tr key={q.id} className="is-click" onClick={() => go(q.status === 'draft' ? 'quoteEdit' : 'quote', q.id)}>
                    <td className="strong num">{q.number}</td><td className="num">{q.created}</td><td><Badge map={QUOTE_STATUS} k={q.status} /></td>
                    <td className="num">{q.valid_until || '—'}{q.status === 'priced' && daysLeft != null && daysLeft >= 0 && <span className="badge warning" style={{ marginInlineStart: 8 }}>باقي <span className="num">{daysLeft}</span> يوم</span>}</td>
                    <td className="t-end strong num">{q.total != null ? fmt(q.total) : '—'}</td>
                    <td className="t-end"><button className="btn-link muted">{q.status === 'draft' ? 'تعديل' : q.status === 'priced' ? 'مراجعة والرد' : 'فتح'}</button></td>
                  </tr>);
              })}</tbody>
            </table></div>
            <Pager page={meta.page} pages={meta.pages} total={meta.total} per={meta.per} onPage={setPage} />
          </Async>
        </DataBoundary>
      </section>
    </>
  );
};

/* ---------- 16. Create / edit quote ---------- */
export const QuoteForm = ({ id }) => {
  const { go, toast, route } = useApp();
  const editingId = id ?? route.id;
  const [items, setItems] = useState([]);
  const [note, setNote] = useState('');
  const [search, setSearch] = useState('');
  const [debounced, setDebounced] = useState('');
  const [matches, setMatches] = useState([]);
  const [errs, setErrs] = useState({});
  const [confirm, setConfirm] = useState(null);
  const [busy, setBusy] = useState(false);
  const savedId = React.useRef(editingId);
  const quoteApi = useApi((signal) => wholesaleEndpoints.quote(editingId, signal).then(mapQuote), [editingId], !!editingId);

  useEffect(() => {
    if (quoteApi.state === 'ready' && quoteApi.data) {
        const m = quoteApi.data;
        setItems((m.items || []).map((it) => ({ variant_id: it.variant_id, name: it.name, sku: it.sku, qty: it.qty, target: it.target != null ? String(it.target) : '' })));
        setNote(m.trader_note || '');
    }
    savedId.current = editingId;
  }, [editingId, quoteApi.data]);

  useEffect(() => {
    const t = setTimeout(() => setDebounced(search), 400);
    return () => clearTimeout(t);
  }, [search]);

  useEffect(() => {
    if (!debounced.trim()) { setMatches([]); return; }
    const ctrl = new AbortController();
    wholesaleEndpoints.products({ search: debounced.trim(), per_page: 5 }, ctrl.signal)
      .then((r) => {
        const vars = (r.data || []).flatMap((p) => (p.variants || []).map((v) => ({
          variant_id: v.id, name: p.name, sku: v.sku, price: v.your_price != null ? Number(v.your_price) : null,
        })));
        if (!ctrl.signal.aborted) setMatches(vars);
      })
      .catch(() => {});
    return () => ctrl.abort();
  }, [debounced]);

  const upd = (i, k, val) => setItems(items.map((it, j) => j === i ? { ...it, [k]: val } : it));

  const save = async () => {
    const e = {};
    if (!items.length) e.items = 'أضف بند واحد على الأقل.';
    items.forEach((it, i) => { if (!it.qty || Number(it.qty) <= 0) e[`items.${i}.qty`] = 'الكمية مطلوبة.'; });
    if (note.length > 2000) e.note = 'الحد الأقصى 2000 حرف.';
    setErrs(e);
    if (Object.keys(e).length) return null;
    const body = {
      customer_notes: note || null,
      items: items.map((it) => ({ product_variant_id: it.variant_id, qty: Number(it.qty), requested_target_price: it.target ? Number(it.target) : null })),
    };
    setBusy(true);
    try {
      const saved = savedId.current ? await wholesaleEndpoints.updateQuote(savedId.current, body) : await wholesaleEndpoints.createQuote(body);
      savedId.current = saved.id;
      return saved;
    } catch (err) {
      const info = apiError(err);
      const mapped = {};
      Object.entries(info.fields || {}).forEach(([k, msgs]) => { mapped[k === 'customer_notes' ? 'note' : k] = Array.isArray(msgs) ? msgs[0] : String(msgs); });
      setErrs(mapped);
      if (!Object.keys(mapped).length) toast(info.message);
      return null;
    } finally {
      setBusy(false);
    }
  };

  const saveDraft = async () => {
    const saved = await save();
    if (saved) { toast('تم حفظ المسودة'); go('quotes'); }
  };

  const sendForPricing = async () => {
    const saved = await save();
    if (!saved) return;
    setBusy(true);
    try {
      const submitted = await wholesaleEndpoints.submitQuote(saved.id);
      go('quote', submitted.id);
    } catch (err) {
      toast(apiError(err).message);
    } finally {
      setBusy(false);
      setConfirm(null);
    }
  };

  const removeDraft = async () => {
    setBusy(true);
    try {
      await wholesaleEndpoints.deleteQuote(editingId);
      toast('تم حذف المسودة');
      go('quotes');
    } catch (err) {
      toast(apiError(err).message);
    } finally {
      setBusy(false);
      setConfirm(null);
    }
  };

  if (editingId && quoteApi.state !== 'ready') return (<><PageHead en="Quote" /><section className="panel"><DataBoundary api={quoteApi}><Async rows={5} cols={5} /></DataBoundary></section></>);

  return (
    <>
      <PageHead en={editingId ? 'تعديل مسودة' : 'New Quote'} crumb={<Crumb items={[{ label: 'عروض الأسعار', go: () => go('quotes') }, { label: editingId ? 'تعديل مسودة' : 'طلب جديد' }]} />} ar={editingId ? 'مسودة — يمكنك التعديل قبل الإرسال' : 'اختر المنتجات والكميات، واقترح السعر المستهدف لو حابب'}>
        {editingId && <button className="btn-pill is-danger" onClick={() => setConfirm('delete')}><i className="fa-regular fa-trash-can" /> حذف المسودة</button>}
      </PageHead>
      <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
        <section className="panel">
          <div className="toolbar" style={{ position: 'relative' }}>
            <div className="search" style={{ flex: 1 }}><i className="fa-solid fa-plus" /><input className="line-input" placeholder="أضف منتج — ابحث بالاسم أو SKU" value={search} onChange={(e) => setSearch(e.target.value)} /></div>
            <span className="soft small"><span className="num">{items.length}</span> / <span className="num">100</span> بند</span>
            {matches.length > 0 && (
              <div className="qf-suggest">{matches.map((v) => (
                <button key={v.variant_id} onClick={() => { setItems([...items, { variant_id: v.variant_id, name: v.name, sku: v.sku, qty: 1, target: '' }]); setSearch(''); setMatches([]); }}>
                  <Thumb sm /><span style={{ flex: 1 }}><b>{v.name}</b><span className="sku">{v.sku}</span></span><span className="num small">{v.price != null ? fmt(v.price) : '—'}</span></button>))}</div>
            )}
          </div>
          {items.length === 0 ? <Empty icon="fa-list" title="مفيش بنود" desc="ابحث وأضف المنتجات اللي عايز تسعيرها." /> : (
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>المتغير</th><th>الكمية</th><th>السعر المستهدف <span className="f-opt">(اختياري)</span></th><th></th></tr></thead>
              <tbody>{items.map((it, i) => (
                <tr key={i} className={errs[`items.${i}.qty`] ? 'is-error' : ''}>
                  <td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="soft small"><span className="sku">{it.sku}</span></div></div></div></td>
                  <td><Qty value={it.qty} onChange={(n) => upd(i, 'qty', n)} />{errs[`items.${i}.qty`] && <p className="f-error">{errs[`items.${i}.qty`]}</p>}</td>
                  <td><input className="box-input ltr" style={{ width: 120 }} placeholder="0.00" value={it.target} onChange={(e) => upd(i, 'target', e.target.value.replace(/[^\d.]/g, ''))} />{errs[`items.${i}.requested_target_price`] && <p className="f-error">{errs[`items.${i}.requested_target_price`]}</p>}{errs[`items.${i}.product_variant_id`] && <p className="f-error">{errs[`items.${i}.product_variant_id`]}</p>}</td>
                  <td><button className="btn-link muted" onClick={() => setItems(items.filter((_, j) => j !== i))} aria-label="حذف"><i className="fa-solid fa-xmark" /></button></td>
                </tr>))}</tbody>
            </table></div>
          )}
          {errs.items && <p className="f-error" style={{ padding: '0 24px 16px' }}>{errs.items}</p>}
        </section>
        <aside className="stack" style={{ position: 'sticky', top: 100 }}>
          <Panel title="ملاحظات للإدارة">
            <Field label="ملاحظات التاجر" opt counter={<span className="f-counter" style={{ color: note.length > 2000 ? '#b91c1c' : null }}>{note.length}/2000</span>} error={errs.note}>
              <textarea className="line-input" rows="5" value={note} placeholder="مواعيد التسليم، تغليف خاص، شروط الدفع…" onChange={(e) => setNote(e.target.value)} />
            </Field>
            <div className="divider" />
            <div className="sum-row"><span>عدد البنود</span><strong className="num">{items.length}</strong></div>
            <div className="sum-row"><span>إجمالي الكميات</span><strong className="num">{items.reduce((a, it) => a + Number(it.qty || 0), 0)}</strong></div>
            <button className="btn-block mt-24" disabled={busy} onClick={() => setConfirm('submit')}><i className="fa-solid fa-paper-plane" /> إرسال للإدارة للتسعير</button>
            <button className="btn-pill mt-8" style={{ width: '100%', justifyContent: 'center' }} disabled={busy} onClick={saveDraft}><i className="fa-regular fa-floppy-disk" /> حفظ كمسودة</button>
          </Panel>
          <p className="note"><i className="fa-solid fa-circle-info" />بعد الإرسال مش هتقدر تعدّل الطلب. الإدارة هترد بالأسعار وتاريخ صلاحية العرض.</p>
        </aside>
      </div>
      {confirm === 'submit' && <Modal title="إرسال طلب التسعير؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon"><i className="fa-solid fa-paper-plane" /></div>}
        foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-dark" disabled={busy} onClick={sendForPricing}>{busy ? <span className="spin" /> : 'إرسال'}</button></>}>
        <p className="muted">هيتم إرسال <span className="num">{items.length}</span> بند للإدارة. الحالة هتتغير إلى «مطلوب تسعيره».</p></Modal>}
      {confirm === 'delete' && <Modal title="حذف المسودة؟" onClose={() => setConfirm(null)} icon={<div className="modal-icon is-err"><i className="fa-solid fa-trash-can" /></div>}
        foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className="btn-pill is-danger" disabled={busy} onClick={removeDraft}>{busy ? <span className="spin" /> : 'حذف'}</button></>}>
        <p className="muted">الإجراء ده نهائي.</p></Modal>}
    </>
  );
};

/* ---------- 17. Quote detail ---------- */
export const QuoteDetail = ({ id }) => {
  const { go, toast, refreshAccount } = useApp();
  const [confirm, setConfirm] = useState(null);
  const [busy, setBusy] = useState(false);

  const api = useApi((signal) => wholesaleEndpoints.quote(id, signal).then(mapQuote), [id]);
  const q = api.data;

  const act = async (kind) => {
    setBusy(true);
    try {
      if (kind === 'accept') {
        await wholesaleEndpoints.acceptQuote(id);
        toast('تم قبول العرض');
      } else {
        await wholesaleEndpoints.rejectQuote(id);
        toast('تم رفض العرض');
      }
      await api.reload();
      refreshAccount();
    } catch (e) {
      toast(apiError(e).message);
      await api.reload();
    } finally {
      setBusy(false);
      setConfirm(null);
    }
  };

  return (
    <>
      <PageHead en={q?.number || ''} crumb={<Crumb items={[{ label: 'عروض الأسعار', go: () => go('quotes') }, { label: q?.number || '', mono: true }]} />} ar={q ? <>أُنشئ في <span className="num">{q.created}</span>{q.valid_until ? <> · صالح حتى <span className="num">{q.valid_until}</span></> : null}</> : null}>
        {q && <Badge map={QUOTE_STATUS} k={q.status} lg />}
      </PageHead>
      <DataBoundary api={api}>
        <Async rows={5} cols={4} empty={<Empty icon="fa-file-signature" title="العرض غير موجود" />}>
          {q && (
          <>
            {q.status === 'priced' && <div className="mb-24"><Banner kind="info" icon="fa-clock" action={<div className="row"><button className="btn-pill is-danger sm" onClick={() => setConfirm('reject')}>رفض</button><button className="btn-pill is-dark sm" onClick={() => setConfirm('accept')}>قبول العرض</button></div>}><b>الإدارة سعّرت العرض.</b> راجع الأسعار وقرر قبل <span className="num">{q.valid_until}</span> — بعدها العرض بينتهي تلقائيًا.</Banner></div>}
            {q.status === 'requested' && <div className="mb-24"><Banner kind="warn" icon="fa-hourglass-half">الطلب عند الإدارة للتسعير. هيوصلك إشعار لما يتم الرد.</Banner></div>}
            {q.status === 'expired' && <div className="mb-24"><Banner kind="error" icon="fa-calendar-xmark">انتهت صلاحية العرض ولم يعد قابلًا للقبول. تقدر تطلب عرض جديد.</Banner></div>}
            {q.status === 'converted' && <div className="mb-24"><Banner kind="ok" action={q.converted_order_id && <button className="btn-pill sm" onClick={() => go('order', q.converted_order_id)}>فتح الطلب <span className="num">{q.converted_order_id}</span></button>}>تم تحويل العرض لطلب.</Banner></div>}
            {q.status === 'accepted' && <div className="mb-24"><Banner kind="ok">تم قبول العرض. الإدارة هتحوله لطلب وهيظهر في طلباتك.</Banner></div>}
            <div className="grid-2">
              <Panel title="البنود" en="LINE ITEMS" body={false}>
                <div className="tbl-wrap"><table className="tbl">
                  <thead><tr><th>المنتج</th><th>الكمية</th><th>السعر المطلوب</th><th>السعر المعروض</th><th className="t-end">إجمالي البند</th></tr></thead>
                  <tbody>{q.items.map((it) => (
                    <tr key={it.id || it.sku}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td>
                      <td className="num">{it.qty}</td><td className="num muted">{it.target != null ? fmt(it.target) : '—'}</td>
                      <td className="num strong">{it.offered != null ? fmt(it.offered) : <span className="soft">في الانتظار</span>}</td>
                      <td className="t-end strong num">{it.offered != null ? fmt(it.line_total) : '—'}</td></tr>))}</tbody>
                </table></div>
              </Panel>
              <div className="stack">
                <Panel title="الإجماليات" en="TOTALS">
                  <div className="sum-row"><span>الإجمالي قبل الخصم</span><strong className="num">{q.subtotal != null ? fmt(q.subtotal) : '—'}</strong></div>
                  <div className="sum-row is-neg"><span>الخصم</span><strong className="num">{q.discount ? '− ' + fmt(q.discount) : '—'}</strong></div>
                  <div className="sum-row"><span>الضريبة</span><strong className="num">{q.tax != null ? fmt(q.tax) : '—'}</strong></div>
                  <div className="sum-total"><span>الإجمالي النهائي</span><strong className="num">{q.total != null ? fmt(q.total) : '—'}</strong></div>
                </Panel>
                <Panel title="الملاحظات" en="NOTES">
                  <div className="note-bubble"><span>ملاحظات التاجر</span><p>{q.trader_note || <span className="soft">—</span>}</p></div>
                  <div className="note-bubble is-admin"><span>رد الإدارة</span><p>{q.admin_note || <span className="soft">لم يتم الرد بعد</span>}</p></div>
                </Panel>
              </div>
            </div>
          </>
          )}
        </Async>
      </DataBoundary>
      {confirm && <Modal title={confirm === 'accept' ? 'قبول عرض السعر؟' : 'رفض عرض السعر؟'} onClose={() => setConfirm(null)} icon={<div className={`modal-icon${confirm === 'reject' ? ' is-err' : ''}`}><i className={`fa-solid ${confirm === 'accept' ? 'fa-check' : 'fa-xmark'}`} /></div>}
        foot={<><button className="btn-pill" onClick={() => setConfirm(null)}>رجوع</button><button className={`btn-pill ${confirm === 'accept' ? 'is-dark' : 'is-danger'}`} disabled={busy} onClick={() => act(confirm)}>{busy ? <span className="spin" /> : confirm === 'accept' ? 'قبول' : 'رفض'}</button></>}>
        <p className="muted" style={{ lineHeight: 1.9 }}>{confirm === 'accept' && q ? <>بقبولك العرض بإجمالي <b className="num" style={{ color: 'var(--ink)' }}>{fmt(q.total)} EGP</b> الإدارة هتحوله لطلب.</> : 'الإجراء نهائي، ولن يكون العرض قابلًا للقبول بعد الرفض.'}</p></Modal>}
    </>
  );
};

/* ---------- 22. Returns ---------- */
export const Returns = () => {
  const { go } = useApp();
  const [page, setPage] = useState(1);

  const api = useApi(() => accountEndpoints.returns(page)
    .then((r) => ({ items: (r.data || []).map(mapReturn), meta: pageMeta(r.meta) })), [page]);
  const list = api.data?.items || [];
  const meta = api.data?.meta || { page: 1, pages: 1, total: 0, per: 20 };

  return (
    <>
      <PageHead en="Returns" ar="طلبات الإرجاع والاسترداد"><button className="btn-pill is-dark" onClick={() => go('returnNew')}><i className="fa-solid fa-plus" /> طلب إرجاع</button></PageHead>
      <section className="panel">
        <DataBoundary api={api}>
          <Async rows={4} cols={5} isEmpty={!list.length} empty={<Empty icon="fa-rotate-left" title="مفيش مرتجعات" desc="تقدر تطلب إرجاع لأي طلب مؤهل بعد التسليم." />}>
            <div className="tbl-wrap"><table className="tbl">
              <thead><tr><th>رقم المرتجع</th><th>الطلب</th><th>الحالة</th><th>مبلغ الاسترداد</th><th>التاريخ</th><th></th></tr></thead>
              <tbody>{list.map((r) => (
                <tr key={r.id} className="is-click" onClick={() => go('return', r.id)}>
                  <td className="strong num">{r.number}</td><td className="num">{r.order}</td><td><Badge map={RETURN_STATUS} k={r.status} /></td>
                  <td className="strong num">{fmt(r.refund)}</td><td className="num">{r.date}</td><td className="t-end"><button className="btn-link muted">التفاصيل</button></td></tr>))}</tbody>
            </table></div>
            <Pager page={meta.page} pages={meta.pages} total={meta.total} per={meta.per} onPage={setPage} />
          </Async>
        </DataBoundary>
      </section>
    </>
  );
};

export const ReturnForm = ({ orderId }) => {
  const { go, toast, route } = useApp();
  const preselect = orderId ?? route.id;
  const [oid, setOid] = useState(preselect || null);
  const [sel, setSel] = useState({});
  const [reason, setReason] = useState('');
  const [method, setMethod] = useState('');
  const [errs, setErrs] = useState({});
  const [busy, setBusy] = useState(false);

  const eligibleApi = useApi((signal) => allPages((page, signal) => wholesaleEndpoints.orders({ group: 'delivered', page }, signal), signal)
    .then((rows) => rows.map(mapOrder).filter((o) => o.returnable)), []);
  const eligible = eligibleApi.data || [];
  useEffect(() => { if (!oid && eligible.length) setOid(eligible[0].id); }, [oid, eligible]);

  const orderApi = useApi((signal) => wholesaleEndpoints.order(oid, signal).then(mapOrder), [oid], !!oid);
  const order = orderApi.state === 'ready' && orderApi.data?.id === oid ? orderApi.data : null;
  useEffect(() => { setSel({}); }, [oid]);

  const toggle = (id) => setSel((s) => ({ ...s, [id]: s[id] ? undefined : { qty: 1, reason: '', files: [] } }));
  const set = (id, k, v) => setSel((s) => ({ ...s, [id]: { ...s[id], [k]: v } }));
  const chosen = Object.entries(sel).filter(([, v]) => v);
  const totalFiles = chosen.reduce((a, [, v]) => a + v.files.length, 0);

  const addFiles = (id, list) => {
    const cur = sel[id];
    if (!cur) return;
    const next = [...cur.files, ...list];
    const error = validateReturnFiles(chosen.map(([itemId, value]) => String(itemId) === String(id) ? next : value.files));
    setErrs((previous) => ({ ...previous, files: error }));
    if (error) { toast(error); return; }
    set(id, 'files', next);
  };

  const submit = async () => {
    const e = {};
    if (!oid || !order || !order.returnable) e.order = 'اختر طلبًا مؤهلًا للإرجاع.';
    if (!chosen.length) e.items = 'اختر بند واحد على الأقل.';
    if (!reason.trim()) e.reason = 'السبب العام مطلوب.';
    chosen.forEach(([itemId, v]) => {
      if (v.reason.length > 255) e[itemId] = 'الحد الأقصى 255 حرف.';
      if (!Number.isInteger(Number(v.qty)) || Number(v.qty) < 1) e[`${itemId}-qty`] = 'كمية صحيحة مطلوبة.';
    });
    const fileError = validateReturnFiles(chosen.map(([, v]) => v.files));
    if (fileError) e.files = fileError;
    if (method && !REFUND_METHOD[method]) e.method = 'طريقة استرداد غير صالحة.';
    setErrs(e);
    if (Object.keys(e).length) return;
    const fd = new FormData();
    fd.append('order_id', String(oid));
    fd.append('reason', reason);
    if (method) fd.append('refund_method', method);
    chosen.forEach(([itemId, v], i) => {
      fd.append(`items[${i}][order_item_id]`, String(itemId));
      fd.append(`items[${i}][requested_qty]`, String(Math.trunc(Number(v.qty))));
      if (v.reason) fd.append(`items[${i}][item_reason]`, v.reason);
      v.files.forEach((fl) => fd.append(`items[${i}][attachments][]`, fl));
    });
    setBusy(true);
    try {
      const r = await accountEndpoints.createReturn(fd);
      go('return', r.id);
    } catch (err) {
      const info = apiError(err);
      const mapped = {};
      Object.entries(info.fields || {}).forEach(([k, msgs]) => {
        const parts = k.split('.');
        const itemId = parts[0] === 'items' ? chosen[Number(parts[1])]?.[0] : null;
        const key = k === 'order_id' ? 'order' : k === 'refund_method' ? 'method'
          : itemId ? (parts[2] === 'requested_qty' ? `${itemId}-qty` : parts[2] === 'item_reason' ? itemId : parts[2] === 'attachments' ? 'files' : 'items') : k;
        mapped[key] = Array.isArray(msgs) ? msgs[0] : String(msgs);
      });
      setErrs(mapped);
      if (!Object.keys(mapped).length) toast(info.message);
    } finally {
      setBusy(false);
    }
  };

  return (
    <>
      <PageHead en="New Return" crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: 'طلب جديد' }]} />} ar="اختر الطلب والبنود، ووضح السبب" />
      <div className="grid-2" style={{ gridTemplateColumns: '1fr 340px' }}>
        <div className="stack">
          <Panel title="الطلب المؤهل" en="ORDER">
            {errs.order && <p className="f-error">{errs.order}</p>}
            <DataBoundary api={eligibleApi}><Async rows={2} cols={2} isEmpty={!eligible.length} empty={<Empty title="لا توجد طلبات مؤهلة للإرجاع حاليًا." />}>
            <div className="addr-picks">{eligible.map((x) => (
              <button key={x.id} className={`addr-pick${oid === x.id ? ' is-on' : ''}`} onClick={() => { setOid(x.id); }}><b className="num">{x.number}</b><span>تم التسليم · <span className="num">{x.date}</span> · <span className="num">{fmt(x.total)}</span> EGP</span></button>))}
              {!eligible.length && <p className="muted">لا توجد طلبات مؤهلة للإرجاع حاليًا.</p>}</div>
            </Async></DataBoundary>
            <p className="note mt-16"><i className="fa-solid fa-circle-info" />الطلبات المؤهلة بس هي اللي بتظهر هنا (تم تسليمها وضمن مدة الإرجاع).</p>
          </Panel>
          <Panel title="البنود المرتجعة" en="ITEMS">
            {errs.items && <p className="f-error" style={{ marginTop: 0 }}>{errs.items}</p>}
            {oid && <DataBoundary api={orderApi}><Async rows={3} cols={3}>
            {(order?.items || []).map((it) => {
              const s = sel[it.id];
              return (
                <div key={it.id} className={`ret-item${s ? ' is-on' : ''}`}>
                  <label className="row" style={{ cursor: 'pointer' }}>
                    <input type="checkbox" checked={!!s} onChange={() => toggle(it.id)} style={{ accentColor: '#111', width: 16, height: 16 }} />
                    <Thumb sm /><div style={{ flex: 1 }}><div className="prod-name">{it.name}</div><div className="soft small"><span className="sku">{it.sku}</span> · تم شراء <span className="num">{it.qty}</span> · <span className="num">{fmt(it.unit)}</span></div></div>
                  </label>
                  {s && (
                    <div className="fields mt-16" style={{ paddingInlineStart: 42 }}>
                      <Field label="الكمية المرتجعة" req hint={`حتى ${it.qty}`} error={errs[`${it.id}-qty`]}><Qty value={s.qty} min={1} onChange={(n) => set(it.id, 'qty', Math.min(n, it.qty))} /></Field>
                      <Field label="سبب البند" opt error={errs[it.id]}><input className={`line-input${errs[it.id] ? ' is-invalid' : ''}`} value={s.reason} placeholder="مثال: عيب في السحّاب" onChange={(e) => set(it.id, 'reason', e.target.value)} /></Field>
                      <Field label="صور" opt span hint="حتى 5 صور للبند · 5 ميجابايت للصورة · JPG / PNG / WebP" error={errs.files}>
                        <div className="row wrap">
                          {s.files.map((fl, k) => <button key={k} type="button" className="photo-chip" title={`حذف ${fl.name}`} onClick={() => { set(it.id, 'files', s.files.filter((_, index) => index !== k)); setErrs((previous) => ({ ...previous, files: null })); }}><i className="fa-regular fa-image" /></button>)}
                          {s.files.length < 5 && totalFiles < 10 && <label className="drop sm" style={{ minHeight: 52, width: 52, padding: 0, justifyContent: 'center', cursor: 'pointer' }}><input type="file" accept=".jpg,.jpeg,.png,.webp" multiple style={{ display: 'none' }} onChange={(e) => { addFiles(it.id, Array.from(e.target.files || [])); e.target.value = ''; }} /><i className="fa-solid fa-plus" /></label>}
                        </div>
                      </Field>
                    </div>
                  )}
                </div>);
            })}
            </Async></DataBoundary>}
            {errs.files && <p className="f-error" role="alert">{errs.files}</p>}
          </Panel>
        </div>
        <aside className="stack" style={{ position: 'sticky', top: 100 }}>
          <Panel title="السبب والاسترداد">
            <Field label="السبب العام" req error={errs.reason}><textarea className={`line-input${errs.reason ? ' is-invalid' : ''}`} rows="3" value={reason} onChange={(e) => setReason(e.target.value)} /></Field>
            <div className="f-label mt-24">طريقة الاسترداد</div>
            <div className="radio-list">{Object.entries(REFUND_METHOD).map(([k, l]) => <label key={k} className="radio-row"><span className="radio-left"><input type="radio" checked={method === k} onChange={() => setMethod(k)} /><span className="radio-title">{l}</span></span></label>)}</div>
            {errs.method && <p className="f-error">{errs.method}</p>}
            <div className="sum-row mt-16"><span>صور مرفقة</span><strong className="num" style={{ color: totalFiles > 10 ? '#b91c1c' : null }}>{totalFiles} / 10</strong></div>
            <button className="btn-block mt-24" disabled={busy || !order || !order.returnable} onClick={submit}>{busy ? <><span className="spin" /> جارٍ التقديم…</> : 'تقديم طلب الإرجاع'}</button>
          </Panel>
          <p className="note"><i className="fa-solid fa-circle-info" />إجمالي حجم الصور حتى 25 ميجابايت. مبلغ الاسترداد النهائي بيتحدد بعد فحص المرتجع.</p>
        </aside>
      </div>
    </>
  );
};

export const ReturnDetail = ({ id }) => {
  const { go } = useApp();
  const api = useApi(() => accountEndpoints.returnDetail(id).then(mapReturn), [id]);
  const r = api.data;
  const steps = r ? [['requested', r.date], ['approved', r.approved_at], ['received', r.received_at], ['refunded', r.refunded_at]] : [];

  const { toast } = useApp();
  const dlPhoto = async (url) => {
    try {
      await saveBlob(defaultApiClient.get(url, { responseType: 'blob', params: { signed: 1 } }), 'photo.jpg');
    } catch (e) {
      toast(apiError(e).message);
    }
  };

  return (
    <>
      <PageHead en={r?.number || ''} crumb={<Crumb items={[{ label: 'المرتجعات', go: () => go('returns') }, { label: r?.number || '', mono: true }]} />} ar={r ? <>على الطلب <button className="btn-link" onClick={() => go('order', r.order_id)}><span className="num">{r.order}</span></button></> : null}>
        {r && <Badge map={RETURN_STATUS} k={r.status} lg />}
      </PageHead>
      <DataBoundary api={api}>
        <Async rows={4} cols={4} empty={<Empty icon="fa-rotate-left" title="المرتجع غير موجود" />}>
          {r && (
          <div className="grid-2">
            <div className="stack">
              <Panel title="البنود" en="ITEMS" body={false}>
                <table className="tbl"><thead><tr><th>المنتج</th><th>الكمية</th><th>السبب</th><th>صور</th></tr></thead>
                  <tbody>{r.items.map((it, i) => <tr key={i}><td><div className="prod-cell"><Thumb sm /><div><div className="prod-name">{it.name}</div><div className="sku">{it.sku}</div></div></div></td><td className="num">{it.qty}</td><td>{it.reason}</td><td><div className="row" style={{ gap: 6 }}>{(it.attachments || []).map((u, k) => <button key={k} className="photo-chip" style={{ width: 36, height: 36 }} title="تنزيل الصورة" onClick={() => dlPhoto(u)}><i className="fa-regular fa-image" /></button>)}{it.photos > 0 && !it.attachments?.length && <span className="soft small num">{it.photos}</span>}</div></td></tr>)}</tbody></table>
              </Panel>
              <Panel title="السبب العام"><p style={{ margin: 0 }}>{r.reason}</p></Panel>
            </div>
            <div className="stack">
              <Panel title="الاسترداد" en="REFUND">
                <dl className="kv"><dt>المبلغ</dt><dd><Money v={r.refund} strong /></dd><dt>الطريقة</dt><dd>{REFUND_METHOD[r.method] || r.method || '—'}</dd><dt>المرجع</dt><dd className="sku">{r.ref || '—'}</dd></dl>
              </Panel>
              <Panel title="المراحل" en="TIMELINE">
                <ul className="tl">{steps.map(([s, d], i) => <li key={s} className={d ? (steps[i + 1] && steps[i + 1][1] ? 'is-done' : 'is-now') : 'is-future'}><div className="tl-title">{RETURN_STATUS[s] ? RETURN_STATUS[s][0] : s}</div>{d && <div className="tl-meta num">{d}</div>}</li>)}</ul>
              </Panel>
            </div>
          </div>
          )}
        </Async>
      </DataBoundary>
    </>
  );
};/* Sophie — Wholesale Portal. Built on the storefront's sophie.css / luxuryAuth.css vocabulary. */
:root {
  --ink: #111111;
  --ink-2: #1e293b;
  --body: #334155;
  --muted: #64748b;
  --soft: #94a3b8;
  --line: #cbd5e1;
  --line-2: #e5e7eb;
  --bg: #f3f5f7;
  --accent: #4f7d88;
  --accent-soft: #dfe5e9;
  --teal: #159a8c;
  --info-bg: #f0f9fa; --info-line: #cce3e8; --info-ink: #2c545e;
  --err-bg: #fef2f2; --err-line: #fecaca; --err-ink: #991b1b;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}
* { box-sizing: border-box; }
html, body { margin: 0; }
body {
  font-family: 'Poppins', 'Cairo', sans-serif;
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
button, input, select, textarea { font-family: inherit; }
.num { font-family: 'Poppins', sans-serif; font-variant-numeric: tabular-nums; direction: ltr; unicode-bidi: isolate; }
.ltr { direction: ltr; unicode-bidi: isolate; }
.osw { font-family: 'Oswald', sans-serif; text-transform: uppercase; letter-spacing: .06em; }

/* Keep the document, sidebar, tables and dialogs on the same scroll treatment. */
html:has(.wholesale-portal-app),
.wholesale-portal-app,
.wholesale-portal-app * {
  scrollbar-width: thin;
  scrollbar-color: #94a3b8 transparent;
}
html:has(.wholesale-portal-app)::-webkit-scrollbar,
.wholesale-portal-app::-webkit-scrollbar,
.wholesale-portal-app *::-webkit-scrollbar { width: 8px; height: 8px; }
html:has(.wholesale-portal-app)::-webkit-scrollbar-track,
.wholesale-portal-app::-webkit-scrollbar-track,
.wholesale-portal-app *::-webkit-scrollbar-track { background: transparent; }
html:has(.wholesale-portal-app)::-webkit-scrollbar-thumb,
.wholesale-portal-app::-webkit-scrollbar-thumb,
.wholesale-portal-app *::-webkit-scrollbar-thumb {
  background: #94a3b8;
  border: 2px solid transparent;
  background-clip: padding-box;
  border-radius: 999px;
}
html:has(.wholesale-portal-app)::-webkit-scrollbar-thumb:hover,
.wholesale-portal-app::-webkit-scrollbar-thumb:hover,
.wholesale-portal-app *::-webkit-scrollbar-thumb:hover { background-color: #4f7d88; }
html:has(.wholesale-portal-app)::-webkit-scrollbar-corner,
.wholesale-portal-app::-webkit-scrollbar-corner,
.wholesale-portal-app *::-webkit-scrollbar-corner { background: transparent; }
@media (forced-colors: active) {
  html:has(.wholesale-portal-app),
  .wholesale-portal-app,
  .wholesale-portal-app * { scrollbar-width: auto; scrollbar-color: auto; }
}

/* ============ HEADER (SophieHeader) ============ */
.wp-header {
  position: sticky; top: 0; z-index: 100;
  height: 76px; display: flex; align-items: center; justify-content: space-between;
  padding: 0 40px; background: rgba(255,255,255,.94); backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(0,0,0,.05);
}
.wp-logo { display: flex; align-items: center; gap: 8px; font-family: 'Poppins', sans-serif; font-size: 22px; font-weight: 700; letter-spacing: -.5px; color: #000; text-decoration: none; cursor: pointer; background: none; border: 0; padding: 0; }
.wp-logo-tag { font-family: 'Oswald', sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 1px; color: var(--accent); text-transform: uppercase; border: 1px solid var(--accent-soft); border-radius: 999px; padding: 3px 10px; margin-inline-start: 6px; }
.wp-head-right { display: flex; align-items: center; gap: 22px; }
.wp-credit-chip { display: flex; align-items: center; gap: 10px; font-size: 12px; color: var(--muted); padding: 7px 14px; border: 1px solid var(--line-2); border-radius: 999px; background: #fff; }
.wp-credit-chip strong { color: var(--ink); font-weight: 600; }
.wp-icon-btn { position: relative; background: none; border: 0; padding: 4px; cursor: pointer; color: var(--ink); font-size: 16px; transition: color .2s; }
.wp-icon-btn:hover { color: var(--accent); }
.wp-count { position: absolute; top: -6px; inset-inline-end: -9px; min-width: 17px; height: 17px; padding: 0 4px; border-radius: 999px; background: #000; color: #fff; font: 600 10px 'Poppins', sans-serif; display: inline-flex; align-items: center; justify-content: center; }
.wp-avatar { width: 36px; height: 36px; border-radius: 50%; background: var(--accent-soft); color: var(--info-ink); display: inline-flex; align-items: center; justify-content: center; font: 600 12px 'Poppins', sans-serif; border: 1px solid #fff; box-shadow: 0 0 0 1px var(--line-2); cursor: pointer; }

/* ============ LAYOUT ============ */
.wp-layout { display: grid; grid-template-columns: 248px minmax(0, 1fr); min-height: calc(100vh - 76px); }
.wp-side { position: sticky; top: 76px; align-self: start; height: calc(100vh - 76px); overflow-y: auto; padding: 34px 28px 40px 18px; border-inline-end: 1px solid var(--line-2); background: #fff; }
.wp-side-tag { font-family: 'Oswald', sans-serif; font-size: 11px; font-weight: 500; letter-spacing: 1px; color: var(--accent); text-transform: uppercase; margin-bottom: 18px; direction: ltr; text-align: right; }
.wp-side-group { margin-bottom: 22px; }
.wp-side-group-title { font-family: 'Oswald', sans-serif; font-size: 11px; letter-spacing: .1em; color: var(--soft); text-transform: uppercase; margin: 0 0 6px; }
.wp-side-link { display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; padding: 8px 0; background: none; border: 0; cursor: pointer; font-family: 'Cairo', sans-serif; font-size: 14px; color: #475569; text-align: start; transition: color .2s; }
.wp-side-link:hover { color: var(--accent); }
.wp-side-link.is-active { color: var(--ink); font-weight: 700; }
.wp-side-link.is-active .wp-side-dot { opacity: 1; }
.wp-side-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--accent); opacity: 0; }
.wp-side-badge { font: 600 10px 'Poppins', sans-serif; background: #111; color: #fff; border-radius: 999px; padding: 2px 7px; }
.wp-side-foot { margin-top: 30px; padding-top: 20px; border-top: 1px solid var(--line-2); }
.wp-main { padding: 42px 48px 90px; min-width: 0; }
.wp-wrap { max-width: 1180px; margin: 0 auto; }

/* ============ PAGE HEAD (checkout-giant-title) ============ */
.wp-page-top { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-bottom: 34px; }
.wp-giant { font-family: 'Oswald', sans-serif; font-size: 60px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--ink); line-height: 1; margin: 0; direction: ltr; text-align: right; }
.wp-page-ar { font-family: 'Cairo', sans-serif; font-size: 15px; color: var(--muted); margin: 10px 0 0; }
.wp-crumb { font-family: 'Cairo', sans-serif; font-size: 13px; color: var(--soft); margin-bottom: 12px; display: flex; gap: 8px; align-items: center; }
.wp-crumb button { background: none; border: 0; padding: 0; color: var(--muted); cursor: pointer; font: inherit; text-decoration: underline; text-underline-offset: 4px; }
.wp-actions { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }

/* ============ BUTTONS ============ */
.btn-pill { display: inline-flex; align-items: center; gap: 8px; border: 1px solid var(--line); background: #fff; padding: 9px 18px; border-radius: 999px; font: 500 12.5px 'Cairo', sans-serif; color: var(--body); cursor: pointer; transition: all .2s ease; text-decoration: none; white-space: nowrap; }
.btn-pill:hover { background: var(--ink); color: #fff; border-color: var(--ink); }
.btn-pill.is-dark { background: var(--ink); color: #fff; border-color: var(--ink); }
.btn-pill.is-dark:hover { background: #2c2c2c; }
.btn-pill.is-danger { color: #b91c1c; border-color: #fecaca; }
.btn-pill.is-danger:hover { background: #b91c1c; color: #fff; border-color: #b91c1c; }
.btn-pill:disabled { opacity: .45; cursor: not-allowed; background: #fff; color: var(--body); border-color: var(--line); }
.btn-pill.sm { padding: 6px 12px; font-size: 12px; }
.btn-block { width: 100%; background: #1a1a1a; color: #fff; border: 0; padding: 16px 24px; font: 500 13px 'Oswald', 'Cairo', sans-serif; letter-spacing: 1px; text-transform: uppercase; cursor: pointer; transition: background-color .2s, transform .15s; display: inline-flex; align-items: center; justify-content: center; gap: 10px; }
.btn-block:hover { background: var(--teal); transform: translateY(-1px); }
.btn-block:disabled { opacity: .5; cursor: not-allowed; transform: none; background: #1a1a1a; }
.btn-soft { background: var(--accent-soft); color: var(--body); border: 0; padding: 11px 16px; font: 500 12px 'Cairo', sans-serif; cursor: pointer; transition: background-color .2s, color .2s; white-space: nowrap; }
.btn-soft:hover { background: var(--ink); color: #fff; }
.btn-link { background: none; border: 0; padding: 0; color: var(--ink); font: 600 13px 'Cairo', sans-serif; text-decoration: underline; text-underline-offset: 4px; cursor: pointer; }
.btn-link:hover { color: var(--accent); }
.btn-link.muted { color: var(--muted); font-weight: 500; }
.btn-link.danger { color: #b91c1c; }

/* ============ PANELS ============ */
.panel { background: #fff; border: 1px solid var(--line-2); border-radius: 4px; }
.panel-head { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; padding: 20px 24px 0; }
.panel-title { font-family: 'Cairo', sans-serif; font-size: 17px; font-weight: 700; color: var(--ink); margin: 0; }
.panel-en { font-family: 'Oswald', sans-serif; font-size: 11px; letter-spacing: .1em; color: var(--soft); text-transform: uppercase; }
.panel-body { padding: 18px 24px 24px; }
.grid-2 { display: grid; grid-template-columns: 1.4fr 1fr; gap: 28px; align-items: start; }
.grid-2e { display: grid; grid-template-columns: 1fr 1fr; gap: 28px; align-items: start; }
.stack { display: flex; flex-direction: column; gap: 24px; }

/* KPI tiles */
.kpis { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 16px; margin-bottom: 28px; }
.kpi { background: #fff; border: 1px solid var(--line-2); border-radius: 4px; padding: 20px 22px 22px; display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.kpi.is-ink { background: var(--ink); color: #fff; border-color: var(--ink); }
.kpi-label { font-family: 'Cairo', sans-serif; font-size: 13px; color: var(--muted); }
.kpi.is-ink .kpi-label { color: #a3a3a3; }
.kpi-en { font-family: 'Oswald', sans-serif; font-size: 10px; letter-spacing: .12em; color: var(--soft); text-transform: uppercase; direction: ltr; }
.kpi-value { font-family: 'Poppins', sans-serif; font-size: 26px; font-weight: 600; letter-spacing: -.5px; direction: ltr; text-align: right; }
.kpi-value small { font-size: 12px; font-weight: 500; color: var(--soft); margin-inline-start: 4px; }
.kpi-bar { height: 4px; background: var(--accent-soft); border-radius: 4px; overflow: hidden; }
.kpi-bar > span { display: block; height: 100%; background: var(--accent); }
.kpi-foot { font-size: 12px; color: var(--muted); }

/* ============ TABLES ============ */
.tbl-wrap { overflow-x: auto; }
.tbl { width: 100%; border-collapse: collapse; font-size: 13px; }
.tbl th { font-family: 'Cairo', sans-serif; font-weight: 600; font-size: 12px; color: var(--soft); text-align: start; padding: 12px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; }
.tbl td { padding: 14px 12px; border-bottom: 1px solid var(--line-2); color: var(--body); vertical-align: middle; }
.tbl tr:last-child td { border-bottom: 0; }
.tbl td.strong, .tbl .strong { color: var(--ink); font-weight: 600; }
.tbl tr.is-click { cursor: pointer; transition: background .15s; }
.tbl tr.is-click:hover td { background: #fafbfc; }
.tbl tr.is-error td { background: #fffafa; }
.tbl tr.is-warn td { background: #fffdf5; }
.tbl .t-end { text-align: end; }
.tbl tfoot td { border-top: 1px solid var(--line); border-bottom: 0; font-weight: 600; color: var(--ink); }
.row-actions { display: flex; gap: 14px; justify-content: flex-end; align-items: center; white-space: nowrap; }

/* ============ BADGES (@alfarid/ui Badge) ============ */
.badge { display: inline-flex; align-items: center; gap: 6px; border-radius: 999px; border: 1px solid; padding: 2px 10px; font: 500 12px 'Cairo', sans-serif; white-space: nowrap; line-height: 1.7; }
.badge::before { content: ''; width: 6px; height: 6px; border-radius: 50%; background: currentColor; opacity: .8; }
.badge.default { background: #f4f4f5; color: #3f3f46; border-color: #e4e4e7; }
.badge.success { background: #ecfdf5; color: #047857; border-color: #a7f3d0; }
.badge.warning { background: #fffbeb; color: #b45309; border-color: #fde68a; }
.badge.danger { background: #fff1f2; color: #be123c; border-color: #fecdd3; }
.badge.info { background: #f0f9ff; color: #0369a1; border-color: #bae6fd; }
.badge.accent { background: var(--info-bg); color: var(--info-ink); border-color: var(--info-line); }
.badge.lg { font-size: 14px; padding: 5px 14px; }

/* ============ FORMS (line inputs) ============ */
.fields { display: grid; grid-template-columns: 1fr 1fr; column-gap: 28px; row-gap: 22px; }
.fields .span-2 { grid-column: 1 / -1; }
.f-label { display: block; font: 600 12.5px 'Cairo', sans-serif; color: var(--ink-2); margin-bottom: 4px; }
.f-req { color: var(--accent); margin-inline-start: 4px; }
.f-opt { color: var(--soft); font-weight: 400; margin-inline-start: 6px; font-size: 11.5px; }
.line-input { width: 100%; background: transparent; border: 0; border-bottom: 1px solid var(--line); padding: 10px 0; font: 13.5px 'Cairo', 'Poppins', sans-serif; color: var(--ink); outline: none; transition: border-color .2s; border-radius: 0; }
.line-input::placeholder { color: var(--soft); }
.line-input:focus { border-bottom-color: var(--teal); }
.line-input.is-invalid { border-bottom-color: #dc2626; }
select.line-input { appearance: none; background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%); background-position: 8px 55%, 13px 55%; background-size: 5px 5px; background-repeat: no-repeat; padding-inline-end: 0; padding-inline-start: 0; cursor: pointer; }
textarea.line-input { resize: vertical; min-height: 84px; line-height: 1.8; }
.f-error { margin: 6px 0 0; color: #b91c1c; font-size: 12px; display: flex; gap: 6px; align-items: center; }
.f-hint { margin: 6px 0 0; color: var(--soft); font-size: 11.5px; line-height: 1.7; }
.f-counter { font-family: 'Poppins', sans-serif; font-size: 11px; color: var(--soft); }
.box-input { width: 100%; border: 1px solid var(--line); background: #fff; border-radius: 3px; padding: 8px 10px; font: 13px 'Poppins', 'Cairo', sans-serif; color: var(--ink); outline: none; }
.box-input:focus { border-color: var(--teal); }
.box-input.is-invalid { border-color: #dc2626; background: #fffafa; }

.radio-list { display: flex; flex-direction: column; }
.radio-row { border-bottom: 1px solid var(--line); padding: 14px 0; display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; cursor: pointer; }
.radio-row.is-disabled { cursor: not-allowed; opacity: .55; }
.radio-left { display: flex; gap: 10px; align-items: flex-start; }
.radio-left input { accent-color: var(--ink); margin-top: 5px; }
.radio-title { font-size: 13.5px; font-weight: 600; color: var(--ink); display: block; }
.radio-desc { font-size: 12px; color: var(--soft); display: block; margin-top: 2px; }
.radio-price { font-size: 13px; font-weight: 600; color: var(--ink); white-space: nowrap; }
.check-row { display: flex; align-items: flex-start; gap: 10px; font-size: 12.5px; color: var(--muted); cursor: pointer; line-height: 1.7; }
.check-row input { accent-color: var(--ink); width: 15px; height: 15px; margin-top: 4px; }

.seg { display: inline-flex; background: #f4f6f8; border: 1px solid #e9ecef; border-radius: 30px; padding: 4px; gap: 4px; }
.seg button { padding: 7px 16px; border-radius: 20px; border: 0; background: transparent; color: #777; cursor: pointer; font: 500 12.5px 'Cairo', sans-serif; display: inline-flex; gap: 6px; align-items: center; transition: all .25s; }
.seg button.is-on { background: #000; color: #fff; box-shadow: 0 2px 8px rgba(0,0,0,.15); }
.seg button .seg-n { font: 600 10px 'Poppins', sans-serif; opacity: .7; }

.chips { display: flex; gap: 8px; flex-wrap: wrap; }
.chip { border: 1px solid var(--line); background: #fff; border-radius: 999px; padding: 6px 14px; font: 500 12.5px 'Cairo', sans-serif; color: var(--body); cursor: pointer; transition: all .2s; display: inline-flex; gap: 6px; align-items: center; }
.chip:hover { border-color: var(--ink); }
.chip.is-on { background: var(--ink); color: #fff; border-color: var(--ink); }
.chip .num { font-size: 11px; opacity: .65; }

.toolbar { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 18px 24px; border-bottom: 1px solid var(--line-2); }
.search { position: relative; min-width: 300px; }
.search i { position: absolute; inset-inline-start: 0; top: 50%; transform: translateY(-50%); color: var(--soft); font-size: 13px; }
.search .line-input { padding-inline-start: 24px; }

/* qty stepper */
.qty { display: inline-flex; align-items: center; border: 1px solid var(--line); border-radius: 999px; background: #fff; height: 32px; }
.qty button { width: 30px; height: 30px; border: 0; background: none; cursor: pointer; color: var(--ink); font-size: 11px; border-radius: 50%; }
.qty button:hover { background: var(--ink); color: #fff; }
.qty input { width: 48px; border: 0; text-align: center; font: 600 13px 'Poppins', sans-serif; outline: none; background: transparent; }

/* banners (checkout-banner) */
.banner { display: flex; align-items: flex-start; gap: 12px; border-radius: 4px; padding: 12px 16px; font-size: 13px; line-height: 1.8; border: 1px solid; }
.banner i { margin-top: 5px; }
.banner.is-error { background: var(--err-bg); color: var(--err-ink); border-color: var(--err-line); }
.banner.is-info { background: var(--info-bg); color: var(--info-ink); border-color: var(--info-line); }
.banner.is-warn { background: #fffbeb; color: #92400e; border-color: #fde68a; }
.banner.is-ok { background: #ecfdf5; color: #065f46; border-color: #a7f3d0; }
.banner .banner-body { flex: 1; }
.banner strong { font-weight: 700; }

/* summary rows (bag-totals-row) */
.sum-row { display: flex; align-items: center; justify-content: space-between; padding: 11px 0; border-bottom: 1px solid var(--line); font-size: 13px; color: var(--body); gap: 12px; }
.sum-row strong { color: var(--ink); font-weight: 600; }
.sum-row.is-neg strong { color: var(--teal); }
.sum-total { display: flex; align-items: baseline; justify-content: space-between; padding-top: 18px; font-size: 16px; font-weight: 700; color: var(--ink); }
.sum-total .num { font-size: 24px; font-weight: 700; }
.kv { display: grid; grid-template-columns: 130px 1fr; row-gap: 12px; column-gap: 16px; font-size: 13px; }
.kv dt { color: var(--soft); }
.kv dd { margin: 0; color: var(--ink); font-weight: 600; min-width: 0; overflow-wrap: anywhere; }

/* thumbs */
.thumb { width: 64px; height: 72px; background: #e4e9ed; display: flex; align-items: center; justify-content: center; border-radius: 2px; color: #a9b6bf; font-size: 22px; flex-shrink: 0; }
.thumb.sm { width: 44px; height: 50px; font-size: 16px; }
.prod-cell { display: flex; gap: 14px; align-items: center; min-width: 0; }
.prod-name { font-weight: 600; color: var(--ink); font-size: 13.5px; }
.prod-en { font-family: 'Poppins', sans-serif; font-size: 11.5px; color: var(--soft); direction: ltr; text-align: right; }
.sku { font-family: 'JetBrains Mono', monospace; font-size: 11.5px; color: var(--muted); direction: ltr; unicode-bidi: isolate; }
.strike { text-decoration: line-through; color: var(--soft); font-weight: 400; }
.tier { display: inline-flex; gap: 4px; align-items: baseline; border: 1px solid var(--info-line); background: var(--info-bg); color: var(--info-ink); border-radius: 3px; padding: 2px 7px; font-size: 11.5px; margin: 2px 0 2px 4px; white-space: nowrap; }

/* pager */
.pager { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 24px; border-top: 1px solid var(--line-2); font-size: 12.5px; color: var(--muted); }
.pager-btns { display: flex; gap: 4px; }
.pager-btns button { min-width: 32px; height: 32px; border-radius: 50%; border: 1px solid transparent; background: none; cursor: pointer; font: 500 12px 'Poppins', sans-serif; color: var(--body); }
.pager-btns button:hover { border-color: var(--line); }
.pager-btns button.is-on { background: var(--ink); color: #fff; }
.pager-btns button:disabled { opacity: .35; cursor: default; }

/* timeline */
.tl { list-style: none; margin: 0; padding: 0; }
.tl li { position: relative; padding: 0 26px 22px 0; }
.tl li::before { content: ''; position: absolute; right: 5px; top: 8px; bottom: -4px; width: 1px; background: var(--line); }
.tl li:last-child::before { display: none; }
.tl li::after { content: ''; position: absolute; right: 0; top: 4px; width: 11px; height: 11px; border-radius: 50%; background: #fff; border: 1px solid var(--line); }
.tl li.is-done::after { background: var(--accent); border-color: var(--accent); }
.tl li.is-now::after { background: #fff; border: 3px solid var(--accent); }
.tl-title { font-weight: 600; font-size: 13.5px; color: var(--ink); }
.tl li.is-future .tl-title { color: var(--soft); font-weight: 500; }
.tl-meta { font-size: 12px; color: var(--soft); margin-top: 2px; }

/* drop zone (luxury-file-picker) */
.drop { position: relative; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; min-height: 150px; border: 1px dashed #a3a3a3; border-radius: 12px; background: #fafafa; color: #262626; font-size: 14px; text-align: center; padding: 24px; cursor: pointer; transition: border-color .2s, background .2s; }
.drop:hover { border-color: var(--ink); background: #fff; }
.drop i { font-size: 26px; color: var(--accent); }
.drop small { color: var(--muted); font-size: 12px; }
.drop.sm { min-height: 64px; flex-direction: row; padding: 12px; font-size: 13px; }
.drop.sm i { font-size: 16px; }
.drop.is-invalid { border-color: #dc2626; background: #fffafa; }
.file-row { display: flex; align-items: center; gap: 12px; padding: 10px 14px; border: 1px solid var(--line-2); border-radius: 10px; background: #fff; font-size: 12.5px; }
.file-row i.fa-file-pdf, .file-row i.fa-file-image, .file-row i.fa-file-excel { color: var(--accent); font-size: 18px; }
.file-row .grow { flex: 1; min-width: 0; overflow-wrap: anywhere; }
.photo-chip { width: 52px; height: 52px; border-radius: 6px; background: #e4e9ed; display: inline-flex; align-items: center; justify-content: center; color: #9aa8b2; font-size: 15px; position: relative; }

/* states */
.state { display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 70px 24px; gap: 10px; }
.state-icon { width: 64px; height: 64px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 24px; background: #f1f5f9; color: var(--soft); margin-bottom: 6px; }
.state-icon.is-err { background: var(--err-bg); color: #dc2626; }
.state-title { font-family: 'Cairo', sans-serif; font-size: 18px; font-weight: 700; margin: 0; }
.state-desc { font-size: 13px; color: var(--muted); max-width: 380px; line-height: 1.8; margin: 0 0 8px; }
.sk { background: linear-gradient(90deg,#f0f1f3 25%,#e6e8eb 37%,#f0f1f3 63%); background-size: 400% 100%; animation: skShimmer 1.2s ease infinite; border-radius: 3px; }
@keyframes skShimmer { 0% { background-position: 100% 50%; } 100% { background-position: 0 50%; } }
.spin { width: 14px; height: 14px; border: 2px solid currentColor; border-top-color: transparent; border-radius: 50%; display: inline-block; animation: spin .7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

/* modal (order-modal) */
.modal-bg { position: fixed; inset: 0; background: rgba(15,23,42,.55); backdrop-filter: blur(4px); display: flex; align-items: center; justify-content: center; z-index: 500; padding: 20px; animation: fadeIn .2s ease; }
@keyframes fadeIn { from { opacity: 0; } }
.modal { background: #fff; width: 100%; max-width: 560px; border-radius: 16px; box-shadow: 0 25px 60px rgba(0,0,0,.22); max-height: calc(100vh - 40px); display: flex; flex-direction: column; animation: popIn .3s var(--ease); }
.modal.wide { max-width: 820px; }
@keyframes popIn { from { transform: translateY(12px); opacity: 0; } }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding: 26px 30px 0; }
.modal-title { font-family: 'Cairo', sans-serif; font-size: 20px; font-weight: 700; margin: 0; }
.modal-x { width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line-2); background: #fff; cursor: pointer; color: var(--muted); flex-shrink: 0; }
.modal-x:hover { background: var(--ink); color: #fff; }
.modal-body { padding: 20px 30px; overflow-y: auto; }
.modal-foot { padding: 0 30px 26px; display: flex; gap: 10px; justify-content: flex-end; flex-wrap: wrap; }
.modal-icon { width: 56px; height: 56px; border-radius: 50%; background: #e6f6f4; color: var(--teal); font-size: 22px; display: inline-flex; align-items: center; justify-content: center; }
.modal-icon.is-warn { background: #fffbeb; color: #b45309; }
.modal-icon.is-err { background: var(--err-bg); color: #dc2626; }

/* toast */
.toast { position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%); background: #0f172a; color: #fff; padding: 12px 20px; border-radius: 999px; font-size: 13px; display: flex; align-items: center; gap: 12px; box-shadow: 0 12px 30px rgba(0,0,0,.22); z-index: 999; animation: toastIn .3s var(--ease); }
.toast i { color: var(--teal); }
.toast button { background: var(--teal); color: #fff; border: 0; border-radius: 999px; padding: 4px 12px; font: 600 11.5px 'Cairo', sans-serif; cursor: pointer; }
@keyframes toastIn { from { transform: translate(-50%, 15px); opacity: 0; } }

/* steps */
.steps { display: flex; gap: 18px; list-style: none; margin: 0 0 26px; padding: 0; font-family: 'Cairo', sans-serif; font-size: 13px; }
.step { display: flex; align-items: center; gap: 8px; color: var(--soft); }
.step-dot { width: 26px; height: 26px; border-radius: 50%; border: 1px solid var(--line); display: inline-flex; align-items: center; justify-content: center; font: 12px 'Poppins', sans-serif; }
.step.is-now { color: #111827; font-weight: 600; }
.step.is-now .step-dot { border-color: var(--accent); color: var(--accent); }
.step.is-done { color: var(--accent); }
.step.is-done .step-dot { background: var(--accent); border-color: var(--accent); color: #fff; }

/* notifications */
.notif { display: grid; grid-template-columns: 40px 1fr auto; gap: 16px; padding: 18px 24px; border-bottom: 1px solid var(--line-2); align-items: start; }
.notif.is-unread { background: #fbfcfd; }
.notif-ic { width: 40px; height: 40px; border-radius: 50%; background: #f1f5f9; color: var(--muted); display: inline-flex; align-items: center; justify-content: center; position: relative; }
.notif.is-unread .notif-ic { background: var(--info-bg); color: var(--accent); }
.notif.is-unread .notif-ic::after { content: ''; position: absolute; top: 0; inset-inline-end: 0; width: 9px; height: 9px; border-radius: 50%; background: var(--teal); border: 2px solid #fff; }
.notif-title { font-weight: 600; font-size: 14px; color: var(--ink); margin: 0 0 4px; }
.notif:not(.is-unread) .notif-title { font-weight: 500; color: var(--body); }
.notif-body { font-size: 13px; color: var(--muted); margin: 0; line-height: 1.8; }
.notif-time { font-size: 11.5px; color: var(--soft); white-space: nowrap; }

.muted { color: var(--muted); }
.soft { color: var(--soft); }
.small { font-size: 12px; }
.mt-8 { margin-top: 8px; } .mt-16 { margin-top: 16px; } .mt-24 { margin-top: 24px; }
.mb-16 { margin-bottom: 16px; } .mb-24 { margin-bottom: 24px; }
.row { display: flex; align-items: center; gap: 12px; }
.between { justify-content: space-between; }
.wrap { flex-wrap: wrap; }
.divider { height: 1px; background: var(--line-2); margin: 20px 0; }
.note { font-size: 12px; color: var(--soft); line-height: 1.8; display: flex; gap: 8px; align-items: flex-start; }
.note i { margin-top: 5px; }

/* session expired */
.expired-bg { position: fixed; inset: 0; z-index: 600; background: rgba(255,255,255,.7); backdrop-filter: blur(6px); display: flex; align-items: center; justify-content: center; padding: 20px; }

@media (max-width: 1100px) {
  .kpis { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .grid-2, .grid-2e { grid-template-columns: 1fr; }
}
@media (max-width: 900px) {
  .wp-layout { grid-template-columns: 1fr; }
  .wp-side { position: static; height: auto; border: 0; border-bottom: 1px solid var(--line-2); padding: 14px 20px; display: flex; gap: 8px; overflow-x: auto; }
  .wp-side-tag, .wp-side-group-title, .wp-side-foot { display: none; }
  .wp-side-group { display: contents; }
  .wp-side-link { white-space: nowrap; width: auto; padding: 6px 12px; border: 1px solid var(--line-2); border-radius: 999px; }
  .wp-side-dot { display: none; }
  .wp-main { padding: 28px 18px 80px; }
  .wp-giant { font-size: 42px; }
  .wp-credit-chip { display: none; }
  .wp-header { padding: 0 18px; }
  .fields { grid-template-columns: 1fr; }
  .search { min-width: 0; flex: 1; }
}

/* ============ SCREEN-SPECIFIC ============ */
.dash-shortcuts { display: grid; grid-template-columns: repeat(4, minmax(0,1fr)); gap: 16px; margin-bottom: 28px; }
.dash-sc { display: flex; align-items: center; gap: 14px; padding: 18px 20px; background: #fff; border: 1px solid var(--line-2); border-radius: 4px; cursor: pointer; text-align: start; transition: all .25s var(--ease); }
.dash-sc > i:first-child { width: 40px; height: 40px; border-radius: 50%; background: var(--accent-soft); color: var(--info-ink); display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; transition: all .25s; }
.dash-sc span { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dash-sc b { font: 700 14px 'Cairo', sans-serif; color: var(--ink); }
.dash-sc small { font: 500 10px 'Oswald', sans-serif; letter-spacing: .12em; color: var(--soft); direction: ltr; text-align: right; }
.dash-sc-arrow { color: var(--soft); font-size: 12px; transition: transform .25s var(--ease); }
.dash-sc:hover { border-color: var(--ink); }
.dash-sc:hover > i:first-child { background: var(--ink); color: #fff; }
.dash-sc:hover .dash-sc-arrow { transform: translateX(-4px); color: var(--ink); }

.imp-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.imp-stats > div { border: 1px solid var(--line-2); border-radius: 4px; padding: 16px 18px; display: flex; flex-direction: column; gap: 4px; }
.imp-stats .num { font-size: 30px; font-weight: 600; color: var(--teal); text-align: right; }
.imp-stats .is-warn .num { color: #b45309; }
.imp-stats small { color: var(--muted); font-size: 12.5px; }
.imp-sample { margin-top: 12px; border: 1px solid var(--line-2); }
.imp-sample th { background: #fafbfc; font-family: 'JetBrains Mono', monospace; text-align: left; }
.imp-sample td { text-align: left; }

.checkout-heading { font-family: 'Cairo', sans-serif; font-size: 20px; font-weight: 600; color: var(--ink); letter-spacing: -.2px; margin: 0 0 20px; }
.ck-block { border: 0; padding: 0; margin: 0 0 44px; min-width: 0; }
.ck-block:disabled { opacity: .7; }
.cart-row { display: grid; grid-template-columns: 88px 1fr auto; gap: 18px; padding: 20px 0; border-bottom: 1px solid var(--line); align-items: start; }
.cart-row:first-child { padding-top: 0; }
.cart-row .thumb { width: 88px; height: 104px; font-size: 28px; }
.cart-row.is-bad .thumb { outline: 1px solid #fecaca; }
.cart-info { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.cart-meta { display: grid; grid-template-columns: 78px 1fr; row-gap: 4px; font-size: 12px; }
.cart-meta span { color: var(--soft); }
.cart-meta b { color: var(--ink-2); font-weight: 600; }
.cart-right { display: flex; flex-direction: column; align-items: flex-end; gap: 30px; }
.promo { display: flex; gap: 14px; align-items: flex-end; margin: 0 0 22px; }
.promo-chip { display: inline-flex; align-items: center; gap: 8px; background: var(--info-bg); color: var(--info-ink); border: 1px solid var(--info-line); border-radius: 999px; padding: 6px 14px 6px 6px; font-size: 13px; font-weight: 600; }
.promo-chip button { width: 22px; height: 22px; border-radius: 50%; border: 0; background: var(--accent); color: #fff; cursor: pointer; line-height: 1; }
.addr-picks { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 10px; }
.addr-pick { text-align: start; background: #fff; border: 1px solid var(--line); border-radius: 4px; padding: 14px 16px; cursor: pointer; display: flex; flex-direction: column; gap: 4px; transition: border-color .2s, box-shadow .2s; font-family: 'Cairo', sans-serif; }
.addr-pick b { font-size: 13.5px; color: var(--ink); display: flex; align-items: center; }
.addr-pick span { font-size: 12px; color: var(--muted); }
.addr-pick:hover { border-color: var(--muted); }
.addr-pick.is-on { border-color: var(--ink); box-shadow: inset 0 0 0 1px var(--ink); }
.ck-items { margin-bottom: 8px; }
.ck-item { display: flex; align-items: center; gap: 14px; padding: 12px 0; border-bottom: 1px solid var(--line); }

.success-wrap { display: flex; justify-content: center; padding: 20px 0 40px; }
.order-card { background: #fff; max-width: 520px; width: 100%; border-radius: 16px; padding: 40px 36px; text-align: center; box-shadow: 0 25px 60px rgba(0,0,0,.08); border: 1px solid var(--line-2); }
.success-title { font-family: 'Oswald', sans-serif; font-size: 34px; font-weight: 700; letter-spacing: 1px; margin: 18px 0 6px; }
.success-num { font-size: 22px; font-weight: 600; margin: 0 0 12px; letter-spacing: .5px; }

.qf-suggest { position: absolute; top: 100%; inset-inline: 24px; margin-top: -8px; background: #fff; border: 1px solid var(--line-2); border-radius: 8px; box-shadow: 0 18px 40px rgba(15,23,42,.12); z-index: 20; overflow: hidden; }
.qf-suggest button { display: flex; align-items: center; gap: 12px; width: 100%; padding: 10px 14px; background: none; border: 0; border-bottom: 1px solid var(--line-2); cursor: pointer; text-align: start; font-family: 'Cairo', sans-serif; }
.qf-suggest button:hover { background: #fafbfc; }
.qf-suggest b { display: block; font-size: 13px; }

.note-bubble { background: #fafbfc; border: 1px solid var(--line-2); border-radius: 12px; padding: 12px 16px; margin-bottom: 12px; }
.note-bubble span { font-size: 11.5px; color: var(--soft); font-weight: 600; }
.note-bubble p { margin: 4px 0 0; font-size: 13px; line-height: 1.9; color: var(--body); }
.note-bubble.is-admin { background: var(--info-bg); border-color: var(--info-line); }
.note-bubble.is-admin span { color: var(--accent); }

.ret-item { padding: 16px 0; border-bottom: 1px solid var(--line-2); }
.ret-item:last-child { border-bottom: 0; }
.ret-item.is-on { background: #fcfdfd; }

.inv-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; padding-bottom: 16px; border-bottom: 1px solid var(--line); }
.out-row { display: flex; justify-content: space-between; align-items: center; padding: 14px 24px; border-bottom: 1px solid var(--line-2); cursor: pointer; font-size: 13px; }
.out-row:hover { background: #fafbfc; }
.out-row div { display: flex; flex-direction: column; }
.out-row div span { font-size: 11.5px; color: var(--soft); }

.wallet-hero { background: var(--ink); color: #fff; border-radius: 4px; padding: 30px 32px; display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; flex-wrap: wrap; position: relative; overflow: hidden; }
.wallet-hero::after { content: 'WALLET'; position: absolute; left: -10px; bottom: -34px; font: 700 130px 'Oswald', sans-serif; color: rgba(255,255,255,.04); letter-spacing: 4px; pointer-events: none; }
.wallet-amt { font-size: 44px; font-weight: 600; letter-spacing: -1px; margin: 8px 0 4px; text-align: right; }
.wallet-amt small { font-size: 15px; color: #a3a3a3; font-weight: 500; }
.wtx-ic { width: 30px; height: 30px; border-radius: 50%; background: #e6f6f4; color: var(--teal); display: inline-flex; align-items: center; justify-content: center; font-size: 11px; }
.wtx-ic.neg { background: var(--err-bg); color: #b91c1c; }

.acct-hero { display: flex; align-items: center; gap: 20px; background: #fff; border: 1px solid var(--line-2); border-radius: 4px; padding: 24px 28px; }
.acct-name { font: 700 22px 'Cairo', sans-serif; }
.addr-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px; }
.addr-card { border: 1px solid var(--line-2); border-radius: 4px; padding: 16px 18px; font-family: 'Cairo', sans-serif; }
.addr-card.is-def { border-color: var(--accent); background: #fbfdfd; }

/* proto nav (screen jumper) */
.proto-bar { position: fixed; bottom: 18px; left: 18px; z-index: 400; display: flex; gap: 8px; align-items: center; background: #fff; border: 1px solid var(--line-2); border-radius: 999px; padding: 6px 6px 6px 14px; box-shadow: 0 12px 30px rgba(15,23,42,.12); font-size: 12px; }
.proto-bar select { border: 0; background: #f4f6f8; border-radius: 999px; padding: 7px 12px; font: 500 12px 'Cairo', sans-serif; cursor: pointer; outline: none; max-width: 240px; }
.proto-bar span { font: 500 10px 'Oswald', sans-serif; letter-spacing: .12em; color: var(--soft); }

@media (max-width: 1100px) { .dash-shortcuts { grid-template-columns: repeat(2, minmax(0,1fr)); } .addr-grid { grid-template-columns: 1fr 1fr; } }
@media (max-width: 700px) { .addr-picks, .addr-grid { grid-template-columns: 1fr; } }

.tbl td.num, .tbl td .num, .tbl .sku, .tbl td.strong.num { white-space: nowrap; }
.wp-side-link span:first-child { white-space: nowrap; }
.dash-tables { display: grid; grid-template-columns: 1fr; gap: 24px; }
@media (min-width: 1500px) { .dash-tables { grid-template-columns: 1fr 1fr; } }
.badge { white-space: nowrap; }

.f-label, .radio-title, .kpi-label, .sum-row > span:first-child { white-space: nowrap; }
.radio-left > span { min-width: 0; }import React, { useEffect } from 'react';

/* Shared primitives — mirror @alfarid/ui + sophie.css patterns. */

export const Badge = ({ map, k, lg }) => {
  const [label, v] = map[k] || [k, 'default'];
  return <span className={`badge ${v}${lg ? ' lg' : ''}`}>{label}</span>;
};

export const PageHead = ({ en, ar, crumb, children }) => (
  <div className="wp-page-top">
    <div>
      {crumb && <div className="wp-crumb">{crumb}</div>}
      <h1 className="wp-giant">{en}</h1>
      {ar && <p className="wp-page-ar">{ar}</p>}
    </div>
    {children && <div className="wp-actions">{children}</div>}
  </div>
);

export const Crumb = ({ items }) => (
  <>{items.map((it, i) => (
    <React.Fragment key={i}>
      {i > 0 && <i className="fa-solid fa-chevron-left" style={{ fontSize: 9 }} />}
      {it.go ? <button onClick={it.go}>{it.label}</button> : <span className={it.mono ? 'num' : ''}>{it.label}</span>}
    </React.Fragment>
  ))}</>
);

export const Panel = ({ title, en, action, children, body = true, style }) => (
  <section className="panel" style={style}>
    {(title || action) && (
      <div className="panel-head">
        <div className="row" style={{ gap: 10, alignItems: 'baseline' }}>
          {title && <h2 className="panel-title">{title}</h2>}
          {en && <span className="panel-en">{en}</span>}
        </div>
        {action}
      </div>
    )}
    {body ? <div className="panel-body">{children}</div> : children}
  </section>
);

/* Loading / empty / error */
export const SkeletonRows = ({ rows = 5, cols = 5 }) => (
  <div style={{ padding: '18px 24px' }} aria-busy="true" aria-label="جارٍ التحميل">
    {Array.from({ length: rows }).map((_, r) => (
      <div key={r} style={{ display: 'grid', gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: 18, padding: '14px 0', borderBottom: '1px solid var(--line-2)' }}>
        {Array.from({ length: cols }).map((_, c) => <div key={c} className="sk" style={{ height: 12, width: `${55 + ((r * 7 + c * 13) % 40)}%` }} />)}
      </div>
    ))}
  </div>
);
export const Empty = ({ icon = 'fa-inbox', title, desc, action }) => (
  <div className="state">
    <div className="state-icon"><i className={`fa-solid ${icon}`} /></div>
    <p className="state-title">{title}</p>
    {desc && <p className="state-desc">{desc}</p>}
    {action}
  </div>
);
export const ErrorState = ({ onRetry, title = 'تعذر تحميل البيانات', desc = 'حصلت مشكلة في الاتصال بالخادم. تأكد من الاتصال وحاول مرة أخرى.' }) => (
  <div className="state" role="alert">
    <div className="state-icon is-err"><i className="fa-solid fa-triangle-exclamation" /></div>
    <p className="state-title">{title}</p>
    <p className="state-desc">{desc}</p>
    <button className="btn-pill is-dark" onClick={onRetry}><i className="fa-solid fa-rotate-right" /> إعادة المحاولة</button>
  </div>
);

/* Async wrapper — global "data state" tweak drives it */
export const DataStateCtx = React.createContext({ state: 'ready', retry: () => {} });
export const Async = ({ children, empty, rows, cols, isEmpty }) => {
  const { state, retry } = React.useContext(DataStateCtx);
  if (state === 'loading') return <SkeletonRows rows={rows} cols={cols} />;
  if (state === 'error') return <ErrorState onRetry={retry} />;
  if (state === 'empty' || isEmpty) return empty || <Empty title="لا توجد بيانات" />;
  return children;
};

export const Pager = ({ page = 1, pages = 3, total, per = 15, onPage = () => {} }) => (
  <div className="pager">
    <span>عرض <span className="num">{total ? (page - 1) * per + 1 : 0}–{Math.min(page * per, total)}</span> من <span className="num">{total}</span></span>
    <div className="pager-btns">
      <button disabled={page === 1} onClick={() => onPage(page - 1)} aria-label="السابق"><i className="fa-solid fa-chevron-right" /></button>
      {Array.from({ length: pages }).map((_, i) => <button key={i} className={page === i + 1 ? 'is-on' : ''} onClick={() => onPage(i + 1)}>{i + 1}</button>)}
      <button disabled={page === pages} onClick={() => onPage(page + 1)} aria-label="التالي"><i className="fa-solid fa-chevron-left" /></button>
    </div>
  </div>
);

export const Field = ({ label, req, opt, error, hint, span, children, counter }) => (
  <div className={span ? 'span-2' : ''}>
    <div className="row between">
      <label className="f-label">{label}{req && <span className="f-req">*</span>}{opt && <span className="f-opt">(اختياري)</span>}</label>
      {counter}
    </div>
    {children}
    {error && <p className="f-error" role="alert"><i className="fa-solid fa-circle-exclamation" />{error}</p>}
    {!error && hint && <p className="f-hint">{hint}</p>}
  </div>
);

export const Modal = ({ title, onClose, children, foot, wide, icon }) => {
  useEffect(() => {
    const k = (e) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [onClose]);
  return (
    <div className="modal-bg" onMouseDown={(e) => e.target === e.currentTarget && onClose()}>
      <div className={`modal${wide ? ' wide' : ''}`} role="dialog" aria-modal="true">
        <div className="modal-head">
          <div className="row" style={{ gap: 14 }}>
            {icon}
            <h2 className="modal-title">{title}</h2>
          </div>
          <button className="modal-x" onClick={onClose} aria-label="إغلاق"><i className="fa-solid fa-xmark" /></button>
        </div>
        <div className="modal-body">{children}</div>
        {foot && <div className="modal-foot">{foot}</div>}
      </div>
    </div>
  );
};

export const Banner = ({ kind = 'info', icon, children, action }) => (
  <div className={`banner is-${kind}`} role={kind === 'error' ? 'alert' : 'status'}>
    <i className={`fa-solid ${icon || { info: 'fa-circle-info', error: 'fa-circle-exclamation', warn: 'fa-triangle-exclamation', ok: 'fa-circle-check' }[kind]}`} />
    <div className="banner-body">{children}</div>
    {action}
  </div>
);

export const Qty = ({ value, onChange, min = 0 }) => (
  <div className="qty ltr">
    <button type="button" onClick={() => onChange(Math.max(min, value - 1))} aria-label="إنقاص"><i className="fa-solid fa-minus" /></button>
    <input value={value} inputMode="numeric" onChange={(e) => onChange(Math.max(min, parseInt(e.target.value.replace(/\D/g, '') || '0', 10)))} aria-label="الكمية" />
    <button type="button" onClick={() => onChange(value + 1)} aria-label="زيادة"><i className="fa-solid fa-plus" /></button>
  </div>
);

export const Thumb = ({ sm }) => <div className={`thumb${sm ? ' sm' : ''}`} aria-hidden="true"><i className="fa-solid fa-bag-shopping" /></div>;

export const Seg = ({ options, value, onChange }) => (
  <div className="seg" role="tablist">
    {options.map((o) => (
      <button key={o.value} role="tab" aria-selected={value === o.value} className={value === o.value ? 'is-on' : ''} onClick={() => onChange(o.value)}>
        {o.icon && <i className={`fa-solid ${o.icon}`} />}{o.label}{o.n != null && <span className="seg-n">{o.n}</span>}
      </button>
    ))}
  </div>
);'use client';

