};'use client';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import {
  accountEndpoints,
  checkoutEndpoints,
  type CheckoutPaymentMethod,
  type ShippingOptionsResponse,
  type StoreCity,
  type CheckoutPayload,
} from '@alfarid/api-client';
import { getCartSession, useCartStore } from '@/stores/cart-store';
import { useAuthStore } from '@/store/auth.store';
import { useAuthHydrated } from '@/hooks/use-auth-hydrated';
import { viewerKey } from '@/lib/viewer-key';
import { rememberGuestOrder } from '@/lib/guest-orders';

export interface SavedAddressItem {
  id: number;
  city_id: number;
  address_line: string;
  is_default?: boolean;
  label?: string;
}

export interface CheckoutForm {
  fullName: string;
  phone: string;
  email: string;
  cityId: number | null;
  street: string;
  building: string;
  floor: string;
  apartment: string;
  notes: string;
  paymentMethod: CheckoutPaymentMethod;
  agreeTerms: boolean;
}

const initialForm: CheckoutForm = {
  fullName: '',
  phone: '',
  email: '',
  cityId: null,
  street: '',
  building: '',
  floor: '',
  apartment: '',
  notes: '',
  paymentMethod: 'cod',
  agreeTerms: false,
};

/** Server field -> form field, for 422 mapping. */
const fieldMap: Record<string, keyof CheckoutForm | 'banner'> = {
  recipient_name: 'fullName',
  recipient_phone: 'phone',
  recipient_email: 'email',
  city_id: 'cityId',
  shipping_address_line: 'street',
  shipping_notes: 'notes',
  payment_method: 'paymentMethod',
  expected_total: 'banner',
};

export function buildAddressLine(
  form: Pick<CheckoutForm, 'street' | 'building' | 'floor' | 'apartment'>,
) {
  return [
    form.street.trim(),
    form.building.trim() && `Bldg ${form.building.trim()}`,
    form.floor.trim() && `Floor ${form.floor.trim()}`,
    form.apartment.trim() && `Apt ${form.apartment.trim()}`,
  ]
    .filter(Boolean)
    .join(', ');
}

/**
 * Generate a unique idempotency key with fallback for non-secure HTTP contexts.
 */
export function newIdempotencyKey(): string {
  // Web Crypto randomUUID requires a secure origin; fallback ensures reliability on local networks.
  const generator = globalThis.crypto?.randomUUID;
  if (typeof generator === 'function') {
    return generator.call(globalThis.crypto);
  }
  return `${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

/** Checkout can submit only these methods. Anything else (card, bitcoin) is dropped. */
export function checkoutPaymentMethods(methods: readonly string[]): CheckoutPaymentMethod[] {
  return methods.filter((method): method is CheckoutPaymentMethod =>
    (['cod', 'wallet', 'bank_transfer', 'credit'] as const).includes(method as CheckoutPaymentMethod));
}

/**
 * Display a quote only when it strictly matches the current live cart state and selections.
 *
 * Guards against displaying stale delivery rates while background cart mutations are in flight.
 */
export function shownQuote<T>(quote: T | null, quotedFor: string, quoteKey: string, cartBusy: boolean, cartLoading: boolean): T | null {
  return quotedFor === quoteKey && !cartBusy && !cartLoading ? quote : null;
}

export function useCheckout() {
  const router = useRouter();
  const params = useSearchParams();
  const [form, setForm] = useState<CheckoutForm>(initialForm);
  const [touched, setTouched] = useState<Partial<Record<keyof CheckoutForm, boolean>>>({});
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof CheckoutForm, string>>>({});
  const [banner, setBanner] = useState<{
    kind: 'error' | 'info';
    text: string;
    action?: { label: string; onClick: () => void };
  } | null>(null);
  const [cities, setCities] = useState<StoreCity[] | null>(null);
  const [savedAddresses, setSavedAddresses] = useState<SavedAddressItem[]>([]);
  const [quote, setQuote] = useState<ShippingOptionsResponse | null>(null);
  const [quoteLoading, setQuoteLoading] = useState(false);
  const [citiesError, setCitiesError] = useState(false);
  const [quoteError, setQuoteError] = useState(false);
  const [quoteRevision, refreshQuote] = useState(0);
  const [quotedFor, setQuotedFor] = useState('');
  const [uncertain, setUncertain] = useState(false);
  const submittingRef = useRef(false);
  const pending = useRef<{ body: CheckoutPayload; session: string | null } | null>(null);
  const [promoInput, setPromoInput] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const keyRef = useRef<string>(newIdempotencyKey());
  const promoTried = useRef(false);

  const items = useCartStore((s) => s.items);
  const cartLoading = useCartStore((s) => s.loading);
  const cartBusy = useCartStore((s) => s.busy);
  const cartError = useCartStore((s) => s.error);
  const totals = useCartStore((s) => s.totals);
  const couponCode = useCartStore((s) => s.couponCode);
  const loadCart = useCartStore((s) => s.loadCart);
  const updateQuantity = useCartStore((s) => s.updateQuantity);
  const removeItem = useCartStore((s) => s.removeItem);
  const applyCoupon = useCartStore((s) => s.applyCoupon);
  const removeCoupon = useCartStore((s) => s.removeCoupon);
  const user = useAuthStore((s) => s.user);
  const token = useAuthStore((s) => s.token);
  const hydrated = useAuthHydrated();
  const owner = viewerKey(token);
  const attemptOwner = token
    ? `${useAuthStore.getState().actorType}:${String(user?.id ?? 'unknown')}`
    : 'guest';
  const quoteKey = JSON.stringify([
    owner,
    form.cityId,
    form.paymentMethod,
    couponCode,
    items,
    quoteRevision,
  ]);
  const liveQuote = shownQuote(quote, quotedFor, quoteKey, cartBusy, cartLoading);

  // A reload after a lost response must recover the same attempt, never create a second order.
  useEffect(() => {
    if (!hydrated) return;
    pending.current = null;
    setUncertain(false);
    try {
      const saved = JSON.parse(sessionStorage.getItem('pending_checkout') ?? 'null');
      if (
        saved?.owner === attemptOwner &&
        typeof saved.key === 'string' &&
        saved.body?.city_id &&
        saved.body?.recipient_phone &&
        Number.isFinite(saved.body.expected_total)
      ) {
        keyRef.current = saved.key;
        pending.current = { body: saved.body, session: saved.session ?? null };
        setUncertain(true);
        setBanner({
          kind: 'info',
          text: 'في محاولة طلب سابقة لم يتم تأكيدها. اضغط إعادة المحاولة لتأكيد نفس الطلب.',
        });
        setForm((f) => ({
          ...f,
          fullName: saved.body.recipient_name,
          phone: saved.body.recipient_phone,
          email: saved.body.recipient_email ?? '',
          cityId: saved.body.city_id,
          street: saved.body.shipping_address_line,
          notes: saved.body.shipping_notes ?? '',
          paymentMethod: saved.body.payment_method,
          agreeTerms: true,
        }));
      }
    } catch {
      /* Storage is optional; the in-memory attempt remains safe. */
    }
  }, [hydrated, attemptOwner]);

  const loadCities = useCallback(() => {
    setCitiesError(false);
    setCities(null);
    checkoutEndpoints
      .cities()
      .then(setCities)
      .catch(() => {
        setCities([]);
        setCitiesError(true);
      });
  }, []);

  const set = useCallback(<K extends keyof CheckoutForm>(key: K, value: CheckoutForm[K]) => {
    setForm((f) => ({ ...f, [key]: value }));
    setFieldErrors((e) => ({ ...e, [key]: undefined }));
  }, []);

  const blur = useCallback((key: keyof CheckoutForm) => {
    setTouched((t) => ({ ...t, [key]: true }));
  }, []);

  const applySavedAddress = useCallback((addr: SavedAddressItem) => {
    setForm((f) => ({
      ...f,
      cityId: addr.city_id,
      street: addr.address_line,
    }));
    setFieldErrors((e) => ({ ...e, cityId: undefined, street: undefined }));
  }, []);

  // Prefill contact fields for signed-in shoppers.
  useEffect(() => {
    if (!user) return;
    setForm((f) => ({
      ...f,
      fullName: f.fullName || (user.name as string) || '',
      email: f.email || (user.email as string) || '',
      phone: f.phone || (user.phone as string) || '',
    }));
  }, [user]);

  // Default saved address (first default) for signed-in shoppers, plus list for one-tap switching.
  useEffect(() => {
    if (!token) {
      setSavedAddresses([]);
      return;
    }
    let cancelled = false;
    accountEndpoints
      .addresses()
      .then((list) => {
        if (cancelled || list.length === 0) return;
        setSavedAddresses(list as SavedAddressItem[]);
        const d = list.find((a) => a.is_default) ?? list[0];
        setForm((f) =>
          f.street || f.cityId ? f : { ...f, cityId: d.city_id, street: d.address_line },
        );
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [token]);

  // Initial load: cart + cities in parallel.
  useEffect(() => {
    if (!hydrated) return;
    loadCart();
    loadCities();
  }, [hydrated, owner, loadCart, loadCities]);

  const addressLine = useMemo(() => buildAddressLine(form), [form]);

  // Live quote: city / payment method / coupon / cart changes (debounced 300ms).
  useEffect(() => {
    if (!hydrated || form.cityId === null || cartBusy || cartLoading) {
      setQuote(null);
      setQuoteLoading(false);
      return;
    }
    let current = true;
    const controller = new AbortController();
    setQuote(null);
    setQuoteError(false);
    setQuoteLoading(true);
    const t = setTimeout(() => {
      checkoutEndpoints
        .shippingOptions(
          { city_id: form.cityId as number, payment_method: form.paymentMethod },
          getCartSession(),
          controller.signal,
        )
        .then((res) => {
          if (!current) return;
          const allowed = checkoutPaymentMethods(res.payment_methods);
          if (!allowed.includes(form.paymentMethod) && allowed.length) {
            setForm((f) => ({ ...f, paymentMethod: allowed[0] as CheckoutPaymentMethod }));
            return;
          }
          setQuote(res);
          setQuotedFor(quoteKey);
        })
        .catch(() => {
          if (current) setQuoteError(true);
        })
        .finally(() => {
          if (current) setQuoteLoading(false);
        });
    }, 300);
    return () => {
      current = false;
      clearTimeout(t);
      controller.abort();
    };
  }, [quoteKey, hydrated, cartBusy, cartLoading, form.cityId, form.paymentMethod]);

  // ?promo=CODE auto-applies once.
  useEffect(() => {
    if (promoTried.current || !hydrated || cartLoading || !totals) return;
    const code = params.get('promo');
    if (!code) return;
    promoTried.current = true;
    setPromoInput(code);
    applyCoupon(code).then((ok) => {
      if (!ok) {
        setBanner({
          kind: 'error',
          text: useCartStore.getState().error || 'كود الخصم غير صالح أو منتهي.',
        });
      }
    });
  }, [params, hydrated, cartLoading, totals, applyCoupon]);

  const errors = useMemo(() => {
    const e: Partial<Record<keyof CheckoutForm, string>> = {};
    if (!form.fullName.trim()) e.fullName = 'الاسم مطلوب';
    if (!form.phone.trim()) e.phone = 'رقم الموبايل مطلوب';
    else if (!/^[0-9+\s().-]{7,}$/.test(form.phone.trim())) e.phone = 'رقم موبايل غير صالح';
    if (form.email.trim() && !/^\S+@\S+\.\S+$/.test(form.email.trim())) {
      e.email = 'بريد إلكتروني غير صالح';
    }
    if (form.cityId === null) e.cityId = 'اختار المدينة';
    if (!form.street.trim()) e.street = 'العنوان مطلوب';
    if (!form.agreeTerms) e.agreeTerms = 'لازم توافق على الشروط عشان تكمل الطلب';
    return e;
  }, [form]);

  const visibleErrors = useMemo(() => {
    const out: typeof errors = {};
    (Object.keys({ ...errors, ...fieldErrors }) as (keyof CheckoutForm)[]).forEach((k) => {
      if (touched[k] || fieldErrors[k]) out[k] = fieldErrors[k] ?? errors[k];
    });
    return out;
  }, [errors, touched, fieldErrors]);

  const validate = useCallback(() => {
    setTouched({
      fullName: true,
      phone: true,
      email: true,
      cityId: true,
      street: true,
      agreeTerms: true,
    });
    if (Object.keys(errors).length > 0) {
      requestAnimationFrame(() =>
        document.querySelector<HTMLElement>('[data-checkout-error="true"]')?.focus(),
      );
      return false;
    }
    return true;
  }, [errors]);

  const handleError = useCallback(
    (err: unknown) => {
      const status = (
        err as {
          response?: {
            status?: number;
            headers?: Record<string, string>;
            data?: { message?: string; errors?: Record<string, string[]>; code?: string };
          };
        }
      )?.response;
      const code = status?.data?.code;
      if (code === 'price_changed') {
        loadCart();
        setQuote(null);
        refreshQuote((v) => v + 1);
        setBanner({
          kind: 'error',
          text: 'الأسعار اتحدثت، راجع الإجمالي واضغط إتمام الطلب تاني.',
        });
        return;
      }
      if (code === 'coupon_invalid') {
        setBanner({
          kind: 'error',
          text: status?.data?.message || 'الكوبون مبقاش صالح.',
          action: {
            label: 'إزالة الكوبون',
            onClick: () => {
              removeCoupon();
              setBanner(null);
            },
          },
        });
        return;
      }
      if (status?.status === 429) {
        const retry = status.headers?.['retry-after'] ?? 60;
        setBanner({ kind: 'error', text: `محاولات كتيرة، حاول بعد ${retry} ثانية.` });
        return;
      }
      if (status?.status === 422) {
        const apiErrors = status.data?.errors ?? {};
        const mapped: Partial<Record<keyof CheckoutForm, string>> = {};
        Object.entries(apiErrors).forEach(([key, messages]) => {
          const target = fieldMap[key];
          if (target && target !== 'banner' && messages?.[0]) mapped[target] = messages[0];
        });
        if (Object.keys(mapped).length > 0) {
          setFieldErrors(mapped);
          setTouched((t) => ({
            ...t,
            ...Object.fromEntries(Object.keys(mapped).map((k) => [k, true])),
          }));
          setTimeout(
            () =>
              document
                .querySelector('[data-checkout-error="true"]')
                ?.scrollIntoView({ behavior: 'smooth', block: 'center' }),
            50,
          );
          return;
        }
      }
      setBanner({ kind: 'error', text: status?.data?.message || 'حصل خطأ، حاول تاني.' });
    },
    [loadCart, removeCoupon],
  );

  const submit = useCallback(async () => {
    if (submittingRef.current) return;
    if (
      !pending.current &&
      (!validate() || !liveQuote?.preview || cartBusy || cartLoading || items.length === 0)
    ) {
      return;
    }
    if (!pending.current && items.some((i) => !i.priced || i.quantity > i.available)) {
      setBanner({
        kind: 'error',
        text: 'في منتجات مش متاحة بالكمية دي، شيلها أو قلل الكمية الأول.',
      });
      return;
    }
    if (
      !pending.current &&
      (form.cityId === null || !liveQuote?.payment_methods.includes(form.paymentMethod))
    ) {
      return;
    }
    submittingRef.current = true;
    setSubmitting(true);
    try {
      pending.current ??= {
        body: {
          recipient_name: form.fullName.trim(),
          recipient_phone: form.phone.trim(),
          recipient_email: form.email.trim() || undefined,
          city_id: form.cityId!,
          shipping_address_line: addressLine,
          shipping_notes: form.notes.trim() || undefined,
          payment_method: form.paymentMethod,
          expected_total: liveQuote!.preview!.grand_total,
        },
        session: getCartSession(),
      };
      try {
        sessionStorage.setItem(
          'pending_checkout',
          JSON.stringify({ owner: attemptOwner, key: keyRef.current, ...pending.current }),
        );
      } catch {
        /* In-memory retry still uses the same key. */
      }
      const res = await checkoutEndpoints.place(
        pending.current.body,
        pending.current.session,
        keyRef.current,
      );
      if (attemptOwner === 'guest') rememberGuestOrder(res.data.order_number);
      try {
        sessionStorage.setItem('last_order', JSON.stringify(res.data));
      } catch {
        /* Receipt storage must never turn a successful order into a retry. */
      }
      pending.current = null;
      try {
        sessionStorage.removeItem('pending_checkout');
      } catch {
        /* Optional storage. */
      }
      setUncertain(false);
      await loadCart();
      router.replace(`/checkout/success?order=${encodeURIComponent(res.data.order_number)}`);
    } catch (e) {
      handleError(e);
      const status = (e as { response?: { status: number } }).response?.status;
      // Network errors and server failures may have committed the order. Retry the exact request and key.
      if (
        status &&
        status >= 400 &&
        status < 500 &&
        status !== 408 &&
        status !== 409 &&
        status !== 429
      ) {
        pending.current = null;
        try {
          sessionStorage.removeItem('pending_checkout');
        } catch {
          /* Optional storage. */
        }
        setUncertain(false);
        keyRef.current = newIdempotencyKey();
      } else {
        setUncertain(true);
        const retryAfter = (e as { response?: { headers?: Record<string, string> } }).response
          ?.headers?.['retry-after'];
        setBanner({
          kind: 'error',
          text:
            'تعذّر تأكيد نتيجة الطلب. اضغط إعادة المحاولة لتأكيد نفس الطلب بدون تكراره.' +
            (status === 429 ? ` محاولات كتيرة، حاول بعد ${retryAfter ?? 60} ثانية.` : ''),
        });
      }
    } finally {
      submittingRef.current = false;
      setSubmitting(false);
    }
  }, [
    validate,
    items,
    form,
    addressLine,
    liveQuote,
    cartBusy,
    cartLoading,
    loadCart,
    router,
    handleError,
    attemptOwner,
  ]);

  const step =
    !form.fullName.trim() || !form.phone.trim()
      ? 1
      : form.cityId === null || !form.street.trim()
        ? 2
        : 3;

  return {
    form,
    set,
    blur,
    visibleErrors,
    fieldErrors,
    banner,
    setBanner,
    cities,
    citiesError,
    loadCities,
    savedAddresses,
    applySavedAddress,
    quote: liveQuote,
    quoteLoading,
    quoteError,
    retryQuote: () => refreshQuote((v) => v + 1),
    locked: submitting || uncertain,
    canSubmit:
      !submitting &&
      (uncertain ||
        (!!liveQuote?.preview &&
          !!liveQuote.options.length &&
          liveQuote.payment_methods.includes(form.paymentMethod) &&
          !cartBusy &&
          !cartLoading &&
          items.length > 0)),
    uncertain,
    promoInput,
    setPromoInput,
    items,
    cartLoading,
    cartBusy,
    cartError,
    totals,
    couponCode,
    updateQuantity,
    removeItem,
    applyCoupon,
    removeCoupon,
    loadCart,
    submit,
    submitting,
    step,
    addressLine,
    user,
    token,
  };
}

export type CheckoutVM = ReturnType<typeof useCheckout>;'use client';

import React, { useState, useEffect, useRef } from 'react';
import Link from 'next/link';
import { usePathname, useRouter } from 'next/navigation';
import { useCartStore } from '@/stores/cart-store';
import { SophieCartDrawer } from './SophieCartDrawer';
import { SophieMegaDropdown } from './SophieMegaDropdown';
import { SophieProfileDropdown } from './SophieProfileDropdown';
import { useAuthStore } from '@/store/auth.store';
import type { Destination } from '@/types/auth';
import { authEndpoints } from '@alfarid/api-client';
import { logoutWeb } from '@/services/auth.service';
import { prefetchMegaMenu, useMegaMenu } from '@/hooks/useMegaMenu';
import { toProfileVM } from '@/lib/sophie-mappers';
import { STORE_ROUTES } from '@/lib/store-routes';
import { BrandLogo, useBranding } from '@alfarid/ui/branding';

export function SophieHeader() {
  const pathname = usePathname();
  const router = useRouter();
  const [searchOpen, setSearchOpen] = useState(false);
  const [search, setSearch] = useState('');
  const { branding } = useBranding();
  const [cartOpen, setCartOpen] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [mounted, setMounted] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const mobileMenuRef = useRef<HTMLDivElement>(null);

  // Mega dropdown state
  const [megaOpen, setMegaOpen] = useState(false);
  const [megaDept, setMegaDept] = useState<string | null>(null);
  const [mobileDept, setMobileDept] = useState<string | null>(null);
  const megaCloseTimer = useRef<NodeJS.Timeout | null>(null);
  const megaOpenTimer = useRef<NodeJS.Timeout | null>(null);
  const { departments, error: menuError, retry: retryMenu } = useMegaMenu();
  const deptKeys = departments ? Object.keys(departments) : [];
  const firstDept = deptKeys[0] ?? null;
  const currentDepartment = () => {
    const category = new URL(window.location.href).searchParams.get('category');
    return deptKeys.find((key) => key === category || [departments![key].col1, departments![key].col2, departments![key].col3]
      .flat().some((group) => group.slug === category || group.links.some((link) => link.slug === category))) ?? firstDept;
  };

  const items = useCartStore((s) => s.items);
  const cartCount = items.reduce((total, item) => total + item.quantity, 0);

  const user = useAuthStore((s) => s.user);
  const token = useAuthStore((s) => s.token);
  const destination = useAuthStore((s) => s.destination);
  const actorType = useAuthStore((s) => s.actorType);
  void actorType;
  const isAuthed = mounted && !!token;
  const isCheckoutPage = pathname.startsWith('/checkout');

  useEffect(() => {
    setMounted(true);
    return () => {
      if (megaCloseTimer.current) clearTimeout(megaCloseTimer.current);
      if (megaOpenTimer.current) clearTimeout(megaOpenTimer.current);
    };
  }, []);

  const openFromKeyboard = (event: React.KeyboardEvent<HTMLAnchorElement>) => {
    if (event.key !== 'ArrowDown') return;
    event.preventDefault();
    if (megaOpenTimer.current) clearTimeout(megaOpenTimer.current);
    setMegaDept(currentDepartment()); setMegaOpen(true);
    requestAnimationFrame(() => document.querySelector<HTMLButtonElement>('#mega-dropdown button[role="tab"]')?.focus());
  };

  useEffect(() => {
    setMobileMenuOpen(false);
    setSearchOpen(false);
    setMegaOpen(false);
  }, [pathname]);

  // Keep keyboard navigation inside the sheet, then return to its trigger.
  useEffect(() => {
    if (!mobileMenuOpen) return;
    const previousFocus = document.activeElement as HTMLElement | null;
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    mobileMenuRef.current?.focus();
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { event.preventDefault(); setMobileMenuOpen(false); }
      if (event.key !== 'Tab') return;
      const controls = Array.from(mobileMenuRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled)') ?? [])
        .filter(control => control.getClientRects().length > 0);
      const first = controls[0], last = controls[controls.length - 1];
      if (!first) { event.preventDefault(); return; }
      if (event.shiftKey && (document.activeElement === first || document.activeElement === mobileMenuRef.current)) {
        event.preventDefault(); last.focus();
      } else if (!event.shiftKey && (document.activeElement === last || document.activeElement === mobileMenuRef.current)) {
        event.preventDefault(); first.focus();
      }
    };
    const keepFocus = (event: FocusEvent) => {
      if (!mobileMenuRef.current?.contains(event.target as Node)) mobileMenuRef.current?.focus();
    };
    const desktop = window.matchMedia('(min-width: 1024px)');
    const onResize = (event: MediaQueryListEvent) => { if (event.matches) setMobileMenuOpen(false); };
    desktop.addEventListener('change', onResize);
    document.addEventListener('keydown', onKey);
    document.addEventListener('focusin', keepFocus);
    return () => {
      document.body.style.overflow = prevOverflow;
      desktop.removeEventListener('change', onResize);
      document.removeEventListener('keydown', onKey);
      document.removeEventListener('focusin', keepFocus);
      previousFocus?.focus();
    };
  }, [mobileMenuOpen]);

  useEffect(() => {
    if (searchOpen) {
      requestAnimationFrame(() => searchInputRef.current?.focus());
    }
  }, [searchOpen]);

  const handleOpenMega = (dept: string | null) => {
    if (megaCloseTimer.current) clearTimeout(megaCloseTimer.current);
    if (megaOpenTimer.current) clearTimeout(megaOpenTimer.current);
    // Hover intent: only open after 120ms so passing cursors don't trigger it.
    megaOpenTimer.current = setTimeout(() => {
      setMegaDept(currentDepartment() ?? dept);
      setMegaOpen(true);
    }, 120);
  };

  const handleScheduleCloseMega = () => {
    if (megaOpenTimer.current) clearTimeout(megaOpenTimer.current);
    megaCloseTimer.current = setTimeout(() => {
      setMegaOpen(false);
    }, 220);
  };

  const handleCancelCloseMega = () => {
    if (megaCloseTimer.current) clearTimeout(megaCloseTimer.current);
  };

  const handleProfileAction = async (actionId: string) => {
    if (actionId === 'signout') { await logoutWeb('/'); return; }
    const routes: Record<string, string> = { profile: '/account', orders: '/account/orders', wallet: '/account/wallet', returns: '/account/returns' };
    if (routes[actionId]) router.push(routes[actionId]);
  };

  const handleSearchSubmit = (event: React.FormEvent) => {
    event.preventDefault();
    router.push(STORE_ROUTES.shop({ search: search.trim() }));
    setSearchOpen(false);
    setMobileMenuOpen(false);
  };

  // Warm the menu cache after load so it opens instantly on first hover.
  useEffect(() => {
    const w = window as unknown as { requestIdleCallback?: (cb: () => void) => number };
    if (typeof w.requestIdleCallback === 'function') {
      w.requestIdleCallback(() => prefetchMegaMenu());
    } else {
      const t = setTimeout(() => prefetchMegaMenu(), 2000);
      return () => clearTimeout(t);
    }
  }, []);

  // Session is valid 24h: revalidate once on mount when a token exists.
  // On 401 the global setUnauthorizedHandler clears the session by itself.
  useEffect(() => {
    if (!mounted || !token) return;
    let cancelled = false;
    authEndpoints.me().then((res: any) => {
      if (cancelled) return;
      useAuthStore.setState({
        user: (res?.data as Record<string, unknown>) ?? null,
        destination: (res?.redirect?.destination as Destination | null) ?? null,
        home: (res?.redirect?.path as string | null) ?? null,
      });
    }).catch(() => {});
    return () => { cancelled = true; };
  }, [mounted, token]);

  return (
    <>
      <header
        data-store-header
        className="store-header flex items-center justify-between gap-2 py-3 sm:py-5 lg:py-6 relative z-30"
        onMouseLeave={handleScheduleCloseMega}
        onMouseEnter={handleCancelCloseMega}
      >
        {/* Brand Logo */}
        <Link
          href="/"
          title={branding.name}
          className="flex items-center gap-2 min-w-0 min-h-[44px] font-['Poppins'] text-xl sm:text-2xl font-bold tracking-tight text-black"
        >
          <BrandLogo
            className="w-6 h-6 shrink-0"
            fallback={
              <svg className="w-6 h-6 shrink-0" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <polygon points="2,12 20,3 14,21 10,14 2,12" fill="#000" />
                <line x1="20" y1="3" x2="10" y2="14" stroke="#fff" strokeWidth="1.5" />
              </svg>
            }
          />
          <span dir="auto" className="truncate max-w-[125px] min-[380px]:max-w-[165px] sm:max-w-[220px]">
            {branding.name}
          </span>
        </Link>

        {/* Desktop Navigation */}
        <nav aria-label="Main navigation" className="hidden lg:flex items-center gap-7 xl:gap-8 font-['Oswald'] text-[13px] font-medium tracking-wide uppercase">
          <Link
            href="/"
            aria-current={pathname === '/' ? 'page' : undefined}
            className="py-2 transition-colors hover:text-[#4f7d88]"
          >
            Home
          </Link>

          {/* Shop with Mega Dropdown */}
          <div
            className="relative"
            onMouseEnter={() => handleOpenMega(firstDept)}
          >
            <Link
              href="/shop"
              aria-current={pathname === '/shop' ? 'page' : undefined}
              onClick={(e) => {
                if (window.innerWidth >= 1024 && !e.metaKey && !e.ctrlKey && !e.shiftKey && !e.altKey) {
                  e.preventDefault();
                  setMegaDept(currentDepartment());
                  setMegaOpen((prev) => !prev);
                }
              }}
              aria-controls="mega-dropdown"
              aria-expanded={megaOpen}
              onKeyDown={openFromKeyboard}
              className="py-2 text-[#111] hover:text-[#4f7d88] transition-colors flex items-center gap-1.5"
            >
              Shop
              <svg
                className={`w-2.5 h-2.5 text-gray-500 transition-transform ${megaOpen ? 'rotate-180' : ''}`}
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" />
              </svg>
            </Link>
          </div>

          {/* Categories with Mega Dropdown */}
          <div
            className="relative"
            onMouseEnter={() => handleOpenMega(firstDept)}
          >
            <Link
              href="/categories"
              aria-current={pathname === '/categories' ? 'page' : undefined}
              onClick={(e) => {
                if (window.innerWidth >= 1024 && !e.metaKey && !e.ctrlKey && !e.shiftKey && !e.altKey) {
                  e.preventDefault();
                  setMegaDept(currentDepartment());
                  setMegaOpen((prev) => !prev);
                }
              }}
              aria-controls="mega-dropdown"
              aria-expanded={megaOpen}
              onKeyDown={openFromKeyboard}
              className="py-2 text-[#111] hover:text-[#4f7d88] transition-colors flex items-center gap-1.5"
            >
              Categories
              <svg
                className={`w-2.5 h-2.5 text-gray-500 transition-transform ${megaOpen ? 'rotate-180' : ''}`}
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" />
              </svg>
            </Link>
          </div>

          {/* Offers: direct link (no discount sort in the catalog API, so no columns) */}
          <Link
            href={STORE_ROUTES.shop()}
            className="py-2 text-[#c93b2e] hover:text-[#a82e23] transition-colors uppercase font-medium"
          >
            Offers
          </Link>

          <a href={STORE_ROUTES.shop({ sort: 'newest' })} className="py-2 text-[#111] hover:text-[#4f7d88] transition-colors">
            New Arrivals
          </a>

          {mounted && !isAuthed && (
            <Link href="/orders/track" className="py-2 text-[#111] hover:text-[#4f7d88] transition-colors">
              Track Order
            </Link>
          )}
        </nav>

        {/* Right Icons: Search, Profile Dropdown / Sign in, Cart, Mobile Menu Toggle */}
        <div className="flex items-center gap-1 sm:gap-2.5 lg:gap-4 text-[15px] text-black shrink-0">
          {/* Search Trigger */}
          <button
            type="button"
            aria-label="Search"
            aria-expanded={searchOpen}
            onClick={() => setSearchOpen(!searchOpen)}
            className="w-11 h-11 inline-flex items-center justify-center rounded-full hover:bg-gray-100 hover:text-[#4f7d88] transition-colors"
          >
            <svg className="w-[18px] h-[18px]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <circle cx="10.5" cy="10.5" r="6.5" />
              <path d="m16 16 5 5" />
            </svg>
          </button>

          {/* Sophie Profile Avatar Dropdown (authed) or Sign in (guest) */}
          {!mounted ? (
            <span className="hidden sm:inline-block w-9 h-9 rounded-full bg-gray-100 animate-pulse" aria-hidden />
          ) : isAuthed ? (
            <SophieProfileDropdown user={toProfileVM(user, destination)} onSelectAction={handleProfileAction} />
          ) : (
            <Link
              href={`/auth/login?redirect=${encodeURIComponent(pathname)}`}
              className="font-['Oswald'] text-[13px] uppercase tracking-wide hover:text-[#4f7d88] px-2 py-2 min-h-[44px] hidden sm:inline-flex items-center transition-colors"
            >
              Sign in
            </Link>
          )}

          {/* Cart Icon & Badge */}
          <button
            type="button"
            onClick={() => setCartOpen(true)}
            className="flex items-center gap-1.5 hover:bg-gray-100 hover:text-[#4f7d88] transition-colors px-2 py-2 min-h-[44px] rounded-full relative"
            aria-label="Shopping Cart"
          >
            <svg className="w-[18px] h-[18px]" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
            </svg>
            <span
              data-cart-count
              className="bg-black text-white font-['Poppins'] text-[10px] font-semibold min-w-[18px] h-[18px] px-1 rounded-full inline-flex items-center justify-center"
            >
              {mounted ? cartCount : 0}
            </span>
          </button>

          {/* Mobile Menu Toggle Button */}
          <button
            type="button"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="lg:hidden w-11 h-11 inline-flex items-center justify-center rounded-full text-black hover:bg-gray-100 hover:text-[#4f7d88] transition-colors"
            aria-controls="mobile-store-menu"
            aria-label="Toggle navigation menu"
            aria-expanded={mobileMenuOpen}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              {mobileMenuOpen ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              )}
            </svg>
          </button>
        </div>

        {/* Longacres-Inspired Mega Dropdown for Shop & Categories */}
        <SophieMegaDropdown
          isOpen={megaOpen}
          defaultDept={megaDept}
          departments={departments}
          error={menuError}
          onRetry={retryMenu}
          onClose={() => setMegaOpen(false)}
          onSelectCategory={(slug: string) => router.push(slug ? STORE_ROUTES.shop({ category: slug }) : STORE_ROUTES.shop())}
          onAddToCart={() => setCartOpen(true)}
        />
      </header>

      {/* Header Search Box */}
      {searchOpen && (
        <form
          className="store-header-search"
          role="search"
          onSubmit={handleSearchSubmit}
        >
          <input
            ref={searchInputRef}
            autoFocus
            type="search"
            inputMode="search"
            enterKeyHint="search"
            autoComplete="off"
            aria-label="Search bags"
            placeholder="Search bags, collections, or styles…"
            value={search}
            maxLength={100}
            onChange={(event) => setSearch(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Escape') setSearchOpen(false);
            }}
          />
          {search && (
            <button
              type="button"
              onClick={() => {
                setSearch('');
                searchInputRef.current?.focus();
              }}
              aria-label="Clear search query"
              className="store-header-search-clear"
            >
              ×
            </button>
          )}
          <button type="submit">Search</button>
          <button
            type="button"
            onClick={() => setSearchOpen(false)}
            aria-label="Close search"
            className="store-header-search-close"
          >
            Cancel
          </button>
        </form>
      )}

      {/* Mobile Navigation Drawer & Backdrop */}
      {mobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 z-50 flex flex-col justify-end sm:justify-start">
          <div
            className="fixed inset-0 bg-black/45 backdrop-blur-[2px] transition-opacity"
            onClick={() => setMobileMenuOpen(false)}
            aria-hidden="true"
          />
          <div
            id="mobile-store-menu"
            ref={mobileMenuRef}
            tabIndex={-1}
            role="dialog"
            aria-modal="true"
            aria-label="Mobile navigation menu"
            className="store-mobile-menu relative z-10 w-full max-h-[86dvh] bg-white rounded-t-2xl sm:rounded-t-none sm:rounded-b-xl border-t sm:border border-gray-100 shadow-2xl flex flex-col overflow-hidden focus:outline-none"
          >
            {/* Mobile Sheet Grab Handle & Header */}
            <div className="pt-2.5 pb-2 px-4 border-b border-gray-100 flex items-center justify-between bg-white">
              <span className="font-['Oswald'] text-sm font-semibold uppercase tracking-wider text-gray-900">
                Browse Store
              </span>
              <button
                type="button"
                onClick={() => setMobileMenuOpen(false)}
                aria-label="Close navigation menu"
                className="w-10 h-10 inline-flex items-center justify-center rounded-full text-gray-500 hover:text-black hover:bg-gray-100 transition-colors"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {/* Quick Mobile Search Inside Drawer */}
            <form onSubmit={handleSearchSubmit} className="px-4 py-3 border-b border-gray-100 bg-gray-50/70 flex items-center gap-2">
              <input
                type="search"
                inputMode="search"
                enterKeyHint="search"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                placeholder="Search bags…"
                aria-label="Search bags"
                className="flex-1 min-w-0 h-11 px-3.5 rounded-lg border border-gray-200 bg-white text-base text-gray-900 placeholder:text-gray-400 focus:border-[#4f7d88] focus:outline-none"
              />
              <button
                type="submit"
                className="h-11 px-4 rounded-lg bg-black text-white font-['Oswald'] text-xs uppercase tracking-wider shrink-0 hover:bg-[#2c2c2c] transition-colors"
              >
                Search
              </button>
            </form>

            {/* Scrollable Navigation Links & Department Accordions */}
            <div className="flex-1 min-h-0 overflow-y-auto overscroll-contain px-4 py-3 space-y-1 font-['Oswald'] uppercase text-sm tracking-wide">
              <Link
                href="/"
                onClick={() => setMobileMenuOpen(false)}
                aria-current={pathname === '/' ? 'page' : undefined}
                className={`flex items-center justify-between py-3 px-2 rounded-lg transition-colors ${pathname === '/' ? 'text-[#4f7d88] bg-[#f0f7f8] font-semibold' : 'text-gray-800 hover:bg-gray-50'}`}
              >
                <span>Home</span>
              </Link>
              <Link
                href="/shop"
                onClick={() => setMobileMenuOpen(false)}
                aria-current={pathname === '/shop' ? 'page' : undefined}
                className={`flex items-center justify-between py-3 px-2 rounded-lg transition-colors ${pathname === '/shop' ? 'text-[#4f7d88] bg-[#f0f7f8] font-semibold' : 'text-gray-800 hover:bg-gray-50'}`}
              >
                <span>Shop All Collections</span>
              </Link>
              <Link
                href="/categories"
                onClick={() => setMobileMenuOpen(false)}
                aria-current={pathname === '/categories' ? 'page' : undefined}
                className={`flex items-center justify-between py-3 px-2 rounded-lg transition-colors ${pathname === '/categories' ? 'text-[#4f7d88] bg-[#f0f7f8] font-semibold' : 'text-gray-800 hover:bg-gray-50'}`}
              >
                <span>All Categories</span>
              </Link>

              {/* Departments accordion from the same live menu data */}
              {menuError && (
                <p role="alert" className="py-2 px-2 text-xs text-red-700 font-['Poppins'] normal-case">
                  تعذّر تحميل الأقسام.{' '}
                  <button type="button" onClick={retryMenu} className="underline font-semibold ml-1">
                    إعادة المحاولة
                  </button>
                </p>
              )}
              {deptKeys.map((key) => {
                const dept = departments![key];
                const expanded = mobileDept === key;
                return (
                  <div key={key} className="border-t border-gray-100 pt-1">
                    <button
                      type="button"
                      aria-expanded={expanded}
                      onClick={() => setMobileDept(expanded ? null : key)}
                      className="flex w-full items-center justify-between py-3 px-2 rounded-lg text-gray-800 hover:text-[#4f7d88] hover:bg-gray-50 transition-colors"
                    >
                      <span>{dept.name}</span>
                      <span
                        aria-hidden="true"
                        className="w-7 h-7 rounded-full bg-gray-100 inline-flex items-center justify-center text-base leading-none text-gray-600"
                      >
                        {expanded ? '−' : '+'}
                      </span>
                    </button>
                    {expanded && (
                      <div className="pb-3 pl-3 pr-1 space-y-2.5 normal-case font-['Poppins']">
                        {[dept.col1, dept.col2, dept.col3].flat().map((group) => (
                          <div key={group.slug} className="bg-gray-50/70 rounded-lg p-2.5">
                            <Link
                              href={STORE_ROUTES.shop({ category: group.slug })}
                              onClick={() => setMobileMenuOpen(false)}
                              className="block py-1.5 text-gray-900 hover:text-[#4f7d88] font-semibold text-[13.5px]"
                            >
                              {group.title}
                            </Link>
                            <div className="grid grid-cols-1 min-[380px]:grid-cols-2 gap-1 mt-1">
                              {group.links.map((link) => (
                                <Link
                                  key={link.slug}
                                  href={STORE_ROUTES.shop({ category: link.slug })}
                                  onClick={() => setMobileMenuOpen(false)}
                                  className="flex items-center justify-between py-2 px-2 rounded-md text-gray-600 hover:text-[#4f7d88] hover:bg-white text-[13px] transition-colors"
                                >
                                  <span className="truncate">{link.label}</span>
                                  <span className="text-gray-500 text-[11px] ml-1.5 shrink-0">({link.count})</span>
                                </Link>
                              ))}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}

              <div className="border-t border-gray-100 pt-1 space-y-1">
                <Link
                  href={STORE_ROUTES.shop()}
                  onClick={() => setMobileMenuOpen(false)}
                  className="flex items-center justify-between py-3 px-2 rounded-lg text-[#c93b2e] hover:bg-red-50/60"
                >
                  <span>Offers</span>
                </Link>
                <a
                  href={STORE_ROUTES.shop({ sort: 'newest' })}
                  onClick={() => setMobileMenuOpen(false)}
                  className="flex items-center justify-between py-3 px-2 rounded-lg text-gray-800 hover:text-[#4f7d88] hover:bg-gray-50"
                >
                  <span>New Arrivals</span>
                </a>
                {mounted && !isAuthed && (
                  <Link href="/orders/track" onClick={() => setMobileMenuOpen(false)}
                    className="flex items-center justify-between rounded-lg px-2 py-3 text-gray-800 hover:bg-gray-50">
                    Track Order
                  </Link>
                )}
              </div>
            </div>

            {/* Thumb-Friendly Sticky Drawer Footer */}
            <div className="p-4 border-t border-gray-100 bg-gray-50 flex items-center gap-3 pb-[calc(1rem+env(safe-area-inset-bottom,0px))]">
              <button
                type="button"
                onClick={() => {
                  setMobileMenuOpen(false);
                  setCartOpen(true);
                }}
                className="flex-1 min-h-[46px] rounded-lg border border-gray-300 bg-white text-gray-900 font-['Oswald'] text-xs uppercase tracking-wider inline-flex items-center justify-center gap-2 hover:bg-gray-100 transition-colors"
              >
                <span>Cart ({mounted ? cartCount : 0})</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* One-Handed Mobile Bottom Navigation Bar (Hidden on desktop and checkout where checkout bar is shown) */}
      {!isCheckoutPage && (
        <nav
          aria-label="Mobile quick navigation"
          className="mobile-bottom-nav lg:hidden"
        >
          <Link
            href="/"
            aria-current={pathname === '/' && !mobileMenuOpen && !searchOpen ? 'page' : undefined}
            onClick={() => {
              setMobileMenuOpen(false);
              setSearchOpen(false);
            }}
            className={`mobile-bottom-nav-item ${pathname === '/' && !mobileMenuOpen && !searchOpen ? 'is-active' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5.5v-6h-5v6H4a1 1 0 0 1-1-1v-9.5Z" />
            </svg>
            <span>Home</span>
          </Link>

          <button
            type="button"
            aria-expanded={mobileMenuOpen}
            onClick={() => {
              setSearchOpen(false);
              setMobileMenuOpen((prev) => !prev);
            }}
            className={`mobile-bottom-nav-item ${mobileMenuOpen || pathname.startsWith('/categories') || pathname.startsWith('/shop') ? 'is-active' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
              <rect x="3" y="3" width="7" height="7" rx="1.5" />
              <rect x="14" y="3" width="7" height="7" rx="1.5" />
              <rect x="3" y="14" width="7" height="7" rx="1.5" />
              <rect x="14" y="14" width="7" height="7" rx="1.5" />
            </svg>
            <span>Shop</span>
          </button>

          <button
            type="button"
            aria-expanded={searchOpen}
            onClick={() => {
              setMobileMenuOpen(false);
              setSearchOpen((prev) => !prev);
            }}
            className={`mobile-bottom-nav-item ${searchOpen ? 'is-active' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
              <circle cx="10.5" cy="10.5" r="6.5" />
              <path strokeLinecap="round" d="m16 16 5 5" />
            </svg>
            <span>Search</span>
          </button>

          <button
            type="button"
            onClick={() => {
              setMobileMenuOpen(false);
              setCartOpen(true);
            }}
            className={`mobile-bottom-nav-item relative ${cartOpen ? 'is-active' : ''}`}
          >
            <span className="relative inline-flex">
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
                <path strokeLinecap="round" strokeLinejoin="round" d="M16 11V7a4 4 0 00-8 0v4M5 9h14l1 12H4L5 9z" />
              </svg>
              {mounted && cartCount > 0 && (
                <span className="mobile-bottom-nav-badge" aria-hidden="true">
                  {cartCount > 99 ? '99+' : cartCount}
                </span>
              )}
            </span>
            <span>Cart</span>
          </button>

          <Link
            href={isAuthed ? '/account' : `/auth/login?redirect=${encodeURIComponent(pathname)}`}
            onClick={() => {
              setMobileMenuOpen(false);
              setSearchOpen(false);
            }}
            className={`mobile-bottom-nav-item ${pathname.startsWith('/account') || pathname.startsWith('/auth') ? 'is-active' : ''}`}
          >
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.8} aria-hidden="true">
              <path strokeLinecap="round" strokeLinejoin="round" d="M15.75 6a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0ZM4.5 20.25a7.5 7.5 0 0 1 15 0" />
            </svg>
            <span>{isAuthed ? 'Account' : 'Sign In'}</span>
          </Link>
        </nav>
      )}

      {/* Slide-out Cart Drawer */}
      <SophieCartDrawer isOpen={cartOpen} onClose={() => setCartOpen(false)} />
    </>
  );
}

export default SophieHeader;'use client';

import React, { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { formatStorePrice } from '@alfarid/utils';
import { useCartStore } from '@/stores/cart-store';
import { SophieBagPlaceholder } from './SophieBagPlaceholder';
import { StoreImage } from '../StoreImage';

export interface SophieProduct {
  id: number;
  variantId?: number;
  slug?: string;
  name: string;
  price: number;
  oldPrice?: number;
  badge?: string;
  imgUrl: string | null;
  badgeTone?: 'default' | 'sale' | 'muted';
  href?: string;
  inStock?: boolean;
  tintClass?: string;
  category?: string;
}

export function SophieProductCard({ product }: { product: SophieProduct }) {
  const addItem = useCartStore((s) => s.addItem);
  const [added, setAdded] = useState(false);
  const addedTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const alive = useRef(true);
  useEffect(() => {
    alive.current = true;
    return () => { alive.current = false; if (addedTimer.current) clearTimeout(addedTimer.current); };
  }, []);
  const [adding, setAdding] = useState(false);
  const busy = useCartStore((s) => s.busy);
  const cartError = useCartStore((s) => s.error);
  const [addFailed, setAddFailed] = useState(false);
  const [failedImage, setFailedImage] = useState<string | null>(null);
  const image = product.imgUrl && failedImage !== product.imgUrl ? (
    <StoreImage
      src={product.imgUrl}
      alt={product.name}
      onError={() => setFailedImage(product.imgUrl)}
      className={`${product.tintClass || ''} max-w-full sm:max-w-[175px] max-h-[155px] sm:max-h-[200px] object-contain transition-transform duration-300 group-hover:scale-105 ${product.inStock === false ? 'opacity-60' : ''}`}
      loading="lazy"
    />
  ) : <SophieBagPlaceholder />;

  const handleAddToCart = async () => {
    if (!product.variantId || busy) return;
    setAdding(true);
    setAddFailed(false);
    const saved = await addItem(product.variantId);
    if (!alive.current) return;
    setAdding(false);
    setAdded(saved);
    setAddFailed(!saved);
    if (addedTimer.current) clearTimeout(addedTimer.current);
    if (saved) addedTimer.current = setTimeout(() => setAdded(false), 1600);
  };

  return (
    <div className="product-card text-center group flex flex-col h-full">
      {/* Image Box */}
      <div className="bg-[#f3f4f6] relative h-[180px] min-[380px]:h-[210px] sm:h-[260px] flex items-center justify-center p-4 sm:p-6 mb-3 overflow-hidden transition-all duration-300 group-hover:bg-[#ebeef2]">
        {/* Badge */}
        {product.badge && (
          <span
            className={`absolute top-0 left-0 ${
              product.badgeTone === 'sale' ? 'bg-[#111]' : product.badgeTone === 'muted' ? 'bg-[#6b7280]' : 'bg-[#4f7d86]'
            } text-white font-['Oswald'] text-[10px] font-medium uppercase px-2.5 py-1 tracking-[0.5px] z-10`}
          >
            {product.badge}
          </span>
        )}

        {/* Product Image */}
        {product.href ? (
          <Link href={product.href} aria-label={product.name} className="flex items-center justify-center w-full h-full">
            {image}
          </Link>
        ) : (
          image
        )}

        {/* Quick Add Overlay on Desktop Hover / Accessible Touch Action */}
        {product.inStock !== false && product.variantId && (
          <div className="absolute inset-x-0 bottom-0 p-2 sm:p-3 bg-gradient-to-t from-black/25 via-black/10 to-transparent opacity-100 lg:opacity-0 lg:group-hover:opacity-100 focus-within:opacity-100 transition-opacity flex items-center justify-center">
            <button
              type="button"
              onClick={handleAddToCart}
              disabled={busy}
              aria-live="polite"
              aria-label={`Add ${product.name} to cart`}
              className={`font-['Oswald'] text-[11px] uppercase tracking-wider min-h-[44px] py-1.5 px-4 rounded-xs shadow-sm transition-all duration-200 active:scale-[0.98] ${
                added ? 'bg-emerald-600 text-white' : 'bg-black text-white hover:bg-neutral-800'
              }`}
            >
              {adding ? 'Adding…' : added ? '✓ Added' : '+ Add to Cart'}
            </button>
          </div>
        )}
      </div>

      {/* Product Name */}
      <h3
        dir="auto"
        className="font-['Oswald'] text-[15px] sm:text-[13.5px] font-medium text-[#222] mb-1 tracking-[0.2px] hover:text-[#4f7d88] transition-colors line-clamp-2 leading-snug"
      >
        {product.href ? (
          <Link href={product.href} className="py-0.5 inline-block">
            {product.name}
          </Link>
        ) : (
          product.name
        )}
      </h3>

      {/* Product Price */}
      <p className="font-['Oswald'] text-[16px] sm:text-[14px] font-semibold text-[#111] mt-auto flex flex-wrap items-baseline justify-center gap-x-1">
        {product.oldPrice && (
          <span className="text-[#767676] line-through font-normal mr-1.5 text-[12.5px]">
            {formatStorePrice(product.oldPrice)}
          </span>
        )}
        <span>{formatStorePrice(product.price)}</span>
      </p>
      {addFailed && cartError && (
        <p role="alert" className="text-xs text-red-700 mt-1.5">
          {cartError}
        </p>
      )}
    </div>
  );
}/* Sophie Luxury Bag Collection Stylesheet */

/* Accessible Skip-to-Content Link */
.skip-to-content {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 9999;
  background-color: #111111;
  color: #ffffff;
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  padding: 10px 18px;
  border-radius: 4px;
  text-decoration: none;
  transform: translateY(-150%);
  transition: transform 0.2s ease;
}

.skip-to-content:focus {
  transform: translateY(0);
  outline: 2px solid #159a8c;
  outline-offset: 2px;
}

/* Storefront Shell & Sticky Header Bar */
.store-page-shell {
  --store-bottom-space: 0px;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

@media (max-width: 1023px) {
  .store-page-shell {
    --store-bottom-space: calc(64px + env(safe-area-inset-bottom, 0px));
    padding-bottom: var(--store-bottom-space);
  }
  .store-page-shell.is-checkout {
    --store-bottom-space: 0px;
  }
}

.store-header-shell {
  position: sticky;
  top: 0;
  z-index: 40;
  /* A filter here would make fixed navigation and drawers relative to the header. */
  background-color: #ffffff;
  border-bottom: 1px solid rgba(226, 232, 240, 0.75);
}

.store-header-inner {
  max-width: 1140px;
  margin: 0 auto;
  padding-left: max(1rem, env(safe-area-inset-left, 0px));
  padding-right: max(1rem, env(safe-area-inset-right, 0px));
}

@media (min-width: 640px) {
  .store-header-inner {
    padding-left: max(1.25rem, env(safe-area-inset-left, 0px));
    padding-right: max(1.25rem, env(safe-area-inset-right, 0px));
  }
}

/* Header Search Form */
.store-header-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 0 14px;
  border-top: 1px solid #f1f5f9;
  position: relative;
  flex-wrap: wrap;
}

.store-header-search input {
  flex: 1;
  flex-basis: 180px;
  min-width: 0;
  min-height: 44px;
  padding: 8px 14px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  background-color: #f8fafc;
  font-family: 'Poppins', sans-serif;
  font-size: 16px;
  color: #111111;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

@media (min-width: 768px) {
  .store-header-search input {
    font-size: 14px;
  }
}

.store-header-search input:focus {
  background-color: #ffffff;
  border-color: #4f7d88;
  outline: none;
}

.store-header-search button[type="submit"] {
  min-height: 44px;
  padding: 0 18px;
  border: none;
  border-radius: 6px;
  background-color: #111111;
  color: #ffffff;
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color 0.2s ease;
}

.store-header-search button[type="submit"]:hover {
  background-color: #159a8c;
}

.store-header-search-clear {
  min-width: 44px;
  min-height: 44px;
  border: none;
  border-radius: 50%;
  background: #e2e8f0;
  color: #334155;
  font-size: 16px;
  line-height: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  flex-shrink: 0;
}

.store-header-search-close {
  min-height: 44px;
  padding: 0 10px;
  border: none;
  background: transparent;
  color: #475569;
  font-family: 'Poppins', sans-serif;
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  flex-shrink: 0;
}

.store-header-search-close:hover {
  color: #111111;
}

.store-header > a:first-child {
  flex: 1 1 auto;
  overflow: hidden;
}

.store-mobile-menu {
  padding-top: env(safe-area-inset-top, 0px);
  padding-inline: env(safe-area-inset-left, 0px) env(safe-area-inset-right, 0px);
}

.store-cart-panel {
  height: 100dvh;
  padding-top: env(safe-area-inset-top, 0px);
  padding-inline: env(safe-area-inset-left, 0px) env(safe-area-inset-right, 0px);
}

.store-cart-panel > :first-child,
.store-cart-panel > :last-child:not(:first-child) {
  flex-shrink: 0;
}

@media (max-width: 639px) {
  .store-header-search input {
    flex-basis: calc(100% - 56px);
  }
  .store-header-search button[type="submit"] {
    flex: 1;
  }
}

@media (max-width: 1023px) {
  /* Keep the keyboard area free while a form is being completed. */
  .store-page-shell:has(input:focus, textarea:focus, select:focus) .mobile-bottom-nav {
    display: none;
  }
  #checkout-view:has(input:focus, textarea:focus, select:focus) .checkout-mobile-bar {
    display: none;
  }
}

/* One-Handed Mobile Bottom Navigation Bar */
.mobile-bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 45;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  align-items: stretch;
  background-color: rgba(255, 255, 255, 0.98);
  backdrop-filter: blur(10px);
  border-top: 1px solid #e2e8f0;
  padding-bottom: env(safe-area-inset-bottom, 0px);
  padding-left: env(safe-area-inset-left, 0px);
  padding-right: env(safe-area-inset-right, 0px);
  box-shadow: 0 -4px 20px rgba(15, 23, 42, 0.06);
}

@media (min-width: 1024px) {
  .mobile-bottom-nav {
    display: none;
  }
}

.mobile-bottom-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  min-height: 56px;
  padding: 6px 2px;
  background: transparent;
  border: none;
  color: #475569;
  font-family: 'Oswald', sans-serif;
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  text-decoration: none;
  cursor: pointer;
  position: relative;
  transition: color 0.18s ease, background-color 0.18s ease;
}

.mobile-bottom-nav-item:active {
  background-color: #f1f5f9;
}

.mobile-bottom-nav-item.is-active {
  color: #111111;
  font-weight: 600;
}

.mobile-bottom-nav-item.is-active::before {
  content: '';
  position: absolute;
  top: 0;
  left: 25%;
  right: 25%;
  height: 2.5px;
  background-color: #159a8c;
  border-radius: 0 0 3px 3px;
}

.mobile-bottom-nav-badge {
  position: absolute;
  top: -5px;
  right: -9px;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background-color: #159a8c;
  color: #ffffff;
  font-family: 'Poppins', sans-serif;
  font-size: 9.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

/* Color tint filters for product photos */
.tint-pink {
  filter: sepia(0.25) saturate(1.4) hue-rotate(315deg) brightness(1.03);
}

.tint-black {
  filter: grayscale(1) brightness(0.35) contrast(1.4);
}

.tint-beige {
  filter: sepia(0.35) saturate(0.85) brightness(1.02);
}

.tint-blue {
  filter: sepia(0.2) saturate(1.2) hue-rotate(165deg) brightness(1.02);
}

.tint-cream {
  filter: sepia(0.18) saturate(0.6) brightness(1.08);
}

/* Hero Section Backdrop and Ambient Lighting */
.hero-wrapper {
  background-color: #dfe5e9;
  position: relative;
  overflow: hidden;
}

.hero-bg-backdrop {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}

.hero-bg-backdrop-img {
  position: absolute;
  top: -8%;
  right: 0;
  width: 60%;
  height: 116%;
  filter: blur(14px) brightness(0.96) saturate(1.25);
  opacity: 0.75;
  transform: scale(1.08);
  transition: transform 0.6s ease;
}

.hero-bg-backdrop-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    #dfe5e9 0%,
    rgba(223, 229, 233, 0.95) 38%,
    rgba(223, 229, 233, 0.6) 65%,
    rgba(223, 229, 233, 0.2) 100%
  );
}

.hero-foreground-img {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  filter: drop-shadow(0 20px 26px rgba(0, 0, 0, 0.2));
  transition: transform 0.4s ease;
}

.hero-foreground-img:hover {
  transform: translateY(-8px) scale(1.02);
}

/* Footer Skyline */
.footer-skyline {
  display: block;
  width: 100%;
  line-height: 0;
  overflow: hidden;
  background-color: #ffffff;
}

.footer-skyline svg {
  display: block;
  width: 100%;
  height: 78px;
}

@media (max-width: 992px) {
  .hero-bg-backdrop-img {
    width: 100%;
    height: 100%;
    top: 0;
    opacity: 0.55;
  }
  .hero-bg-backdrop-overlay {
    background: linear-gradient(
      180deg,
      #dfe5e9 0%,
      rgba(223, 229, 233, 0.94) 45%,
      rgba(223, 229, 233, 0.5) 100%
    );
  }
}

@media (max-width: 576px) {
  .footer-skyline svg {
    height: 46px;
  }
}

/* Balanced responsive hero space without excessive vertical voids on mobile */
.hero-wrapper .sophie-hero-content {
  min-height: 400px;
}
.hero-wrapper .sophie-hero-content.is-fallback-slide {
  min-height: 540px;
}
@media (min-width: 640px) {
  .hero-wrapper .sophie-hero-content {
    min-height: 460px;
  }
  .hero-wrapper .sophie-hero-content.is-fallback-slide {
    min-height: 640px;
  }
}
@media (min-width: 1024px) {
  .hero-wrapper .sophie-hero-content,
  .hero-wrapper .sophie-hero-content.is-fallback-slide {
    min-height: 475px;
  }
}

.sophie-skeleton {
  background: linear-gradient(90deg, #eceef1 0%, #f6f7f8 50%, #eceef1 100%);
  background-size: 200% 100%;
  animation: sophieShimmer 1.4s ease-in-out infinite;
}

@keyframes sophieShimmer {
  from { background-position: 200% 0; }
  to { background-position: -200% 0; }
}

.hero-banner-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: right center;
  animation: heroFade 0.6s ease;
}

.hero-banner-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, #dfe5e9 0%, rgba(223, 229, 233, 0.88) 32%, rgba(223, 229, 233, 0) 62%);
}

@media (max-width: 1023px) {
  .hero-banner-overlay {
    background: linear-gradient(0deg, #dfe5e9 0%, rgba(223, 229, 233, 0.92) 48%, rgba(223, 229, 233, 0.25) 100%);
  }
}

@keyframes heroFade {
  from { opacity: 0; }
  to { opacity: 1; }
}

.sophie-pop-in {
  animation: sophiePop 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
}

@keyframes sophiePop {
  from { opacity: 0; transform: translateY(12px) scale(0.97); }
  to { opacity: 1; transform: none; }
}

.hero-wrapper :focus-visible,
.products-section :focus-visible,
.sophie-pop-in :focus-visible {
  outline: 2px solid #4f7d88;
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .sophie-skeleton,
  .hero-banner-img,
  .sophie-pop-in,
  .hero-foreground-img {
    animation: none;
    transition: none;
  }
}


/* ==========================================================================
   SOPHIE PROFILE DROPDOWN, MEGA MENU & CHECKOUT EXTENSION
   ========================================================================== */

/* Profile Trigger & Dropdown */
.profile-menu-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.profile-avatar-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  padding: 2px;
  background: #ffffff;
  border: 2px solid #f59e0b;
  box-shadow: 0 0 0 2px rgba(245, 158, 11, 0.2);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
  overflow: hidden;
}

.profile-avatar-btn:hover,
.profile-menu-wrap.is-open .profile-avatar-btn {
  transform: scale(1.05);
  box-shadow: 0 0 0 4px rgba(245, 158, 11, 0.28);
}

.profile-avatar-inner {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background: linear-gradient(135deg, #f97316 0%, #fb923c 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.profile-avatar-inner img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Profile Dropdown Card */
.profile-dropdown-card {
  position: absolute;
  top: calc(100% + 12px);
  right: 0;
  width: 248px;
  max-width: calc(100vw - 24px);
  background-color: #ffffff;
  border-radius: 22px;
  border: 1px solid #eef0f3;
  box-shadow: 0 22px 50px rgba(15, 23, 42, 0.13), 0 4px 14px rgba(15, 23, 42, 0.05);
  padding: 18px 14px 16px;
  z-index: 160;
  opacity: 0;
  visibility: hidden;
  transform: translateY(8px) scale(0.98);
  pointer-events: none;
  transition: opacity 0.22s cubic-bezier(0.16, 1, 0.3, 1),
              transform 0.22s cubic-bezier(0.16, 1, 0.3, 1),
              visibility 0.22s;
}

.profile-menu-wrap.is-open .profile-dropdown-card {
  opacity: 1;
  visibility: visible;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

/* Diagonal 25% OFF Ribbon on Top-Right Corner */
.profile-ribbon-wrap {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 84px;
  height: 84px;
  overflow: hidden;
  pointer-events: auto;
  z-index: 5;
}

.profile-ribbon {
  position: absolute;
  top: 16px;
  right: -24px;
  width: 112px;
  padding: 4px 0;
  background: linear-gradient(135deg, #ffe0c8 0%, #ffc099 100%);
  color: #b44d12;
  font-family: 'Poppins', sans-serif;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
  transform: rotate(42deg);
  box-shadow: 0 3px 8px rgba(217, 99, 32, 0.18);
  border: 1px solid rgba(245, 148, 92, 0.45);
  cursor: pointer;
  letter-spacing: 0.2px;
  transition: filter 0.2s ease;
}

.profile-ribbon:hover {
  filter: brightness(0.97);
}

.profile-menu-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.profile-menu-item {
  display: flex;
  align-items: center;
  gap: 13px;
  width: 100%;
  min-height: 44px;
  padding: 11px 14px;
  border-radius: 12px;
  border: none;
  background: transparent;
  font-family: 'Poppins', sans-serif;
  font-size: 13.5px;
  font-weight: 500;
  color: #18181b;
  text-align: left;
  cursor: pointer;
  transition: background-color 0.18s ease, color 0.18s ease, transform 0.15s ease;
}

.profile-menu-item i,
.profile-menu-item svg {
  width: 18px;
  font-size: 15px;
  color: #52525b;
  text-align: center;
  flex-shrink: 0;
  transition: color 0.18s ease;
}

.profile-menu-item:hover {
  background-color: #f4f4f5;
  color: #000000;
}

.profile-menu-item.highlighted {
  background-color: #f3f4f6;
  font-weight: 600;
}

.profile-menu-item.highlighted i {
  color: #18181b;
}

.profile-menu-item.highlighted:hover {
  background-color: #e5e7eb;
}

.profile-menu-divider {
  height: 1px;
  background-color: #e5e7eb;
  margin: 8px 10px;
}

.profile-identity {
  padding: 14px 14px 10px;
  border-bottom: 1px solid #f1f5f9;
  margin-bottom: 6px;
}

.profile-identity-name {
  font-family: 'Poppins', sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: #18181b;
  margin: 0 0 2px;
}

.profile-identity-email {
  font-size: 12.5px;
  color: #52525b;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-identity-wallet {
  font-size: 12.5px;
  font-weight: 600;
  color: #3d646e;
  margin: 6px 0 0;
}

.profile-menu-item.sign-out {
  color: #52525b;
  font-weight: 500;
}

.profile-menu-item.sign-out i {
  color: #52525b;
}

.profile-menu-item.sign-out:hover {
  background-color: #fef2f2;
  color: #dc2626;
}

.profile-menu-item.sign-out:hover i {
  color: #dc2626;
}

/* ================= LONGACRES-INSPIRED MEGA DROPDOWN ================= */
.mega-dropdown-wrapper {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  z-index: 120;
  opacity: 0;
  visibility: hidden;
  transform: translateY(4px);
  pointer-events: none;
  transition: opacity 0.15s ease,
              transform 0.15s ease,
              visibility 0.15s;
}

.mega-link-count {
  color: #64748b;
  font-size: 11px;
  margin-left: 6px;
}

.mega-skel-title,
.mega-skel-link {
  border-radius: 4px;
  background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
  background-size: 200% 100%;
  animation: mega-skel 1.2s ease-in-out infinite;
}

.mega-skel-title {
  height: 14px;
  width: 60%;
  margin: 12px 0 10px;
}

.mega-skel-link {
  height: 12px;
  width: 85%;
  margin: 0 0 8px;
}

@keyframes mega-skel {
  to { background-position: -200% 0; }
}

.mega-spotlight-skel-img {
  height: 150px;
  border-radius: 4px;
  background: linear-gradient(90deg, #f1f5f9 25%, #e2e8f0 50%, #f1f5f9 75%);
  background-size: 200% 100%;
  animation: mega-skel 1.2s ease-in-out infinite;
}

.mega-btn-spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #fff;
  border-radius: 50%;
  animation: mega-spin 0.7s linear infinite;
  vertical-align: -2px;
  margin-right: 6px;
}

@keyframes mega-spin {
  to { transform: rotate(360deg); }
}

@media (prefers-reduced-motion: reduce) {
  .mega-dropdown-wrapper,
  .mega-dept-tab,
  .mega-add-cart-btn {
    transition: none;
  }
  .mega-skel-title,
  .mega-skel-link,
  .mega-spotlight-skel-img,
  .mega-btn-spinner {
    animation: none;
  }
}

.mega-dropdown-wrapper.is-open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  pointer-events: auto;
}

.mega-dropdown-card {
  background-color: #ffffff;
  border-radius: 4px;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.14), 0 4px 16px rgba(15, 23, 42, 0.05);
  border: 1px solid rgba(226, 232, 240, 0.9);
  overflow: hidden;
}

.mega-dept-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 42px;
  border-bottom: 1px solid #f1f5f9;
  background-color: #ffffff;
}

.mega-dept-tabs {
  display: flex;
  align-items: center;
  gap: 28px;
  overflow-x: auto;
  scrollbar-width: none;
}

.mega-dept-tabs::-webkit-scrollbar {
  display: none;
}

.mega-dept-tab {
  background: none;
  border: none;
  font-family: 'Poppins', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: #334155;
  padding: 16px 4px 15px;
  min-height: 48px;
  cursor: pointer;
  position: relative;
  white-space: nowrap;
  transition: color 0.2s ease;
}

.mega-dept-tab::after {
  content: '';
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0;
  height: 3px;
  background-color: #159a8c;
  border-radius: 3px 3px 0 0;
  transition: width 0.25s ease;
}

.mega-dept-tab:hover,
.mega-dept-tab.active {
  color: #0f172a;
}

.mega-dept-tab.active::after {
  width: 100%;
}

.mega-dept-tab.offers-tab {
  color: #c93b2e;
}

.mega-dept-tab.offers-tab.active,
.mega-dept-tab.offers-tab:hover {
  color: #a82e23;
}

.mega-dept-tab.offers-tab::after {
  background-color: #c93b2e;
}

.mega-close-btn {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  color: #475569;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  cursor: pointer;
  transition: all 0.2s ease;
  flex-shrink: 0;
}

.mega-close-btn:hover {
  background: #f1f5f9;
  color: #0f172a;
  transform: scale(1.05);
}

.mega-body {
  display: grid;
  grid-template-columns: repeat(3, 1fr) 275px;
  gap: 32px;
  padding: 34px 42px 38px;
  background-color: #ffffff;
  align-items: start;
}

.mega-col {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.mega-group-title {
  font-family: 'Poppins', sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 8px;
  letter-spacing: -0.1px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.mega-group-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.mega-link {
  font-family: 'Poppins', sans-serif;
  font-size: 13px;
  font-weight: 400;
  color: #475569;
  line-height: 1.5;
  padding: 3px 0;
  transition: color 0.18s ease, transform 0.18s ease;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: none;
}

.mega-link:hover {
  color: #159a8c;
  transform: translateX(3px);
}

.mega-link-tag {
  font-size: 9.5px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 3px;
  background-color: #e6f6f4;
  color: #0f766e;
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.mega-link-tag.hot {
  background-color: #fef2f2;
  color: #dc2626;
}

.mega-spotlight {
  display: flex;
  flex-direction: column;
}

.mega-spotlight-img-wrap {
  position: relative;
  background-color: #f4f6f8;
  border-radius: 4px;
  height: 205px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  overflow: hidden;
  margin-bottom: 14px;
}

.mega-spotlight-img-wrap img {
  max-width: 165px;
  max-height: 170px;
  object-fit: contain;
  mix-blend-mode: multiply;
  transition: transform 0.35s ease;
}

.mega-spotlight:hover .mega-spotlight-img-wrap img {
  transform: scale(1.06);
}

.mega-special-badge {
  position: absolute;
  top: 12px;
  left: 12px;
  background-color: #d93832;
  color: #ffffff;
  font-family: 'Poppins', sans-serif;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  padding: 4px 10px;
  border-radius: 4px;
  z-index: 2;
  box-shadow: 0 2px 6px rgba(217, 56, 50, 0.28);
}

.mega-spotlight-title {
  font-family: 'Poppins', sans-serif;
  font-size: 14px;
  font-weight: 500;
  color: #334155;
  margin-bottom: 4px;
}

.mega-spotlight-price {
  font-family: 'Poppins', sans-serif;
  font-size: 15.5px;
  font-weight: 700;
  color: #1e293b;
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.mega-spotlight-price .old-price {
  font-size: 13px;
  font-weight: 400;
  color: #64748b;
  text-decoration: line-through;
}

.mega-add-cart-btn {
  width: 100%;
  min-height: 44px;
  background-color: #159a8c;
  color: #ffffff;
  border: none;
  border-radius: 999px;
  padding: 12px 20px;
  font-family: 'Poppins', sans-serif;
  font-size: 13px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.15s ease, box-shadow 0.2s ease;
  box-shadow: 0 6px 16px rgba(21, 154, 140, 0.22);
}

.mega-add-cart-btn:hover {
  background-color: #118276;
  transform: translateY(-1px);
  box-shadow: 0 8px 20px rgba(21, 154, 140, 0.3);
}

.mega-footer {
  background-color: #f8fafc;
  border-top: 1px solid #f1f5f9;
  padding: 12px 42px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 12px;
  color: #475569;
}

.mega-footer-perks {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px 24px;
}

.mega-footer-perks span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.mega-footer-perks i {
  color: #159a8c;
}

.mega-footer-cta {
  font-weight: 600;
  color: #0f766e;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  transition: gap 0.2s ease;
  text-decoration: none;
  cursor: pointer;
  background: none;
  border: none;
  font-family: inherit;
  font-size: inherit;
}

.mega-footer-cta:hover {
  gap: 8px;
}

/* ================= CHECKOUT PAGE VIEW ================= */
.checkout-wrapper {
  background-color: #f3f5f7;
  padding: 32px 0 90px;
  min-height: 75vh;
}

@media (max-width: 1023px) {
  .checkout-wrapper {
    padding: 24px 0 calc(110px + env(safe-area-inset-bottom, 0px));
  }
}

.checkout-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 32px;
  flex-wrap: wrap;
  gap: 12px 16px;
}

.checkout-giant-title {
  font-family: 'Oswald', sans-serif;
  font-size: clamp(2.15rem, 8vw, 4rem);
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #111111;
  line-height: 1.05;
}

.back-to-shop-btn {
  background: none;
  border: 1px solid #cbd5e1;
  min-height: 42px;
  padding: 8px 18px;
  border-radius: 999px;
  font-family: 'Poppins', sans-serif;
  font-size: 12px;
  font-weight: 500;
  color: #334155;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s ease;
  text-decoration: none;
}

.back-to-shop-btn:hover {
  background-color: #111111;
  color: #ffffff;
  border-color: #111111;
}

.checkout-grid {
  display: grid;
  grid-template-columns: 1.22fr 0.95fr;
  gap: 76px;
  align-items: start;
}

/* Checkout Left Column: Forms */
.checkout-block {
  margin-bottom: 36px;
}

.checkout-block-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

.checkout-section-heading {
  font-family: 'Poppins', sans-serif;
  font-size: 19px;
  font-weight: 600;
  color: #111111;
  letter-spacing: -0.3px;
}

.checkout-login-prompt {
  font-size: 12px;
  color: #64748b;
}

.checkout-login-prompt button {
  background: none;
  border: none;
  color: #111111;
  font-weight: 600;
  text-decoration: underline;
  cursor: pointer;
  font-family: inherit;
  font-size: inherit;
  min-height: 36px;
  padding: 4px 2px;
}

.checkout-subheading {
  font-size: 13px;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 16px;
}

.checkout-fields-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 24px;
  row-gap: 18px;
  margin-bottom: 24px;
}

.line-input-wrap {
  position: relative;
  min-width: 0;
}

.line-input {
  width: 100%;
  min-height: 44px;
  background: transparent;
  border: none;
  border-bottom: 1.5px solid #cbd5e1;
  padding: 10px 0;
  font-family: 'Poppins', sans-serif;
  font-size: 16px;
  color: #111111;
  outline: none;
  transition: border-color 0.2s ease;
}

@media (min-width: 768px) {
  .line-input {
    font-size: 13.5px;
  }
}

.line-input::placeholder {
  color: #64748b;
}

.line-input:focus {
  border-bottom-color: #159a8c;
}

.checkout-checkbox-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 44px;
  padding: 6px 0;
  font-size: 12.5px;
  color: #475569;
  margin-top: 6px;
  cursor: pointer;
}

.checkout-checkbox-row input[type="checkbox"] {
  accent-color: #111111;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
  cursor: pointer;
}

.checkout-checkbox-row span a {
  text-decoration: underline;
  color: #1e293b;
}

/* Delivery & Payment Radio Rows */
.radio-list {
  display: flex;
  flex-direction: column;
}

.radio-option-row {
  border-bottom: 1px solid #cbd5e1;
  padding: 14px 0;
}

.radio-option-label {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  min-height: 44px;
  cursor: pointer;
  width: 100%;
}

.radio-left {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-width: 0;
}

.radio-left input[type="radio"] {
  accent-color: #111111;
  width: 18px;
  height: 18px;
  margin-top: 2px;
  flex-shrink: 0;
  cursor: pointer;
}

.radio-title {
  font-size: 13px;
  font-weight: 600;
  color: #111111;
  display: block;
}

.radio-desc {
  font-size: 11.5px;
  color: #64748b;
  display: block;
  margin-top: 2px;
}

.radio-price {
  font-size: 13px;
  font-weight: 600;
  color: #111111;
  flex-shrink: 0;
}

.payment-brands {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 18px;
}

.cc-fields-panel {
  padding: 18px 0 8px;
}

.cc-fields-panel.hidden {
  display: none;
}

.btn-place-order {
  width: 100%;
  min-height: 48px;
  background-color: #1a1a1a;
  color: #ffffff;
  border: none;
  padding: 15px 24px;
  font-family: 'Oswald', sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 1px;
  text-transform: uppercase;
  cursor: pointer;
  margin-top: 24px;
  transition: background-color 0.2s ease, transform 0.15s ease;
}

.btn-place-order:hover {
  background-color: #159a8c;
  transform: translateY(-1px);
}

/* Checkout Right Column: Shopping Bag Summary */
.bag-summary-panel {
  position: sticky;
  top: 100px;
}

.bag-items-list {
  display: flex;
  flex-direction: column;
  margin-top: 20px;
}

.bag-item-row {
  display: grid;
  grid-template-columns: 84px 1fr auto;
  gap: 16px;
  padding: 18px 0;
  border-bottom: 1px solid #cbd5e1;
  align-items: start;
}

@media (max-width: 420px) {
  .bag-item-row {
    grid-template-columns: 68px 1fr auto;
    gap: 12px;
  }
}

.bag-item-row:first-child {
  padding-top: 0;
}

.bag-item-thumb {
  width: 100%;
  max-width: 84px;
  height: 96px;
  background-color: #e4e9ed;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px;
  border-radius: 4px;
}

.bag-item-thumb img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  mix-blend-mode: multiply;
}

.bag-item-info {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.bag-item-title {
  font-size: 13.5px;
  font-weight: 600;
  color: #111111;
}

.bag-item-meta {
  display: grid;
  grid-template-columns: 64px 1fr;
  row-gap: 4px;
  font-size: 11.5px;
  align-items: center;
}

.bag-item-meta .meta-label {
  color: #64748b;
}

.bag-item-meta .meta-val {
  color: #1e293b;
  font-weight: 600;
}

.qty-stepper {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.qty-btn {
  width: 34px;
  height: 34px;
  border-radius: 6px;
  border: 1px solid #cbd5e1;
  background: #ffffff;
  color: #111111;
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.15s ease, color 0.15s ease;
}

@media (min-width: 1024px) {
  .qty-btn {
    width: 28px;
    height: 28px;
    font-size: 12px;
  }
}

.qty-btn:hover {
  background: #111111;
  color: #ffffff;
  border-color: #111111;
}

.bag-item-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  height: 100%;
}

.bag-item-price {
  font-size: 13.5px;
  font-weight: 600;
  color: #111111;
}

.bag-remove-btn {
  background: none;
  border: none;
  color: #64748b;
  font-size: 11.5px;
  min-height: 36px;
  padding: 6px 4px;
  cursor: pointer;
  margin-top: 16px;
  transition: color 0.18s ease;
}

.bag-remove-btn:hover {
  color: #dc2626;
}

/* Promocode Row */
.promo-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: end;
  margin: 22px 0 26px;
}

.btn-apply-promo {
  min-height: 44px;
  background-color: #dfe5e9;
  color: #1e293b;
  border: none;
  padding: 11px 18px;
  font-family: 'Oswald', sans-serif;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.btn-apply-promo:hover {
  background-color: #111111;
  color: #ffffff;
}

/* Summary Totals */
.bag-totals-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid #cbd5e1;
  font-size: 12.5px;
  color: #334155;
}

.bag-totals-row strong {
  color: #111111;
  font-weight: 600;
}

.bag-grand-total {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-top: 18px;
  font-size: 18px;
  font-weight: 600;
  color: #111111;
}

.bag-grand-total .total-amount {
  font-family: 'Poppins', sans-serif;
  font-size: 22px;
  font-weight: 700;
}

/* Order Confirmation Modal */
.order-modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 500;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  padding: 16px;
}

.order-modal-backdrop.open {
  opacity: 1;
  visibility: visible;
}

.order-modal-card {
  background: #ffffff;
  max-width: 440px;
  width: 100%;
  border-radius: 16px;
  padding: 28px 24px;
  text-align: center;
  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.22);
}

@media (min-width: 640px) {
  .order-modal-card {
    padding: 36px 32px;
  }
}

.order-modal-icon {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: #e6f6f4;
  color: #159a8c;
  font-size: 24px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}

.order-modal-title {
  font-family: 'Oswald', sans-serif;
  font-size: 24px;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.order-modal-desc {
  font-size: 13px;
  color: #475569;
  line-height: 1.6;
  margin-bottom: 24px;
}

/* Toast Notification */
.toast-notice {
  position: fixed;
  bottom: 26px;
  right: 26px;
  background-color: #0f172a;
  color: #ffffff;
  padding: 12px 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.22);
  z-index: 999;
  opacity: 0;
  transform: translateY(15px);
  pointer-events: none;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

@media (max-width: 1023px) {
  .toast-notice {
    left: 16px;
    right: 16px;
    bottom: calc(74px + env(safe-area-inset-bottom, 0px));
    border-radius: 14px;
    justify-content: space-between;
  }
}

.toast-notice.show {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.toast-notice i {
  color: #159a8c;
}

.toast-checkout-btn {
  background-color: #159a8c;
  color: #ffffff;
  border: none;
  border-radius: 999px;
  min-height: 34px;
  padding: 6px 14px;
  font-family: 'Poppins', sans-serif;
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  flex-shrink: 0;
}

/* Media Queries */
@media (max-width: 992px) {
  .mega-body {
    grid-template-columns: repeat(2, 1fr);
    padding: 24px;
  }
  .mega-dept-bar,
  .mega-footer {
    padding-left: 24px;
    padding-right: 24px;
  }
  .checkout-grid {
    grid-template-columns: 1fr;
    gap: 36px;
  }
}

@media (max-width: 576px) {
  .mega-body,
  .checkout-fields-grid {
    grid-template-columns: 1fr;
  }
}

/* ================= REAL-DATA CHECKOUT ADDITIONS ================= */
.checkout-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 18px;
  list-style: none;
  margin: 0 0 24px;
  padding: 0;
  font-family: 'Oswald', sans-serif;
  font-size: 12.5px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.checkout-step {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #64748b;
}

.checkout-step-dot {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  border: 1px solid #cbd5e1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  flex-shrink: 0;
}

.checkout-step.is-current {
  color: #111827;
}

.checkout-step.is-current .checkout-step-dot {
  border-color: #4f7d88;
  color: #4f7d88;
}

.checkout-step.is-done {
  color: #3d646e;
}

.checkout-step.is-done .checkout-step-dot {
  background: #4f7d88;
  border-color: #4f7d88;
  color: #fff;
}

.checkout-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  border-radius: 6px;
  padding: 12px 16px;
  margin-bottom: 18px;
  font-size: 13.5px;
}

.checkout-banner.is-error {
  background: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}

.checkout-banner.is-info {
  background: #f0f9fa;
  color: #2c545e;
  border: 1px solid #cce3e8;
}

@media (min-width: 1024px) {
  .checkout-summary-sticky {
    position: sticky;
    top: 104px;
    align-self: start;
  }
}

.checkout-submit-btn {
  width: 100%;
  margin-top: 20px;
}

.checkout-submit-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.checkout-mobile-bar {
  display: none;
}

@media (max-width: 1023px) {
  .checkout-mobile-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    z-index: 30;
    background: rgba(255, 255, 255, 0.98);
    backdrop-filter: blur(8px);
    border-top: 1px solid #e5e7eb;
    padding: 12px max(16px, env(safe-area-inset-right, 0px)) calc(12px + env(safe-area-inset-bottom, 0px)) max(16px, env(safe-area-inset-left, 0px));
